def analyze(path, marker, title):
    txt=open(path).read()
    i=txt.find(marker)
    chunk=txt[i:i+8000] if i>=0 else txt
    lines=chunk.splitlines()
    for idx,l in enumerate(lines):
        if title in l:
            col=l.find(title[0]) if False else None
            # find border char before title
            m=re.search(r"[┌╭]([^\s].*?)[─]",l)
            print(path, marker, "lineidx",idx,"line len stripped r?",len(l.rstrip()), "raw",repr(l))
            break

# simpler: use captures from running? We'll parse known files manually by scanning for dialog titles
