from tui import *
import tempfile, os, json
tmp=tempfile.mkdtemp()
backend=os.path.join(tmp,"entries.json")
open(backend,"w").write(json.dumps([{"id":0,"date":"2023-06-15T10:30:00Z","title":"First","content":"Hello","tags":["work"],"priority":3}]))
def rect(title):
    c=cap("s1")
    lines=c.splitlines()
    for y,l in enumerate(lines):
        if title in l and ("┌" in l or "╭" in l):
            x=min(i for i,ch in enumerate(l) if ch in "┌╭")
            end=max(l.rfind("┐"),l.rfind("╮"))
            bot=None
            for yy in range(y, len(lines)):
                if len(lines[yy])>x and lines[yy][x] in "└╰":
                    bot=yy; break
            return (x,end-x+1,y,bot-y+1 if bot else None)
    return None

for rows in [20,24,30,35,40,45,50,60]:
    start("s1",["-j",backend],tmp,cols=120,rows=rows)
    keys("s1","n"); print("120x",rows,"create",rect("Create journal")); keys("s1","Escape")
