{"command":"mkdir -p src/app src/backend
cat > src/cli.rs <<'RS'
use clap::{Arg, ArgAction, Command};
use std::path::PathBuf;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum BackendTypeCli {
    Json,
    Sqlite,
}

#[derive(Debug, Clone)]
pub enum CliCommand {
    PrintConfig,
    ImportJournals { path: PathBuf },
    AssignPriority { priority: u32 },
    Theme(ThemeCommand),
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ThemeCommand {
    PrintPath,
    PrintDefault,
    WriteDefaults,
}

#[derive(Debug, Clone)]
pub struct Cli {
    pub json_file_path: Option<PathBuf>,
    pub sqlite_file_path: Option<PathBuf>,
    pub backend_type: Option<BackendTypeCli>,
    pub config_dir: Option<PathBuf>,
    pub verbose: u8,
    pub log_file: Option<PathBuf>,
    pub command: Option<CliCommand>,
}

fn default_config_dir_display() -> String {
    crate::settings::default_config_dir()
        .map(|p| p.display().to_string())
        .unwrap_or_default()
}

fn default_log_file_display() -> String {
    crate::settings::default_log_path()
        .map(|p| p.display().to_string())
        .unwrap_or_default()
}

pub fn parse() -> Cli {
    let config_help = format!(
        "Specifies the path for the configuration directory.\nConfiguration files is considered as root for themes file too.\nIt still accepts the path for configuration file for backward compatibility.\n(default path: {})",
        default_config_dir_display()
    );
    let log_help = format!(
        "Specifies a file to use for logging\n(default file: {})",
        default_log_file_display()
    );

    let theme_cmd = Command::new("theme")
        .about("Provides commands regarding changing themes and styles of the app")
        .visible_alias("style")
        .arg_required_else_help(true)
        .subcommand_required(true)
        .subcommand(
            Command::new("print-path")
                .about("Prints the path to the user themes file")
                .visible_alias("path"),
        )
        .subcommand(
            Command::new("print-default")
                .about("Dumps the styles with the default values to be used as a reference and base for user custom themes")
                .visible_alias("default"),
        )
        .subcommand(
            Command::new("write-defaults")
                .about("Creates user custom themes file if doesn't exist then writes the default styles to it")
                .visible_alias("write"),
        );

    let mut cmd = Command::new("tui-journal")
        .version("0.16.1")
        .about("Tui app allows writing and managing journals/notes from within the terminal With different local back-ends")
        .arg(
            Arg::new("json_file_path")
                .short('j')
                .long("json-file-path")
                .value_name("FILE PATH")
                .help("Sets the entries Json file path and starts using it")
                .num_args(1),
        )
        .arg(
            Arg::new("sqlite_file_path")
                .short('s')
                .long("sqlite-file-path")
                .value_name("FILE PATH")
                .help("Sets the entries sqlite file path and starts using it")
                .num_args(1),
        )
        .arg(
            Arg::new("backend_type")
                .short('b')
                .long("backend-type")
                .value_name("BACKEND_TYPE")
                .help("Sets the backend type and starts using it")
                .value_parser(["json", "sqlite"])
                .num_args(1),
        )
        .arg(
            Arg::new("config")
                .short('c')
                .long("config")
                .value_name("DIR PATH")
                .help(config_help)
                .num_args(1),
        )
        .arg(
            Arg::new("verbose")
                .short('v')
                .long("verbose")
                .help("Increases logging verbosity each use for up to 3 times")
                .action(ArgAction::Count),
        )
        .arg(
            Arg::new("log")
                .short('l')
                .long("log")
                .value_name("FILE PATH")
                .help(log_help)
                .num_args(1),
        )
        .subcommand(
            Command::new("print-config")
                .about("Print the current settings including the paths for the back-end files")
                .visible_alias("pc"),
        )
        .subcommand(
            Command::new("import-journals")
                .about("Import journals from the given transfer JSON file to the current back-end file")
                .visible_alias("imj")
                .arg(
                    Arg::new("path")
                        .short('p')
                        .long("path")
                        .value_name("FILE PATH")
                        .help("Path of the JSON file to import from")
                        .required(true)
                        .num_args(1),
                ),
        )
        .subcommand(
            Command::new("assign-priority")
                .about("Assign priority for all the entries with empty priority field")
                .visible_alias("ap")
                .arg(
                    Arg::new("PRIORITY")
                        .help("Priority value (Positive number)")
                        .required(true)
                        .value_parser(clap::value_parser!(u32)),
                ),
        )
        .subcommand(theme_cmd);

    let matches = cmd.clone().get_matches();

    let backend_type = matches
        .get_one::<String>("backend_type")
        .map(|s| match s.as_str() {
            "json" => BackendTypeCli::Json,
            _ => BackendTypeCli::Sqlite,
        });

    let command = match matches.subcommand() {
        Some(("print-config", _)) => Some(CliCommand::PrintConfig),
        Some(("import-journals", sub)) => Some(CliCommand::ImportJournals {
            path: PathBuf::from(sub.get_one::<String>("path").unwrap()),
        }),
        Some(("assign-priority", sub)) => Some(CliCommand::AssignPriority {
            priority: *sub.get_one::<u32>("PRIORITY").unwrap(),
        }),
        Some(("theme", sub)) => {
            let tc = match sub.subcommand() {
                Some(("print-path", _)) => ThemeCommand::PrintPath,
                Some(("print-default", _)) => ThemeCommand::PrintDefault,
                Some(("write-defaults", _)) => ThemeCommand::WriteDefaults,
                _ => unreachable!(),
            };
            Some(CliCommand::Theme(tc))
        }
        _ => None,
    };

    Cli {
