                Some(("print-default", _)) => ThemeCommand::PrintDefault,
                Some(("write-defaults", _)) => ThemeCommand::WriteDefaults,
                _ => unreachable!(),
            };
            Some(CliCommand::Theme(tc))
        }
        _ => None,
    };

    Cli {
        json_file_path: matches.get_one::<String>("json_file_path").map(PathBuf::from),
        sqlite_file_path: matches
            .get_one::<String>("sqlite_file_path")
