#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BackendType {
    Json,
    Sqlite,
}

impl std::fmt::Display for BackendType {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            BackendType::Json => write!(f, "Json"),
            BackendType::Sqlite => write!(f, "Sqlite"),
        }
    }
}

// Custom (de)serialization to mirror serde representations observed.
// Serialize as the variant name string.
impl Serialize for BackendType {
    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        serializer.serialize_str(match self {
            BackendType::Json => "Json",
            BackendType::Sqlite => "Sqlite",
        })
    }
}
impl<'de> Deserialize<'de> for BackendType {
    fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        // Use a helper enum with exact variant names so toml error messages match
        // ("unknown variant `json`, expected `Json` or `Sqlite`" and "wanted string or table").
        #[derive(Deserialize)]
        enum Repr {
            Json,
            Sqlite,
        }
        match Repr::deserialize(deserializer)? {
            Repr::Json => Ok(BackendType::Json),
            Repr::Sqlite => Ok(BackendType::Sqlite),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DatumVisibility {
    Show,
    Hide,
    EmptyLine,
}
impl Serialize for DatumVisibility {
    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        serializer.serialize_str(match self {
            DatumVisibility::Show => "show",
            DatumVisibility::Hide => "hide",
            DatumVisibility::EmptyLine => "empty_line",
        })
    }
}
impl<'de> Deserialize<'de> for DatumVisibility {
    fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        #[derive(Deserialize)]
        #[serde(rename_all = "snake_case")]
        enum Repr {
            Show,
            Hide,
            EmptyLine,
        }
        match Repr::deserialize(deserializer)? {
            Repr::Show => Ok(DatumVisibility::Show),
            Repr::Hide => Ok(DatumVisibility::Hide),
            Repr::EmptyLine => Ok(DatumVisibility::EmptyLine),
        }
    }
}

// Path deserialization: rely on serde's PathBuf implementation.

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ExportSettings {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub default_path: Option<PathBuf>,
    #[serde(default = "default_true")]
    pub show_confirmation: bool,
}
impl Default for ExportSettings {
    fn default() -> Self {
        Self { default_path: None, show_confirmation: true }
    }
}

#[derive(Debug, Clone)]
pub struct ExternalEditor {
    pub command: Option<String>,
    pub auto_save: bool,
    pub temp_file_extension: String,
}
impl Default for ExternalEditor {
    fn default() -> Self {
        Self { command: None, auto_save: false, temp_file_extension: "txt".to_string() }
    }
}
impl Serialize for ExternalEditor {
    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        use serde::ser::SerializeMap;
        let mut map = serializer.serialize_map(None)?;
        if let Some(cmd) = &self.command {
            map.serialize_entry("command", cmd)?;
        }
        map.serialize_entry("auto_save", &self.auto_save)?;
        map.serialize_entry("temp_file_extension", &self.temp_file_extension)?;
        map.end()
    }
}
impl<'de> Deserialize<'de> for ExternalEditor {
    fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        struct Visitor;
        impl<'de> serde::de::Visitor<'de> for Visitor {
            type Value = ExternalEditor;
            fn expecting(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
                f.write_str("string or map")
            }
            fn visit_str<E: serde::de::Error>(self, v: &str) -> Result<Self::Value, E> {
                Ok(ExternalEditor { command: Some(v.to_string()), ..Default::default() })
            }
            fn visit_string<E: serde::de::Error>(self, v: String) -> Result<Self::Value, E> {
                Ok(ExternalEditor { command: Some(v), ..Default::default() })
            }
            fn visit_map<A: serde::de::MapAccess<'de>>(self, mut map: A) -> Result<Self::Value, A::Error> {
                let mut command: Option<String> = None;
                let mut auto_save: Option<bool> = None;
                let mut temp_file_extension: Option<String> = None;
                while let Some(key) = map.next_key::<String>()? {
                    match key.as_str() {
                        "command" => {
                            if command.is_some() { return Err(serde::de::Error::duplicate_field("command")); }
                            command = Some(map.next_value()?);
                        }
                        "auto_save" => {
                            if auto_save.is_some() { return Err(serde::de::Error::duplicate_field("auto_save")); }
                            auto_save = Some(map.next_value()?);
                        }
                        "temp_file_extension" => {
                            if temp_file_extension.is_some() { return Err(serde::de::Error::duplicate_field("temp_file_extension")); }
                            temp_file_extension = Some(map.next_value()?);
                        }
                        _ => {
                            let _ = map.next_value::<serde::de::IgnoredAny>()?;
                        }
                    }
                }
                Ok(ExternalEditor {
                    command,
                    auto_save: auto_save.unwrap_or(false),
                    temp_file_extension: temp_file_extension.unwrap_or_else(|| "txt".to_string()),
                })
            }
        }
        deserializer.deserialize_any(Visitor)
    }
}

