pub struct LoadedSettings {
    pub settings: Settings,
    /// directory to use for themes (custom dir if given as dir, otherwise None meaning default)
    pub custom_dir: Option<PathBuf>,
    /// whether a custom configuration argument was supplied at all
    pub custom_is_file: bool,
}

impl Settings {
    pub fn load(custom: Option<&Path>) -> anyhow::Result<LoadedSettings> {
        let (config_path, custom_dir, custom_is_file) = if let Some(p) = custom {
            if !p.exists() {
                return Err(anyhow!(
                    "Provided custom directory doesn't exit. Path: {}",
                    p.display()
                ));
            }
            if p.is_dir() {
                (p.join("config.toml"), Some(p.to_path_buf()), false)
            } else {
                (p.to_path_buf(), None, true)
            }
        } else {
            let dir = default_config_dir().unwrap_or_else(|| PathBuf::from(".config/tui-journal"));
            (dir.join("config.toml"), None, false)
        };

        let settings = if config_path.exists() {
            let content = std::fs::read_to_string(&config_path).map_err(|e| {
                anyhow!("Failed to load configuration file. Error infos: {}", e)
            })?;
            toml::from_str::<Settings>(&content).map_err(|e| {
                anyhow!("Failed to read configuration file. Error infos: {}", e)
            })?
        } else {
            Settings::default()
        };
        Ok(LoadedSettings { settings, custom_dir, custom_is_file })
    }
}

/// Absolutize a path like path-absolutize: joins with cwd if relative and
/// normalizes `.` and `..` components without accessing the filesystem.
pub fn absolutize(path: &Path) -> PathBuf {
    let abs = if path.is_absolute() {
        path.to_path_buf()
    } else {
        std::env::current_dir()
            .unwrap_or_else(|_| PathBuf::from("/"))
            .join(path)
    };
    let mut out = PathBuf::new();
    for comp in abs.components() {
