pub fn themes_path(custom_dir: &Option<PathBuf>, custom_is_file: bool, print_info: bool) -> PathBuf {
    if let Some(dir) = custom_dir {
        return dir.join("themes.toml");
    }
    if custom_is_file {
        if print_info {
            eprintln!("INFO: Custom config directory is ignored in themese because it's not a directory.");
        }
    }
    crate::settings::default_config_dir()
        .unwrap_or_else(|| PathBuf::from(".config/tui-journal"))
        .join("themes.toml")
}

pub fn default_theme_text() -> anyhow::Result<String> {
    let styles = default_styles_file();
    Ok(toml::to_string_pretty(&styles).unwrap())
}

pub fn load_styles(path: &Path) -> anyhow::Result<Styles> {
    let mut styles = default_styles();
    if !path.exists() {
        return Ok(styles);
    }
    let content = std::fs::read_to_string(path).map_err(|e| {
        anyhow!(e).context(format!(
            "Loading themes file content failed. Path: {}",
            path.display()
        ))
    }).context("Error while retrieving app styles")?; // placeholder, replaced below
    // The above double-context pattern is wrong; construct manually:
    // (Kept simple: recreate error chain properly)
    // -- handled by caller if err; we instead do manual below when parse fails.
    let partial: PartialStyles = match toml::from_str(&content) {
        Ok(p) => p,
        Err(e) => {
            return Err(anyhow!(e)
                .context(format!(
                    "Error while desrializing toml text to styles. File path: {}",
                    path.display()
                ))
                .context("Error while retrieving app styles"));
        }
    };
    // merge
    if let Some(g) = partial.general {
        let b = styles.general.clone();
        styles.general = GeneralApp {
            input_block_active: g.input_block_active.as_ref().map(|p| p.merge(b.input_block_active)).unwrap_or(b.input_block_active),
            input_block_invalid: g.input_block_invalid.as_ref().map(|p| p.merge(b.input_block_invalid)).unwrap_or(b.input_block_invalid),
            input_corsur_active: g.input_corsur_active.as_ref().map(|p| p.merge(b.input_corsur_active)).unwrap_or(b.input_corsur_active),
            input_corsur_invalid: g.input_corsur_invalid.as_ref().map(|p| p.merge(b.input_corsur_invalid)).unwrap_or(b.input_corsur_invalid),
            list_item_selected: g.list_item_selected.as_ref().map(|p| p.merge(b.list_item_selected)).unwrap_or(b.list_item_selected),
            list_highlight_active: g.list_highlight_active.as_ref().map(|p| p.merge(b.list_highlight_active)).unwrap_or(b.list_highlight_active),
            list_highlight_inactive: g.list_highlight_inactive.as_ref().map(|p| p.merge(b.list_highlight_inactive)).unwrap_or(b.list_highlight_inactive),
        };
    }
    if let Some(j) = partial.journals_list {
        let b = styles.journals_list.clone();
        styles.journals_list = JournalsApp {
            block_active: j.block_active.as_ref().map(|p| p.merge(b.block_active)).unwrap_or(b.block_active),
            block_inactive: j.block_inactive.as_ref().map(|p| p.merge(b.block_inactive)).unwrap_or(b.block_inactive),
            block_multi_select: j.block_multi_select.as_ref().map(|p| p.merge(b.block_multi_select)).unwrap_or(b.block_multi_select),
            highlight_active: j.highlight_active.as_ref().map(|p| p.merge(b.highlight_active)).unwrap_or(b.highlight_active),
            highlight_inactive: j.highlight_inactive.as_ref().map(|p| p.merge(b.highlight_inactive)).unwrap_or(b.highlight_inactive),
            title_active: j.title_active.as_ref().map(|p| p.merge(b.title_active)).unwrap_or(b.title_active),
            title_inactive: j.title_inactive.as_ref().map(|p| p.merge(b.title_inactive)).unwrap_or(b.title_inactive),
            title_selected: j.title_selected.as_ref().map(|p| p.merge(b.title_selected)).unwrap_or(b.title_selected),
            date_priority: j.date_priority.as_ref().map(|p| p.merge(b.date_priority)).unwrap_or(b.date_priority),
            tags_default: j.tags_default.as_ref().map(|p| p.merge(b.tags_default)).unwrap_or(b.tags_default),
        };
    }
    if let Some(e) = partial.editor {
        let b = styles.editor.clone();
        styles.editor = EditorApp {
            block_insert: e.block_insert.as_ref().map(|p| p.merge(b.block_insert)).unwrap_or(b.block_insert),
            block_visual: e.block_visual.as_ref().map(|p| p.merge(b.block_visual)).unwrap_or(b.block_visual),
            block_normal_active: e.block_normal_active.as_ref().map(|p| p.merge(b.block_normal_active)).unwrap_or(b.block_normal_active),
            block_normal_inactive: e.block_normal_inactive.as_ref().map(|p| p.merge(b.block_normal_inactive)).unwrap_or(b.block_normal_inactive),
            cursor_normal: e.cursor_normal.as_ref().map(|p| p.merge(b.cursor_normal)).unwrap_or(b.cursor_normal),
            cursor_insert: e.cursor_insert.as_ref().map(|p| p.merge(b.cursor_insert)).unwrap_or(b.cursor_insert),
            cursor_visual: e.cursor_visual.as_ref().map(|p| p.merge(b.cursor_visual)).unwrap_or(b.cursor_visual),
            selection_style: e.selection_style.as_ref().map(|p| p.merge(b.selection_style)).unwrap_or(b.selection_style),
        };
    }
    if let Some(m) = partial.msgbox {
        if let Some(c) = m.error { styles.msgbox_error = c; }
        if let Some(c) = m.warning { styles.msgbox_warning = c; }
        if let Some(c) = m.info { styles.msgbox_info = c; }
        if let Some(c) = m.question { styles.msgbox_question = c; }
    }
    Ok(styles)
}

pub fn load_styles_or_err(path: &Path) -> anyhow::Result<Styles> {
    // Wrapper to fix error chain for IO errors (load_styles above contexts incorrectly).
    if path.exists() {
        if path.is_dir() {
            let io = std::io::Error::from_raw_os_error(21);
            return Err(anyhow!(io)
                .context(format!("Loading themes file content failed. Path: {}", path.display()))
                .context("Error while retrieving app styles"));
        }
    }
    load_styles(path)
}
