#[derive(Debug, Clone, Copy, PartialEq)]
pub struct AppStyle {
    pub fg: Option<Color>,
    pub bg: Option<Color>,
    pub modifiers: Modifier,
    pub underline_color: Option<Color>,
}
impl AppStyle {
    pub fn new(fg: Option<Color>, bg: Option<Color>, modifiers: Modifier) -> Self {
        Self { fg, bg, modifiers, underline_color: None }
    }
    pub fn to_ratatui(&self) -> Style {
        let mut s = Style::default();
        if let Some(fg) = self.fg { s = s.fg(fg); }
        if let Some(bg) = self.bg { s = s.bg(bg); }
        if let Some(uc) = self.underline_color { s = s.underline_color(uc); }
        s = s.add_modifier(self.modifiers);
        // Ensure removed modifiers? Style default has none.
        s
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct StyleDef {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub fg: Option<Color>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub bg: Option<Color>,
    #[serde(default, skip_serializing_if = "is_empty_modifier")]
    pub modifiers: Modifier,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub underline_color: Option<Color>,
}
fn is_empty_modifier(m: &Modifier) -> bool {
    // We never skip modifiers in output (defaults print modifiers = "").
    let _ = m;
    false
}
impl StyleDef {
    fn app(&self, base: AppStyle) -> AppStyle {
        // self is a full style (used for defaults serialization). Partial merging uses PartialStyleDef.
        let _ = base;
        AppStyle { fg: self.fg, bg: self.bg, modifiers: self.modifiers, underline_color: self.underline_color }
    }
}

#[derive(Debug, Clone, Deserialize, Default)]
pub struct PartialStyleDef {
    #[serde(default)]
    pub fg: Option<Color>,
    #[serde(default)]
    pub bg: Option<Color>,
    #[serde(default)]
    pub modifiers: Option<Modifier>,
    #[serde(default)]
    pub underline_color: Option<Color>,
}
impl PartialStyleDef {
    fn merge(&self, base: AppStyle) -> AppStyle {
        AppStyle {
            fg: self.fg.or(base.fg),
            bg: self.bg.or(base.bg),
            modifiers: self.modifiers.unwrap_or(base.modifiers),
            underline_color: self.underline_color.or(base.underline_color),
        }
    }
}

