pub fn default_styles() -> Styles {
    use Color::*;
    Styles {
        general: GeneralApp {
            input_block_active: ap(Some(LightYellow), None, Modifier::empty()),
            input_block_invalid: ap(Some(LightRed), None, Modifier::empty()),
