use cli::{CliCommand, ThemeCommand};
use settings::BackendType;

fn main() -> anyhow::Result<()> {
    let cli = cli::parse();
    let loaded = settings::Settings::load(cli.config_dir.as_deref())?;
    let mut settings = loaded.settings;

    logging::init(cli.verbose, cli.log_file.clone())?;

    // Apply CLI overrides
    if let Some(json_path) = &cli.json_file_path {
        settings.json_backend.file_path = settings::absolutize(json_path);
        if cli.backend_type.is_none() {
            settings.backend_type = BackendType::Json;
        }
    }
    if let Some(sqlite_path) = &cli.sqlite_file_path {
        settings.sqlite_backend.file_path = settings::absolutize(sqlite_path);
        if cli.backend_type.is_none() {
            // If both -j and -s are given, sqlite wins in the original regardless of order.
            settings.backend_type = BackendType::Sqlite;
        }
    }
    // The precedence observed: explicit backend-type wins. If only -j, Json; only -s, Sqlite (already default).
    // When both paths given without backend type, result is Sqlite (handled above by applying sqlite after json).
    if let Some(bt) = &cli.backend_type {
        settings.backend_type = match bt {
            cli::BackendTypeCli::Json => BackendType::Json,
            cli::BackendTypeCli::Sqlite => BackendType::Sqlite,
        };
    } else if cli.json_file_path.is_some() && cli.sqlite_file_path.is_none() {
        settings.backend_type = BackendType::Json;
    } else if cli.sqlite_file_path.is_some() && cli.json_file_path.is_none() {
        settings.backend_type = BackendType::Sqlite;
    } else if cli.json_file_path.is_some() && cli.sqlite_file_path.is_some() {
        settings.backend_type = BackendType::Sqlite;
    }

    match cli.command.clone() {
        Some(CliCommand::PrintConfig) => {
            let text = toml::to_string_pretty(&settings)
                .map_err(|e| anyhow!(e))?;
            println!("{}", text);
            return Ok(());
        }
        Some(CliCommand::Theme(theme)) => {
            match theme {
                ThemeCommand::PrintPath => {
                    let path = styles::themes_path(&loaded.custom_dir, loaded.custom_is_file, true);
                    println!("{}", path.display());
                }
                ThemeCommand::PrintDefault => {
                    let text = styles::default_theme_text()?;
                    println!("{}", text);
                }
                ThemeCommand::WriteDefaults => {
                    let path = styles::themes_path(&loaded.custom_dir, loaded.custom_is_file, true);
                    if path.exists() {
                        return Err(anyhow!("Themes file already exists. Path: {}", path.display()));
                    }
                    let text = styles::default_theme_text()?;
                    std::fs::write(&path, text)
                        .context("Error while writing default themes to file")?;
                    println!("Default themes have been written to {}", path.display());
                }
            }
            return Ok(());
        }
        _ => {}
    }

    // Commands that fall through to the TUI (none, import, assign-priority)
    let pre_action = match cli.command.clone() {
        Some(CliCommand::ImportJournals { path }) => Some(app::PreAction::Import(path)),
        Some(CliCommand::AssignPriority { priority }) => Some(app::PreAction::AssignPriority(priority)),
        _ => None,
    };

    let themes_path = styles::themes_path(&loaded.custom_dir, loaded.custom_is_file, true);
    let app_styles = styles::load_styles(&themes_path)
        .map_err(|e| e)?; // load_styles already adds outer context

    app::run(settings, app_styles, pre_action)
}
