#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TransferEntry {
    pub date: DateTime<Utc>,
    pub title: String,
    pub content: String,
    pub tags: Vec<String>,
    #[serde(default)]
    pub priority: Option<u32>,
