const SQLITE_OK: c_int = 0;
const SQLITE_ROW: c_int = 100;
const SQLITE_DONE: c_int = 101;
const SQLITE_TRANSIENT: isize = -1;

#[derive(Debug)]
pub struct DbError {
    pub code: i32,
    pub message: String,
}
impl std::fmt::Display for DbError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "(code: {}) {}", self.code, self.message)
    }
}
impl std::error::Error for DbError {}

fn db_anyhow(code: i32, message: String) -> anyhow::Error {
    let db = DbError { code, message: message.clone() };
    anyhow::Error::new(db).context(format!("error returned from database: (code: {}) {}", code, message))
}

pub struct SqliteProvider {
    pub path: PathBuf,
    db: *mut sqlite3,
}

fn hex_bytes(hex: &str) -> Vec<u8> {
    (0..hex.len()).step_by(2).map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap()).collect()
}

impl SqliteProvider {
    pub fn new(path: PathBuf) -> anyhow::Result<Self> {
        if let Some(parent) = path.parent() {
            if !parent.as_os_str().is_empty() {
                let _ = std::fs::create_dir_all(parent);
            }
        }
        let cpath = CString::new(path.to_string_lossy().as_bytes()).unwrap();
        let mut db: *mut sqlite3 = ptr::null_mut();
        let rc = unsafe { sqlite3_open(cpath.as_ptr(), &mut db) };
        if rc != SQLITE_OK {
            let (code, msg) = if db.is_null() {
                (rc, "out of memory".to_string())
            } else {
                unsafe {
                    let ec = sqlite3_extended_errcode(db);
                    let ptr = sqlite3_errmsg(db);
                    let msg = if ptr.is_null() { String::new() } else { std::ffi::CStr::from_ptr(ptr as *const c_char).to_string_lossy().into_owned() };
                    sqlite3_close(db);
                    (ec, msg)
                }
            };
            return Err(db_anyhow(code, msg));
        }
        let mut prov = SqliteProvider { path, db };
        prov.run_migrations()?;
        Ok(prov)
    }

    fn last_error(&self) -> (i32, String) {
        unsafe {
            let ec = sqlite3_extended_errcode(self.db);
            let ptr = sqlite3_errmsg(self.db);
            let msg = if ptr.is_null() { String::new() } else { std::ffi::CStr::from_ptr(ptr as *const c_char).to_string_lossy().into_owned() };
            (ec, msg)
        }
    }

    fn exec(&self, sql: &str) -> anyhow::Result<()> {
        let csql = CString::new(sql).unwrap();
        let mut errmsg: *mut c_char = ptr::null_mut();
        let rc = unsafe { sqlite3_exec(self.db, csql.as_ptr(), ptr::null_mut(), ptr::null_mut(), &mut errmsg) };
        if rc != SQLITE_OK {
            let (code, msg) = self.last_error();
            if !errmsg.is_null() { unsafe { sqlite3_free(errmsg as *mut c_void); } }
            return Err(db_anyhow(code, msg));
        }
        Ok(())
    }

    fn query(&self, sql: &str, binds: &[Bind]) -> anyhow::Result<Vec<Vec<ColVal>>> {
        let csql = CString::new(sql).unwrap();
        let mut stmt: *mut SqliteStmt = ptr::null_mut();
        let rc = unsafe { sqlite3_prepare_v2(self.db, csql.as_ptr(), -1, &mut stmt, ptr::null_mut()) };
        if rc != SQLITE_OK {
            let (code, msg) = self.last_error();
            return Err(db_anyhow(code, msg));
        }
        for (i, b) in binds.iter().enumerate() {
            let idx = (i + 1) as c_int;
            unsafe {
                match b {
                    Bind::Text(s) => {
                        let cs = CString::new(s.as_bytes()).unwrap();
                        // use byte length and copy via SQLITE_TRANSIENT (-1 as destructor pointer)
                        sqlite3_bind_text(stmt, idx, cs.as_ptr(), s.len() as c_int, SQLITE_TRANSIENT as *mut c_void);
                        // cs dropped but transient makes sqlite copy
                    }
                    Bind::Int(v) => { sqlite3_bind_int64(stmt, idx, *v); }
                    Bind::Null => { sqlite3_bind_null(stmt, idx); }
                    Bind::Blob(bytes) => { sqlite3_bind_blob(stmt, idx, bytes.as_ptr() as *const c_void, bytes.len() as c_int, SQLITE_TRANSIENT as *mut c_void); }
                }
            }
        }
        let mut rows = Vec::new();
        loop {
            let rc = unsafe { sqlite3_step(stmt) };
            if rc == SQLITE_ROW {
                let count = unsafe { sqlite3_column_count(stmt) };
                let mut row = Vec::new();
                for i in 0..count {
                    let t = unsafe { sqlite3_column_type(stmt, i) };
                    match t {
                        1 => row.push(ColVal::Int(unsafe { sqlite3_column_int64(stmt, i) })),
                        3 => {
                            let p = unsafe { sqlite3_column_text(stmt, i) };
                            let n = unsafe { sqlite3_column_bytes(stmt, i) };
                            if p.is_null() { row.push(ColVal::Text(String::new())); }
                            else {
                                let bytes = unsafe { std::slice::from_raw_parts(p, n as usize) };
                                row.push(ColVal::Text(String::from_utf8_lossy(bytes).into_owned()));
                            }
                        }
                        4 => {
                            let p = unsafe { sqlite3_column_blob(stmt, i) };
                            let n = unsafe { sqlite3_column_bytes(stmt, i) };
                            if p.is_null() { row.push(ColVal::Blob(Vec::new())); }
                            else {
                                let bytes = unsafe { std::slice::from_raw_parts(p as *const u8, n as usize) };
                                row.push(ColVal::Blob(bytes.to_vec()));
                            }
                        }
                        2 => {
                            // float - read as text via column_text would work but rarely used
                            let p = unsafe { sqlite3_column_text(stmt, i) };
                            if p.is_null() { row.push(ColVal::Null); }
                            else {
                                let s = unsafe { std::ffi::CStr::from_ptr(p as *const c_char) }.to_string_lossy().into_owned();
                                row.push(ColVal::Text(s));
                            }
                        }
                        _ => row.push(ColVal::Null),
                    }
                }
                rows.push(row);
            } else if rc == SQLITE_DONE {
                break;
            } else {
                let (code, msg) = self.last_error();
                unsafe { sqlite3_finalize(stmt); }
                return Err(db_anyhow(code, msg));
            }
        }
        unsafe { sqlite3_finalize(stmt); }
        Ok(rows)
    }

    fn execute_stmt(&self, sql: &str, binds: &[Bind]) -> anyhow::Result<()> {
        let _ = self.query(sql, binds)?;
        Ok(())
    }

    fn run_migrations(&mut self) -> anyhow::Result<()> {
        // check if migrations table exists
        let rows = self.query("SELECT name FROM sqlite_master WHERE type='table' AND name='_sqlx_migrations'", &[])?;
        if rows.is_empty() {
            self.exec("CREATE TABLE _sqlx_migrations (\n    version BIGINT PRIMARY KEY,\n    description TEXT NOT NULL,\n    installed_on TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    success BOOLEAN NOT NULL,\n    checksum BLOB NOT NULL,\n    execution_time BIGINT NOT NULL\n)")?;
        }
        let applied_rows = self.query("SELECT version FROM _sqlx_migrations", &[])?;
        let applied: Vec<i64> = applied_rows.iter().filter_map(|r| if let ColVal::Int(v) = r[0] { Some(v) } else { None }).collect();
        let migrations: [(i64, &str, &str, &str); 3] = [
            (20230509041613, "init entries", "CREATE TABLE entries\n(\n  id        INTEGER PRIMARY KEY  NOT NULL,\n  title     TEXT                 NOT NULL,\n  date      DATE                 NOT NULL,\n  content   TEXT\n)", "A9B962E074E56DB0FBFBCF4874ED6D1E8D94313C9C0122247465CC26057AD3635235B208703DB8A0843A8BC16CD50685"),
            (20230613041405, "add tags", "CREATE TABLE tags (\n  entry_id INTEGER NOT NULL,\n  tag TEXT NOT NULL,\n  PRIMARY KEY (entry_id, tag)\n  FOREIGN KEY (entry_id) REFERENCES entries (id) ON DELETE CASCADE\n)", "E0EB5FD4D092C82CB2BD4528CE27FE9C037F045245AC9F1235EE2CEF07C75443E8FEC98C3A5F0562C641B1BC5301F319"),
            (20240104160740, "entries priorities", "ALTER TABLE entries ADD COLUMN priority INTEGER DEFAULT NULL", "4DC4E4C3A2CD7ADF8CA6EE6CCA5A84EAA929BBB9C4969AF5BC181A992095E61AA156DAB76718437FCCD99E7FA1A75F7C"),
        ];
        for (version, desc, sql, checksum) in migrations {
            if applied.contains(&version) { continue; }
            let start = std::time::Instant::now();
            self.exec(sql)?;
            let elapsed = start.elapsed().as_nanos() as i64;
            let elapsed = if elapsed <= 0 { 100000 } else { elapsed };
            self.execute_stmt(
                "INSERT INTO _sqlx_migrations (version, description, success, checksum, execution_time) VALUES (?, ?, 1, ?, ?)",
                &[Bind::Int(version), Bind::Text(desc.to_string()), Bind::Blob(hex_bytes(checksum)), Bind::Int(elapsed)],
            )?;
        }
        Ok(())
    }
}

#[derive(Debug, Clone)]
enum ColVal { Int(i64), Text(String), Blob(Vec<u8>), Null }
#[derive(Debug, Clone)]
enum Bind { Text(String), Int(i64), Null, Blob(Vec<u8>) }

impl Drop for SqliteProvider {
    fn drop(&mut self) {
        if !self.db.is_null() { unsafe { sqlite3_close(self.db); } }
    }
}

fn date_to_sql(d: DateTime<Utc>) -> String {
    d.to_rfc3339_opts(SecondsFormat::Secs, false)
        .replace('T', "T")
}
fn parse_sql_date(s: &str) -> Option<DateTime<Utc>> {
    if let Ok(d) = DateTime::parse_from_rfc3339(s) { return Some(d.with_timezone(&Utc)); }
    let fmts = ["%Y-%m-%dT%H:%M:%S%.f%:z", "%Y-%m-%d %H:%M:%S%.f", "%Y-%m-%dT%H:%M:%S%.f", "%Y-%m-%d %H:%M:%S", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d"];
    for f in fmts {
        if f.contains("%:z") {
            if let Ok(d) = DateTime::parse_from_str(s, f) { return Some(d.with_timezone(&Utc)); }
        } else if let Ok(nd) = chrono::NaiveDateTime::parse_from_str(s, f) {
            return Some(DateTime::from_naive_utc_and_offset(nd, Utc));
        }
    }
    if let Ok(nd) = chrono::NaiveDate::parse_from_str(s, "%Y-%m-%d") {
        return Some(DateTime::from_naive_utc_and_offset(nd.and_hms_opt(0, 0, 0)?, Utc));
    }
    None
}

impl DataProvider for SqliteProvider {
    fn load_entries(&self) -> Result<Vec<Entry>, LoadError> {
        let rows = self.query("SELECT id, title, date, content, priority FROM entries ORDER BY id", &[])
            .map_err(|e| LoadError::Message(format!("{}", e)))?;
        let mut entries = Vec::new();
        for row in rows {
            let id = if let ColVal::Int(v) = row[0] { v as u32 } else { 0 };
            let title = if let ColVal::Text(s) = &row[1] { s.clone() } else { String::new() };
            let datestr = if let ColVal::Text(s) = &row[2] { s.clone() } else { String::new() };
            let content = match &row[3] { ColVal::Text(s) => s.clone(), ColVal::Null => String::new(), _ => String::new() };
            let priority = match row[4] { ColVal::Int(v) => Some(v as u32), _ => None };
            let date = parse_sql_date(&datestr).unwrap_or_else(|| DateTime::<Utc>::from_timestamp(0, 0).unwrap());
            let tag_rows = self.query("SELECT tag FROM tags WHERE entry_id = ? ORDER BY tag", &[Bind::Int(id as i64)])
                .map_err(|e| LoadError::Message(format!("{}", e)))?;
            // Preserve insertion order? sqlx without order would return as inserted. Using rowid order would be insertion.
            // Above ORDER BY tag may be wrong; try order by rowid instead below overwritten:
            let tag_rows = self.query("SELECT tag FROM tags WHERE entry_id = ?", &[Bind::Int(id as i64)])
                .map_err(|e| LoadError::Message(format!("{}", e)))?;
            let _ = tag_rows;
            let tags: Vec<String> = tag_rows.iter().filter_map(|r| if let ColVal::Text(s) = &r[0] { Some(s.clone()) } else { None }).collect();
            entries.push(Entry { id, date, title, content, tags, priority });
        }
        Ok(entries)
    }
    fn add_entry(&mut self, draft: &TransferEntry) -> anyhow::Result<Entry> {
        self.execute_stmt("INSERT INTO entries (title, date, content, priority) VALUES (?, ?, ?, ?)", &[
            Bind::Text(draft.title.clone()),
            Bind::Text(date_to_sql(draft.date)),
            Bind::Text(draft.content.clone()),
            match draft.priority { Some(p) => Bind::Int(p as i64), None => Bind::Null },
        ])?;
        let id = unsafe { sqlite3_last_insert_rowid(self.db) } as u32;
        for tag in &draft.tags {
            self.execute_stmt("INSERT INTO tags (entry_id, tag) VALUES (?, ?)", &[Bind::Int(id as i64), Bind::Text(tag.clone())])?;
        }
        Ok(Entry { id, date: draft.date, title: draft.title.clone(), content: draft.content.clone(), tags: draft.tags.clone(), priority: draft.priority })
    }
    fn update_entry(&mut self, entry: &Entry) -> anyhow::Result<()> {
        self.execute_stmt("UPDATE entries SET title = ?, date = ?, content = ?, priority = ? WHERE id = ?", &[
            Bind::Text(entry.title.clone()),
            Bind::Text(date_to_sql(entry.date)),
            Bind::Text(entry.content.clone()),
            match entry.priority { Some(p) => Bind::Int(p as i64), None => Bind::Null },
            Bind::Int(entry.id as i64),
        ])?;
        self.execute_stmt("DELETE FROM tags WHERE entry_id = ?", &[Bind::Int(entry.id as i64)])?;
        for tag in &entry.tags {
            self.execute_stmt("INSERT INTO tags (entry_id, tag) VALUES (?, ?)", &[Bind::Int(entry.id as i64), Bind::Text(tag.clone())])?;
        }
        Ok(())
    }
    fn delete_entry(&mut self, id: u32) -> anyhow::Result<()> {
        self.execute_stmt("DELETE FROM tags WHERE entry_id = ?", &[Bind::Int(id as i64)])?;
        self.execute_stmt("DELETE FROM entries WHERE id = ?", &[Bind::Int(id as i64)])?;
        Ok(())
    }
    fn import_entries(&mut self, drafts: &[TransferEntry]) -> anyhow::Result<Vec<Entry>> {
        let mut out = Vec::new();
        for d in drafts {
            out.push(self.add_entry(d)?);
        }
        Ok(out)
    }
    fn assign_priority(&mut self, priority: u32) -> anyhow::Result<()> {
        self.execute_stmt("UPDATE entries SET priority = ? WHERE priority IS NULL", &[Bind::Int(priority as i64)])?;
        Ok(())
    }
}
