impl JsonProvider {
    fn read_all(&self) -> Result<Vec<Entry>, LoadError> {
        if !self.path.exists() {
            return Ok(Vec::new());
        }
        let content = std::fs::read_to_string(&self.path).map_err(|e| LoadError::Message(e.to_string()))?;
        if content.trim().is_empty() {
            return Ok(Vec::new());
        }
        serde_json::from_str::<Vec<Entry>>(&content).map_err(|_| LoadError::Parse)
    }
    fn write_all(&self, entries: &[Entry]) -> anyhow::Result<()> {
        let text = serde_json::to_string(entries)?;
        std::fs::write(&self.path, text)?;
        Ok(())
    }
}
impl DataProvider for JsonProvider {
    fn load_entries(&self) -> Result<Vec<Entry>, LoadError> {
        self.read_all()
    }
    fn add_entry(&mut self, draft: &TransferEntry) -> anyhow::Result<Entry> {
        let mut entries = self.read_all().map_err(|e| anyhow::anyhow!("{}", e))?;
        let id = entries.iter().map(|e| e.id).max().map(|m| m + 1).unwrap_or(0);
        let entry = Entry { id, date: draft.date, title: draft.title.clone(), content: draft.content.clone(), tags: draft.tags.clone(), priority: draft.priority };
        entries.push(entry.clone());
        self.write_all(&entries)?;
        Ok(entry)
    }
    fn update_entry(&mut self, entry: &Entry) -> anyhow::Result<()> {
        let mut entries = self.read_all().map_err(|e| anyhow::anyhow!("{}", e))?;
        if let Some(e) = entries.iter_mut().find(|e| e.id == entry.id) {
            *e = entry.clone();
        }
        self.write_all(&entries)?;
        Ok(())
    }
    fn delete_entry(&mut self, id: u32) -> anyhow::Result<()> {
        let mut entries = self.read_all().map_err(|e| anyhow::anyhow!("{}", e))?;
        entries.retain(|e| e.id != id);
        self.write_all(&entries)?;
        Ok(())
    }
    fn import_entries(&mut self, drafts: &[TransferEntry]) -> anyhow::Result<Vec<Entry>> {
        let mut entries = self.read_all().map_err(|e| anyhow::anyhow!("{}", e))?;
        let mut next_id = entries.iter().map(|e| e.id).max().map(|m| m + 1).unwrap_or(0);
        let mut added = Vec::new();
        for d in drafts {
            let entry = Entry { id: next_id, date: d.date, title: d.title.clone(), content: d.content.clone(), tags: d.tags.clone(), priority: d.priority };
            next_id += 1;
            entries.push(entry.clone());
            added.push(entry);
        }
        self.write_all(&entries)?;
        Ok(added)
    }
    fn assign_priority(&mut self, priority: u32) -> anyhow::Result<()> {
        let mut entries = self.read_all().map_err(|e| anyhow::anyhow!("{}", e))?;
        for e in entries.iter_mut() {
            if e.priority.is_none() { e.priority = Some(priority); }
        }
        self.write_all(&entries)?;
        Ok(())
    }
