            let line = &self.lines[r];
            let chars: Vec<char> = line.chars().collect();
            let from = if r == sr { sc } else { 0 };
            let to = if r == er { ec } else { chars.len() };
            let s: String = chars.iter().skip(from).take(to.saturating_sub(from)).collect();
            out.push_str(&s);
            if r != er { out.push('\n'); }
        }
        out
    }

