            let (sr, sc) = start;
            let (er, mut ec) = end;
            if ec < self.line_len(er) { ec += 1; }
            let t = self.extract_text((sr, sc), (er, ec));
            self.clipboard = t.clone();
            self.clipboard_linewise = false;
            t
        } else {
            String::new()
        }
    }

    pub fn delete_current_line(&mut self) -> String {
        let line = self.lines.remove(self.row);
        if self.lines.is_empty() { self.lines.push(String::new()); }
        if self.row >= self.lines.len() { self.row = self.lines.len() - 1; }
        self.col = 0;
        self.modified = true;
        line
    }

    pub fn ensure_cursor_visible(&mut self, height: usize, width: usize) {
        if height == 0 { return; }
        if self.row < self.scroll_row { self.scroll_row = self.row; }
        if self.row >= self.scroll_row + height { self.scroll_row = self.row + 1 - height; }
        if width > 0 {
            if self.col < self.scroll_col { self.scroll_col = self.col; }
            if self.col >= self.scroll_col + width { self.scroll_col = self.col + 1 - width; }
        }
    }
}
