            let s: String = chars.iter().skip(from).take(to.saturating_sub(from)).collect();
            out.push_str(&s);
            if r != er { out.push('\n'); }
        }
        out
    }

    pub fn yank_selection(&mut self) -> String {
        if let Some((start, end)) = self.selection_range() {
            let (sr, sc) = start;
            let (er, mut ec) = end;
            if ec < self.line_len(er) { ec += 1; }
            let t = self.extract_text((sr, sc), (er, ec));
            self.clipboard = t.clone();
            self.clipboard_linewise = false;
            t
        } else {
            String::new()
        }
    }

    pub fn delete_current_line(&mut self) -> String {
        let line = self.lines.remove(self.row);
        if self.lines.is_empty() { self.lines.push(String::new()); }
        if self.row >= self.lines.len() { self.row = self.lines.len() - 1; }
