        if height == 0 { return; }
        if self.row < self.scroll_row { self.scroll_row = self.row; }
        if self.row >= self.scroll_row + height { self.scroll_row = self.row + 1 - height; }
        if width > 0 {
            if self.col < self.scroll_col { self.scroll_col = self.col; }
            if self.col >= self.scroll_col + width { self.scroll_col = self.col + 1 - width; }
