#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EditorMode {
    Normal,
    Edit,
    Visual,
}

#[derive(Debug, Clone)]
pub struct Editor {
    pub lines: Vec<String>,
    // cursor as (row, char index): insertion point, 0..=line_len
    pub row: usize,
    pub col: usize,
    pub mode: EditorMode,
    pub visual_anchor: Option<(usize, usize)>,
    pub saved_content: String,
    pub modified: bool,
    pub scroll_row: usize,
    pub scroll_col: usize,
    pub pending_d: bool,
    pub clipboard: String,
    pub clipboard_linewise: bool,
}

impl Default for Editor {
    fn default() -> Self {
        Self {
            lines: vec![String::new()],
            row: 0,
            col: 0,
            mode: EditorMode::Normal,
            visual_anchor: None,
            saved_content: String::new(),
            modified: false,
            scroll_row: 0,
            scroll_col: 0,
            pending_d: false,
            clipboard: String::new(),
            clipboard_linewise: false,
        }
    }
}

impl Editor {
    pub fn load(&mut self, content: &str) {
        self.lines = if content.is_empty() {
            vec![String::new()]
        } else {
            content.split('\n').map(|s| s.to_string()).collect()
        };
        self.saved_content = content.to_string();
        self.modified = false;
        self.mode = EditorMode::Normal;
        self.visual_anchor = None;
        self.pending_d = false;
        // Cursor to end of content (observed)
        self.row = self.lines.len() - 1;
        self.col = self.line_len(self.row);
        self.scroll_row = 0;
        self.scroll_col = 0;
    }

    pub fn content(&self) -> String {
        self.lines.join("\n")
    }

    pub fn line_len(&self, row: usize) -> usize {
        self.lines.get(row).map(|l| l.chars().count()).unwrap_or(0)
    }

    fn clamp_cursor(&mut self) {
        if self.row >= self.lines.len() { self.row = self.lines.len() - 1; }
        let len = self.line_len(self.row);
        if self.col > len { self.col = len; }
    }

    pub fn insert_text(&mut self, text: &str) {
        for ch in text.chars() {
            if ch == '\n' {
                self.insert_newline();
            } else if ch == '\t' {
                self.insert_char('\t');
            } else {
                self.insert_char(ch);
            }
        }
        self.modified = true;
    }
    pub fn insert_char(&mut self, ch: char) {
        let line = self.lines[self.row].clone();
        let mut chars: Vec<char> = line.chars().collect();
        if self.col > chars.len() { self.col = chars.len(); }
        chars.insert(self.col, ch);
        self.lines[self.row] = chars.into_iter().collect();
        self.col += 1;
        self.modified = true;
    }
    pub fn insert_newline(&mut self) {
        let line = self.lines[self.row].clone();
        let chars: Vec<char> = line.chars().collect();
        let left: String = chars.iter().take(self.col).collect();
        let right: String = chars.iter().skip(self.col).collect();
        self.lines[self.row] = left;
        self.lines.insert(self.row + 1, right);
        self.row += 1;
        self.col = 0;
        self.modified = true;
    }
    pub fn backspace(&mut self) {
        if self.col > 0 {
            let line = self.lines[self.row].clone();
            let mut chars: Vec<char> = line.chars().collect();
            chars.remove(self.col - 1);
            self.lines[self.row] = chars.into_iter().collect();
            self.col -= 1;
            self.modified = true;
        } else if self.row > 0 {
            let cur = self.lines.remove(self.row);
            self.row -= 1;
            self.col = self.line_len(self.row);
            self.lines[self.row].push_str(&cur);
            self.modified = true;
        }
    }
    pub fn delete_char(&mut self) {
        if self.col < self.line_len(self.row) {
            let line = self.lines[self.row].clone();
            let mut chars: Vec<char> = line.chars().collect();
            chars.remove(self.col);
            self.lines[self.row] = chars.into_iter().collect();
            self.modified = true;
        } else if self.row + 1 < self.lines.len() {
            let next = self.lines.remove(self.row + 1);
            self.lines[self.row].push_str(&next);
            self.modified = true;
        }
    }
    // Delete char at cursor without setting modified (mirrors observed 'x' behaviour).
    pub fn delete_char_no_modified(&mut self) -> Option<char> {
        if self.col < self.line_len(self.row) {
            let line = self.lines[self.row].clone();
            let mut chars: Vec<char> = line.chars().collect();
            let c = chars.remove(self.col);
            self.lines[self.row] = chars.into_iter().collect();
            self.clamp_cursor();
            Some(c)
        } else {
            None
        }
    }

    pub fn move_left(&mut self) {
        if self.col > 0 { self.col -= 1; }
    }
    pub fn move_right(&mut self) {
        if self.col < self.line_len(self.row) { self.col += 1; }
    }
    pub fn move_up(&mut self) {
        if self.row > 0 {
            self.row -= 1;
            let len = self.line_len(self.row);
            if self.col > len { self.col = len; }
        }
    }
    pub fn move_down(&mut self) {
        if self.row + 1 < self.lines.len() {
            self.row += 1;
            let len = self.line_len(self.row);
            if self.col > len { self.col = len; }
        }
    }
    pub fn line_start(&mut self) { self.col = 0; }
    pub fn line_end(&mut self) { self.col = self.line_len(self.row); }
    pub fn first_non_blank(&mut self) {
        let line = &self.lines[self.row];
        let mut idx = 0;
        for (i, ch) in line.chars().enumerate() {
            if !ch.is_whitespace() { idx = i; self.col = idx; return; }
        }
        self.col = 0;
    }

    fn word_boundaries(&self) -> Vec<(usize, usize)> {
        // returns (row,col) word starts/ends not used directly
        Vec::new()
    }

    pub fn word_forward(&mut self) {
        // vim-like w: move to start of next word
        let pos = self.next_word_start((self.row, self.col));
        if let Some((r, c)) = pos { self.row = r; self.col = c; }
        else { self.row = self.lines.len() - 1; self.col = self.line_len(self.row); }
    }
    pub fn word_back(&mut self) {
        let pos = self.prev_word_start((self.row, self.col));
        if let Some((r, c)) = pos { self.row = r; self.col = c; }
    }
    pub fn word_end(&mut self) {
        let pos = self.next_word_end((self.row, self.col));
        if let Some((r, c)) = pos { self.row = r; self.col = c; }
    }

    fn char_at(&self, row: usize, col: usize) -> Option<char> {
        self.lines.get(row)?.chars().nth(col)
    }
    fn is_word_char(ch: char) -> bool { ch.is_alphanumeric() || ch == '_' }

    fn next_word_start(&self, from: (usize, usize)) -> Option<(usize, usize)> {
        let mut r = from.0;
        let mut c = from.1;
        // skip current word, then whitespace/newlines, land on next word/punct start
        let mut seen_any = false;
        loop {
            if r >= self.lines.len() { return None; }
            let len = self.line_len(r);
            if c >= len {
                r += 1; c = 0;
                if r >= self.lines.len() { return None; }
                continue;
            }
            let ch = self.char_at(r, c).unwrap();
            if !seen_any {
                // skip rest of current word or whitespace
                if ch.is_whitespace() { c += 1; continue; }
                // in a word: skip it
                let wc = Self::is_word_char(ch);
                while c < len {
                    let cc = self.char_at(r, c).unwrap();
                    if Self::is_word_char(cc) != wc || cc.is_whitespace() { break; }
                    c += 1;
                }
                seen_any = true;
                continue;
            } else {
                if ch.is_whitespace() { c += 1; continue; }
                return Some((r, c));
            }
        }
    }
    fn prev_word_start(&self, from: (usize, usize)) -> Option<(usize, usize)> {
        let mut r = from.0 as isize;
        let mut c = from.1 as isize - 1;
