            let len = self.line_len(r as usize) as isize;
            if c < 0 { r -= 1; if r >= 0 { c = self.line_len(r as usize) as isize - 1; } continue; }
            if c >= len { c = len - 1; }
            let ch = self.char_at(r as usize, c as usize)?;
            if ch.is_whitespace() { c -= 1; continue; }
            break;
        }
        if r < 0 { return Some((0, 0)); }
        let ch = self.char_at(r as usize, c as usize)?;
        let wc = Self::is_word_char(ch);
        while c > 0 {
            let cc = self.char_at(r as usize, (c - 1) as usize)?;
            if Self::is_word_char(cc) == wc && !cc.is_whitespace() { c -= 1; } else { break; }
        }
        Some((r as usize, c as usize))
    }
    fn next_word_end(&self, from: (usize, usize)) -> Option<(usize, usize)> {
        // move to end of next word (col points at last char index+? keep insertion model: return col = end index)
        let mut r = from.0;
        let mut c = from.1 + 1;
        loop {
            if r >= self.lines.len() { return None; }
            let len = self.line_len(r);
            if c >= len { r += 1; c = 0; continue; }
            let ch = self.char_at(r, c)?;
