                let ch2 = self.char_at(r, cc)?;
                if Self::is_word_char(ch2) != wc || ch2.is_whitespace() { break; }
                cc += 1;
            }
            // end position: insertion point after last char? vim e lands on last char; insert mode inserts after it if caret = cc
            return Some((r, cc));
        }
    }

    pub fn selection_range(&self) -> Option<((usize, usize), (usize, usize))> {
        let a = self.visual_anchor?;
        let b = (self.row, self.col);
        if a <= b { Some((a, b)) } else { Some((b, a)) }
    }

