#[derive(Debug, Clone, Default)]
pub struct TextInput {
    pub text: String,
    pub cursor: usize, // char index 0..=len
    pub scroll: usize,
}
impl TextInput {
    pub fn new(text: &str) -> Self { Self { text: text.to_string(), cursor: 0, scroll: 0 } }
    pub fn len_chars(&self) -> usize { self.text.chars().count() }
    pub fn set_text(&mut self, t: &str) { self.text = t.to_string(); self.cursor = 0; self.scroll = 0; }
    pub fn insert_char(&mut self, ch: char) {
        let mut chars: Vec<char> = self.text.chars().collect();
        if self.cursor > chars.len() { self.cursor = chars.len(); }
        chars.insert(self.cursor, ch);
        self.text = chars.into_iter().collect();
        self.cursor += 1;
    }
    pub fn insert_str(&mut self, s: &str) { for c in s.chars() { self.insert_char(c); } }
    pub fn backspace(&mut self) {
        if self.cursor > 0 {
            let mut chars: Vec<char> = self.text.chars().collect();
            chars.remove(self.cursor - 1);
            self.text = chars.into_iter().collect();
            self.cursor -= 1;
        }
    }
    pub fn delete(&mut self) {
        if self.cursor < self.len_chars() {
            let mut chars: Vec<char> = self.text.chars().collect();
            chars.remove(self.cursor);
            self.text = chars.into_iter().collect();
        }
    }
    pub fn left(&mut self) { if self.cursor > 0 { self.cursor -= 1; } }
    pub fn right(&mut self) { if self.cursor < self.len_chars() { self.cursor += 1; } }
    pub fn home(&mut self) { self.cursor = 0; }
    pub fn end(&mut self) { self.cursor = self.len_chars(); }
    pub fn ensure_visible(&mut self, width: usize) {
        if width == 0 { return; }
        if self.cursor < self.scroll { self.scroll = self.cursor; }
        if self.cursor >= self.scroll + width { self.scroll = self.cursor + 1 - width; }
    }
    /// Handle common editing keys; returns true if consumed as editing (caller handles dialog-level keys first).
    pub fn handle_key(&mut self, code: crossterm::event::KeyCode, modifiers: crossterm::event::KeyModifiers) -> bool {
        use crossterm::event::{KeyCode, KeyModifiers};
        match code {
            KeyCode::Char(ch) => {
                if modifiers.contains(KeyModifiers::CONTROL) || modifiers.contains(KeyModifiers::ALT) {
                    // Ctrl-a/e etc handled generically below
                    match ch {
                        'a' if modifiers.contains(KeyModifiers::CONTROL) => { self.home(); true }
                        'e' if modifiers.contains(KeyModifiers::CONTROL) => { self.end(); true }
                        'f' if modifiers.contains(KeyModifiers::CONTROL) => { self.right(); true }
                        'b' if modifiers.contains(KeyModifiers::CONTROL) => { self.left(); true }
                        'd' if modifiers.contains(KeyModifiers::CONTROL) => { self.delete(); true }
                        'h' if modifiers.contains(KeyModifiers::CONTROL) => { self.backspace(); true }
                        'k' if modifiers.contains(KeyModifiers::CONTROL) => { self.text = self.text.chars().take(self.cursor).collect(); true }
                        'u' if modifiers.contains(KeyModifiers::CONTROL) => { self.text = self.text.chars().skip(self.cursor).collect(); self.cursor = 0; true }
                        _ => false,
                    }
                } else {
                    self.insert_char(ch); true
                }
            }
            KeyCode::Backspace => { self.backspace(); true }
            KeyCode::Delete => { self.delete(); true }
            KeyCode::Left => { self.left(); true }
            KeyCode::Right => { self.right(); true }
            KeyCode::Home => { self.home(); true }
            KeyCode::End => { self.end(); true }
            _ => false,
        }
    }
}
