    settings: Settings,
    styles: Styles,
    pre_action: Option<PreAction>,
) -> anyhow::Result<()> {
    // Create provider (sqlite creation/migrations are fatal before terminal init)
    let mut provider: Box<dyn DataProvider> = match settings.backend_type {
        BackendType::Json => Box::new(JsonProvider { path: settings.json_backend.file_path.clone() }),
        BackendType::Sqlite => Box::new(SqliteProvider::new(settings.sqlite_backend.file_path.clone())?),
    };

    // App state
    let state_path = settings.app_state_dir.join("state.json");
    let (sorter, fullscreen, state_can_save) = load_app_state(&state_path);

    let mut app = App {
        settings,
        styles,
        provider,
        entries: Vec::new(),
        displayed: Vec::new(),
        selected_index: None,
        focus: Focus::Journals,
        fullscreen,
        multi_select: false,
        multi_selected: HashSet::new(),
        editor: Editor::default(),
        editor_entry_id: None,
        popup: None,
        msgbox: None,
        should_quit: false,
        sorter,
        filter: None,
        undo_stack: Vec::new(),
        redo_stack: Vec::new(),
        list_scroll: 0,
        state_can_save,
        request_external: false,
        external_failed_msg: None,
        tag_cycle: None,
    };

    crate::logging::log_loading_entries();
    let mut initial_msg: Option<MsgBox> = None;
    match app.provider.load_entries() {
        Ok(entries) => {
            app.entries = entries;
        }
        Err(e) => {
            app.entries = Vec::new();
            initial_msg = Some(MsgBox {
                kind: MsgKind::Error,
                text: e.to_string(),
                buttons: MsgButtons::Ok,
                action: MsgAction::None,
            });
        }
    }
    app.refresh_display(true);
    if app.selected_index.is_none() && !app.displayed.is_empty() {
        app.selected_index = Some(0);
    }
    app.sync_editor_to_selected(false);

    // Terminal init (fails with ENXIO when no tty, before pre-actions take effect)
    let mut terminal = init_terminal()?;
    crate::logging::log_mio();

    if let Some(msg) = initial_msg {
        app.msgbox = Some(msg);
    }

    // Pre-actions processed inside the app after terminal init
    if let Some(action) = pre_action {
        app.handle_pre_action(action);
    }

    let result = run_loop(&mut terminal, &mut app);

    restore_terminal(&mut terminal)?;
    result?;

    // Save app state on normal exit
    if app.state_can_save {
        let state = AppStateFile { sorter: app.sorter.clone(), full_screen: app.fullscreen };
        if let Some(parent) = state_path.parent() {
            let _ = std::fs::create_dir_all(parent);
        }
        if let Ok(text) = serde_json::to_string_pretty(&state) {
            let _ = std::fs::write(&state_path, text);
        }
    }
    Ok(())
}

fn load_app_state(path: &PathBuf) -> (SorterState, bool, bool) {
    if !path.exists() {
        return (SorterState::default(), false, true);
    }
    match std::fs::read_to_string(path) {
        Ok(text) => match serde_json::from_str::<AppStateFile>(&text) {
            Ok(state) => (state.sorter, state.full_screen, true),
            Err(_) => (SorterState::default(), false, false),
        },
        Err(_) => (SorterState::default(), false, false),
    }
}

fn init_terminal() -> anyhow::Result<Terminal<CrosstermBackend<Stdout>>> {
    // panic hook to restore terminal
    let original_hook = std::panic::take_hook();
    std::panic::set_hook(Box::new(move |info| {
        let _ = crossterm::terminal::disable_raw_mode();
        let _ = crossterm::execute!(std::io::stdout(), crossterm::terminal::LeaveAlternateScreen, crossterm::cursor::Show);
        original_hook(info);
    }));
    crossterm::terminal::enable_raw_mode()?;
    let mut stdout = std::io::stdout();
    crossterm::execute!(stdout, crossterm::terminal::EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut term = Terminal::new(backend)?;
    term.clear()?;
    Ok(term)
}
fn restore_terminal(term: &mut Terminal<CrosstermBackend<Stdout>>) -> anyhow::Result<()> {
    let _ = crossterm::terminal::disable_raw_mode();
    let _ = crossterm::execute!(std::io::stdout(), crossterm::terminal::LeaveAlternateScreen, crossterm::cursor::Show);
    term.show_cursor()?;
    Ok(())
}

fn run_loop(term: &mut Terminal<CrosstermBackend<Stdout>>, app: &mut App) -> anyhow::Result<()> {
    loop {
        term.draw(|frame| {
            ui::draw(frame, app);
        })?;
        if app.should_quit {
            break;
        }
        if app.request_external {
            app.request_external = false;
            // restore terminal temporarily
            let _ = crossterm::terminal::disable_raw_mode();
            let _ = crossterm::execute!(std::io::stdout(), crossterm::terminal::LeaveAlternateScreen, crossterm::cursor::Show);
            app.do_external_editor();
            // re-enter
            crossterm::terminal::enable_raw_mode()?;
            let _ = crossterm::execute!(std::io::stdout(), crossterm::terminal::EnterAlternateScreen);
            term.clear()?;
            continue;
        }
        let event = crossterm::event::read()?;
        if let Event::Key(key) = event {
            if key.kind == KeyEventKind::Release {
                continue;
            }
            app.handle_key(key);
        }
    }
    Ok(())
}

impl App {
    pub fn current_entry(&self) -> Option<&Entry> {
        let idx = self.selected_index?;
        self.displayed.get(idx)
    }
    pub fn current_entry_id(&self) -> Option<u32> {
        self.current_entry().map(|e| e.id)
    }

    fn handle_pre_action(&mut self, action: PreAction) {
        match action {
            PreAction::AssignPriority(priority) => {
                if let Ok(()) = self.provider.assign_priority(priority) {
                    if let Ok(entries) = self.provider.load_entries() {
                        self.entries = entries;
                        self.refresh_display(true);
                        self.sync_editor_to_selected(false);
                    }
                }
            }
            PreAction::Import(path) => {
                if !path.exists() {
                    self.msgbox = Some(MsgBox {
                        kind: MsgKind::Error,
                        text: format!("Import file doesn't exist: path {}", path.display()),
                        buttons: MsgButtons::Ok,
                        action: MsgAction::None,
                    });
                    return;
                }
                let parsed: Result<EntriesTransfer, String> = match std::fs::read_to_string(&path) {
                    Ok(content) => serde_json::from_str::<EntriesTransfer>(&content)
                        .map_err(|e| e.to_string()),
                    Err(e) => Err(e.to_string()),
                };
                match parsed {
                    Ok(transfer) => {
                        if let Ok(_added) = self.provider.import_entries(&transfer.entries) {
                            if let Ok(entries) = self.provider.load_entries() {
                                self.entries = entries;
                                self.refresh_display(true);
                                self.sync_editor_to_selected(false);
                            }
                        }
                    }
                    Err(e) => {
                        self.msgbox = Some(MsgBox {
                            kind: MsgKind::Error,
                            text: format!("Error while parsing import file. Error: {}", e),
                            buttons: MsgButtons::Ok,
                            action: MsgAction::None,
                        });
                    }
                }
            }
        }
    }

    pub fn refresh_display(&mut self, keep_id: bool) {
        let prev_id = if keep_id { self.current_entry_id() } else { None };
        let prev_index = self.selected_index;
        let mut items: Vec<Entry> = self
            .entries
            .iter()
            .filter(|e| self.matches_filter(e))
            .cloned()
            .collect();
        let criteria = self.sorter.criteria.clone();
        let order = self.sorter.order;
        items.sort_by(|a, b| {
            let mut cmp = std::cmp::Ordering::Equal;
            for c in &criteria {
                cmp = match c {
                    SortCriteria::Date => a.date.cmp(&b.date),
                    SortCriteria::Priority => a.priority.cmp(&b.priority),
                    SortCriteria::Title => a.title.cmp(&b.title),
                };
                if cmp != std::cmp::Ordering::Equal {
                    break;
                }
            }
            if order == SortOrder::Descending { cmp.reverse() } else { cmp }
        });
        self.displayed = items;
        if self.displayed.is_empty() {
            self.selected_index = None;
        } else if let Some(pid) = prev_id {
            if let Some(pos) = self.displayed.iter().position(|e| e.id == pid) {
                self.selected_index = Some(pos);
            } else if let Some(pi) = prev_index {
                self.selected_index = Some(pi.min(self.displayed.len() - 1));
            } else {
                self.selected_index = Some(0);
            }
        } else if let Some(pi) = prev_index {
            self.selected_index = Some(pi.min(self.displayed.len() - 1));
        } else {
            self.selected_index = Some(0);
        }
    }

    fn matches_filter(&self, entry: &Entry) -> bool {
        let Some(f) = &self.filter else { return true };
        if !f.has_criteria() { return true; }
        let mut checks: Vec<bool> = Vec::new();
        if !f.title.is_empty() {
            checks.push(text_matches(&entry.title, &f.title));
        }
        if !f.content.is_empty() {
            checks.push(text_matches(&entry.content, &f.content));
        }
        if let Some(p) = f.priority {
            checks.push(entry.priority == Some(p));
        }
        if !f.tags.is_empty() {
            for tag in &f.tags {
                if tag == NO_TAGS {
                    checks.push(entry.tags.is_empty());
                } else {
                    checks.push(entry.tags.iter().any(|t| t == tag));
                }
            }
        }
        if checks.is_empty() { return true; }
        match f.logic {
            MatchingLogic::All => checks.iter().all(|b| *b),
            MatchingLogic::Any => checks.iter().any(|b| *b),
        }
    }

    pub fn is_filtered(&self) -> bool {
        self.filter.as_ref().map(|f| f.has_criteria()).unwrap_or(false)
    }

    pub fn sync_editor_to_selected(&mut self, keep_mode: bool) {
        if self.editor.modified {
            return;
        }
        let _ = keep_mode;
        match self.current_entry().cloned() {
            Some(entry) => {
                let mode_before = self.editor.mode;
                self.editor.load(&entry.content);
                self.editor.mode = mode_before;
                // load() sets Normal mode; restore logic: if we were in editor focus the caller manages mode.
                // For initial/list sync we want Normal marker hidden anyway; internal default Normal.
                self.editor_entry_id = Some(entry.id);
            }
            None => {
                self.editor.load("");
                self.editor_entry_id = None;
            }
        }
    }

    // Load editor for entry unconditionally keeping mode
    fn load_editor_for(&mut self, entry: &Entry) {
        let mode = self.editor.mode;
        self.editor.load(&entry.content);
        self.editor.mode = mode;
        self.editor_entry_id = Some(entry.id);
    }

    pub fn push_history(&mut self) {
        if self.settings.history_limit == 0 {
            self.undo_stack.clear();
            return;
        }
        self.undo_stack.push(self.entries.clone());
        while self.undo_stack.len() > self.settings.history_limit {
            self.undo_stack.remove(0);
        }
        self.redo_stack.clear();
    }

    fn apply_entries_to_provider(&mut self, entries: &[Entry]) -> anyhow::Result<()> {
        // Replace all entries in provider with given snapshot
        match self.settings.backend_type {
            BackendType::Json => {
                let text = serde_json::to_string(entries)?;
                std::fs::write(&self.settings.json_backend.file_path, text)?;
            }
            BackendType::Sqlite => {
                // delete all then insert with ids
                if let Ok(current) = self.provider.load_entries() {
                    let ids: Vec<u32> = current.iter().map(|e| e.id).collect();
                    let _ = self.provider.delete_entries(&ids);
                }
                // Insert with fixed ids using raw drafts loses ids for sqlite; need direct method:
                // add then update id is not possible. Instead use provider.add for each then ... 
                // SqliteProvider does not expose insert with id; entries will get new ids close to original if emptied.
                for e in entries {
                    let draft = TransferEntry { date: e.date, title: e.title.clone(), content: e.content.clone(), tags: e.tags.clone(), priority: e.priority };
                    let _ = self.provider.add_entry(&draft);
                }
            }
        }
        Ok(())
    }

    fn undo(&mut self) {
        let Some(snapshot) = self.undo_stack.pop() else { return };
        self.redo_stack.push(self.entries.clone());
        while self.redo_stack.len() > self.settings.history_limit && self.settings.history_limit > 0 {
            self.redo_stack.remove(0);
        }
        let _ = self.apply_entries_to_provider(&snapshot);
        if let Ok(entries) = self.provider.load_entries() {
            self.entries = entries;
        } else {
            self.entries = snapshot;
        }
        self.refresh_display(true);
        if !self.editor.modified { self.sync_editor_to_selected(false); }
    }
    fn redo(&mut self) {
        let Some(snapshot) = self.redo_stack.pop() else { return };
        self.undo_stack.push(self.entries.clone());
        let _ = self.apply_entries_to_provider(&snapshot);
        if let Ok(entries) = self.provider.load_entries() {
            self.entries = entries;
        } else {
            self.entries = snapshot;
        }
        self.refresh_display(true);
        if !self.editor.modified { self.sync_editor_to_selected(false); }
    }

    fn reload_all(&mut self) {
        match self.provider.load_entries() {
            Ok(entries) => {
                self.entries = entries;
                self.refresh_display(true);
                if !self.editor.modified { self.sync_editor_to_selected(false); }
            }
            Err(e) => {
                self.msgbox = Some(MsgBox {
                    kind: MsgKind::Error,
                    text: e.to_string(),
                    buttons: MsgButtons::Ok,
                    action: MsgAction::None,
                });
            }
        }
    }

    fn save_editor_content(&mut self) {
        let Some(entry_id) = self.editor_entry_id else {
            // Mirrors original panic when 's' is pressed with no entry (handled in key code)
            return;
        };
        // Find entry in storage
        let Some(mut entry) = self.entries.iter().find(|e| e.id == entry_id).cloned() else { return };
        if entry.content == self.editor.content() && !self.editor.modified {
            // Still update (original writes file even if unmodified via Ctrl-s in some cases).
            // Keep behaviour simple: proceed to write only if caller forced.
        }
        self.push_history();
        entry.content = self.editor.content();
        if self.provider.update_entry(&entry).is_ok() {
            if let Ok(entries) = self.provider.load_entries() {
                self.entries = entries;
                self.refresh_display(true);
            } else if let Some(e) = self.entries.iter_mut().find(|e| e.id == entry_id) {
                e.content = entry.content.clone();
                self.refresh_display(true);
            }
            self.editor.saved_content = entry.content.clone();
            self.editor.modified = false;
            // reload editor content positions remain
            self.editor_entry_id = Some(entry_id);
        }
    }

    fn discard_editor(&mut self) {
        if let Some(entry) = self.entries.iter().find(|e| Some(e.id) == self.editor_entry_id).cloned() {
            let mode = self.editor.mode;
            self.editor.load(&entry.content);
            self.editor.mode = mode;
        } else {
            self.editor.load(&self.editor.saved_content.clone());
        }
        self.editor.modified = false;
    }

    fn check_unsaved(&mut self, next: NextAction) -> bool {
        // returns true if caller should proceed immediately
        if self.editor.modified {
            self.msgbox = Some(MsgBox {
                kind: MsgKind::Question,
                text: "Do you want to save the changes on the current journal?".to_string(),
                buttons: MsgButtons::YesNoCancel,
                action: MsgAction::Unsaved(next),
            });
            false
        } else {
            true
        }
    }

    fn perform_next(&mut self, next: NextAction) {
        match next {
            NextAction::Exit => { self.should_quit = true; }
            NextAction::SelectIndex(idx) => {
                if !self.displayed.is_empty() {
                    self.selected_index = Some(idx.min(self.displayed.len() - 1));
                    // sync editor to new entry
                    self.editor.modified = false;
                    if let Some(entry) = self.current_entry().cloned() {
                        self.load_editor_for(&entry);
                    }
                }
            }
            NextAction::Reload => { self.reload_all(); }
            NextAction::OpenDeleteCurrent => {
                if let Some(id) = self.current_entry_id() {
                    self.msgbox = Some(MsgBox {
                        kind: MsgKind::Question,
                        text: "Do you want to remove the current journal?".to_string(),
                        buttons: MsgButtons::YesNo,
                        action: MsgAction::DeleteCurrent(id),
                    });
                }
            }
            NextAction::OpenEditDialog => { self.open_edit_dialog(); }
            NextAction::ExternalEditor => { self.request_external = true; }
            NextAction::FocusEditorEdit => {
                self.focus = Focus::Editor;
                self.editor.mode = EditorMode::Edit;
            }
        }
    }

    fn move_selection(&mut self, new_index: usize) {
        if self.displayed.is_empty() { return; }
        let new_index = new_index.min(self.displayed.len() - 1);
        if Some(new_index) == self.selected_index { return; }
        let target_id = self.displayed.get(new_index).map(|e| e.id);
        if self.editor.modified && target_id != self.editor_entry_id {
            if self.check_unsaved(NextAction::SelectIndex(new_index)) {
                self.perform_next(NextAction::SelectIndex(new_index));
            }
        } else {
            self.selected_index = Some(new_index);
            if let Some(entry) = self.current_entry().cloned() {
                self.load_editor_for(&entry);
            }
        }
    }

    fn open_create_dialog(&mut self) {
        let today = Local::now().format("%d-%m-%Y").to_string();
        self.popup = Some(Popup::EntryDialog(Box::new(EntryDialog {
            is_create: true,
            entry_id: None,
            title: TextInput::new(""),
            date: TextInput::new(&today),
            priority: TextInput::new(""),
            tags: TextInput::new(""),
            focused: EntryField::Title,
            title_error: None,
            date_error: None,
            priority_error: None,
            tags_popup: None,
        })));
    }
    fn open_edit_dialog(&mut self) {
        let Some(entry) = self.current_entry().cloned() else { return };
        self.popup = Some(Popup::EntryDialog(Box::new(EntryDialog {
            is_create: false,
            entry_id: Some(entry.id),
            title: TextInput::new(&entry.title),
            date: TextInput::new(&entry.date.format("%d-%m-%Y").to_string()),
            priority: TextInput::new(&entry.priority.map(|p| p.to_string()).unwrap_or_default()),
            tags: TextInput::new(&entry.tags.join(", ")),
            focused: EntryField::Title,
            title_error: None,
            date_error: None,
            priority_error: None,
            tags_popup: None,
        })));
    }

    fn all_tags_sorted(&self) -> Vec<String> {
        let mut set = BTreeSet::new();
        for e in &self.entries {
            for t in &e.tags { set.insert(t.clone()); }
        }
        set.into_iter().collect()
    }

    fn open_filter_dialog(&mut self) {
        let existing = self.filter.clone().unwrap_or_else(FilterState::empty);
        let mut all = self.all_tags_sorted();
        all.push(NO_TAGS.to_string());
        self.popup = Some(Popup::Filter(Box::new(FilterDialog {
            title: TextInput::new(&existing.title),
            content: TextInput::new(&existing.content),
            priority: TextInput::new(&existing.priority.map(|p| p.to_string()).unwrap_or_default()),
            priority_error: None,
            focused: FilterField::Title,
            logic: existing.logic.clone(),
            all_tags: all,
            selected: existing.tags.iter().cloned().collect(),
            tag_cursor: 0,
        })));
    }

    fn open_sort_dialog(&mut self) {
        let all = [SortCriteria::Date, SortCriteria::Priority, SortCriteria::Title];
        let applied = self.sorter.criteria.clone();
        let available: Vec<SortCriteria> = all.iter().cloned().filter(|c| !applied.contains(c)).collect();
        self.popup = Some(Popup::Sort(Box::new(SortDialog {
            order: self.sorter.order,
            available,
            applied,
            available_cursor: 0,
            applied_cursor: 0,
            focused: SortField::Available,
        })));
    }

    fn open_fuzzy(&mut self) {
        self.popup = Some(Popup::Fuzzy(Box::new(FuzzyDialog {
            query: TextInput::new(""),
            results: Vec::new(),
            cursor: 0,
        })));
    }

    fn open_help(&mut self) {
        self.popup = Some(Popup::Help(Box::new(HelpState { tab: 0, global_scroll: 0, multi_scroll: 0 })));
    }

    fn open_export_single(&mut self) {
        let Some(entry) = self.current_entry().cloned() else { return };
        let path = self.default_export_path_single(&entry.title);
        self.popup = Some(Popup::Export(Box::new(ExportDialog {
            kind: ExportKind::Single,
            title: entry.title.clone(),
            count: 1,
            ids: vec![entry.id],
            path: TextInput::new(&path),
        })));
    }
    fn open_export_multi(&mut self) {
        if self.multi_selected.is_empty() {
            self.msgbox = Some(MsgBox {
                kind: MsgKind::Warning,
                text: "No items have been selected".to_string(),
                buttons: MsgButtons::Ok,
                action: MsgAction::None,
            });
            return;
        }
        let ids: Vec<u32> = self.multi_selected.iter().cloned().collect();
        let path = self.default_export_path_multi();
        let n = ids.len();
        self.popup = Some(Popup::Export(Box::new(ExportDialog {
            kind: ExportKind::Multi,
            title: String::new(),
            count: n,
            ids,
            path: TextInput::new(&path),
        })));
    }
    fn default_export_path_single(&self, title: &str) -> String {
        let filename = format!("{}.txt", title);
        match &self.settings.export.default_path {
            Some(dp) => {
                if dp.extension().is_some() {
                    dp.to_string_lossy().into_owned()
                } else {
                    dp.join(filename).to_string_lossy().into_owned()
                }
            }
            None => std::env::current_dir().unwrap_or_default().join(filename).to_string_lossy().into_owned(),
        }
    }
    fn default_export_path_multi(&self) -> String {
        let filename = "tjournal_export.json".to_string();
        match &self.settings.export.default_path {
            Some(dp) => {
                if dp.extension().is_some() {
                    dp.to_string_lossy().into_owned()
                } else {
                    dp.join(filename).to_string_lossy().into_owned()
                }
            }
            None => std::env::current_dir().unwrap_or_default().join(filename).to_string_lossy().into_owned(),
        }
    }

    pub fn do_external_editor(&mut self) {
        let Some(entry_id) = self.editor_entry_id.or_else(|| self.current_entry_id()) else { return };
        let editor_cmd: Option<String> = if let Some(cmd) = &self.settings.external_editor.command {
            Some(cmd.clone())
        } else if let Ok(v) = std::env::var("VISUAL") {
            Some(v)
        } else if let Ok(v) = std::env::var("EDITOR") {
            Some(v)
        } else {
            Some("vi".to_string())
        };
        let cmd_str = editor_cmd.unwrap_or_default();
        if cmd_str.trim().is_empty() {
            self.msgbox = Some(MsgBox {
                kind: MsgKind::Error,
                text: "The Editor in configuration and environmental variables is empty: VISUAL - EDITOR".to_string(),
                buttons: MsgButtons::Ok,
                action: MsgAction::None,
            });
            return;
        }
        let ext = &self.settings.external_editor.temp_file_extension;
        let temp_path = std::env::temp_dir().join(format!("tui_journal.{}", ext));
        let content = self.editor.content();
        if std::fs::write(&temp_path, &content).is_err() {
            return;
        }
        // Run editor: if command contains spaces, run through shell; otherwise direct.
        let status = if cmd_str.trim().contains(char::is_whitespace) {
            std::process::Command::new("sh")
                .arg("-c")
                .arg(format!("{} \"$@\"", cmd_str))
                .arg("sh")
                .arg(&temp_path)
                .status()
        } else {
            std::process::Command::new(&cmd_str).arg(&temp_path).status()
        };
        match status {
            Ok(_st) => {
                if let Ok(new_content) = std::fs::read_to_string(&temp_path) {
                    let mode = self.editor.mode;
                    self.editor.load(&new_content);
                    self.editor.mode = mode;
                    self.editor.modified = new_content != self.editor.saved_content;
                    if self.settings.external_editor.auto_save && self.editor.modified {
                        // save immediately
                        self.editor_entry_id = Some(entry_id);
                        self.save_editor_content();
                    }
                }
                let _ = std::fs::remove_file(&temp_path);
            }
            Err(e) => {
                let _ = std::fs::remove_file(&temp_path);
                self.msgbox = Some(MsgBox {
                    kind: MsgKind::Error,
                    text: format!("Error while opening the editor. Editor command: '{}'. Error: {}", cmd_str, e),
                    buttons: MsgButtons::Ok,
                    action: MsgAction::None,
                });
            }
        }
    }

    pub fn handle_key(&mut self, key: KeyEvent) {
        // MsgBox takes precedence
        if self.msgbox.is_some() {
            self.handle_msgbox_key(key);
            return;
        }
        if self.popup.is_some() {
            self.handle_popup_key(key);
            return;
        }
        self.handle_main_key(key);
    }

    fn handle_msgbox_key(&mut self, key: KeyEvent) {
        let Some(msg) = self.msgbox.clone() else { return };
        let code = key.code;
        match msg.buttons {
            MsgButtons::Ok => {
                let dismiss = matches!(code, KeyCode::Enter)
                    || code == KeyCode::Esc
                    || code == KeyCode::Char('o');
                // also Ctrl-m is Enter equivalent in crossterm (Enter already). Char 'm' with ctrl arrives as Enter? keep.
                if dismiss {
                    self.msgbox = None;
                    if let MsgAction::None = msg.action {}
                }
            }
            MsgButtons::YesNo => {
                match code {
                    KeyCode::Char('y') | KeyCode::Enter => {
                        self.msgbox = None;
                        self.execute_msg_action(msg.action, true);
                    }
                    KeyCode::Char('n') | KeyCode::Esc => {
                        self.msgbox = None;
                        self.execute_msg_action(msg.action, false);
                    }
                    _ => {}
                }
            }
            MsgButtons::YesNoCancel => {
                match code {
                    KeyCode::Char('y') | KeyCode::Enter => {
                        self.msgbox = None;
                        self.execute_msg_action(msg.action, true);
                    }
                    KeyCode::Char('n') => {
                        self.msgbox = None;
                        self.execute_msg_action(msg.action, false);
                    }
                    KeyCode::Char('c') | KeyCode::Esc => {
                        self.msgbox = None;
                        // cancel: do nothing
                    }
                    _ => {}
                }
            }
        }
    }

    fn execute_msg_action(&mut self, action: MsgAction, yes: bool) {
        match action {
            MsgAction::None => {}
            MsgAction::DeleteCurrent(id) => {
                if yes {
                    self.push_history();
                    if self.provider.delete_entry(id).is_ok() {
                        if let Ok(entries) = self.provider.load_entries() { self.entries = entries; }
                        else { self.entries.retain(|e| e.id != id); }
                        self.multi_selected.remove(&id);
                        self.refresh_display(true);
                        self.editor.modified = false;
                        self.sync_editor_to_selected(false);
                    }
                }
            }
            MsgAction::DeleteSelected(ids) => {
                if yes {
                    self.push_history();
                    if self.provider.delete_entries(&ids).is_ok() {
                        if let Ok(entries) = self.provider.load_entries() { self.entries = entries; }
                        else { self.entries.retain(|e| !ids.contains(&e.id)); }
                        for id in &ids { self.multi_selected.remove(id); }
                        self.refresh_display(true);
                        self.editor.modified = false;
                        self.sync_editor_to_selected(false);
                    }
                }
            }
            MsgAction::Unsaved(next) => {
                if yes {
                    self.save_editor_content();
                } else {
                    // discard
                    self.discard_editor();
                }
                self.perform_next(next);
            }
            MsgAction::DiscardEditor => {
                if yes {
                    self.discard_editor();
                }
            }
        }
    }

    fn handle_popup_key(&mut self, key: KeyEvent) {
        // Take popup out to avoid borrow issues; put back if not closed.
        let mut popup = self.popup.take().unwrap();
        let close = match &mut popup {
            Popup::EntryDialog(d) => self.entry_dialog_key(d, key),
            Popup::Filter(d) => self.filter_dialog_key(d, key),
            Popup::Sort(d) => self.sort_dialog_key(d, key),
            Popup::Fuzzy(d) => self.fuzzy_dialog_key(d, key),
            Popup::Help(d) => self.help_key(d, key),
            Popup::Export(d) => self.export_dialog_key(d, key),
        };
        if !close {
            // If during handling a msgbox/popup replacement was requested via self.popup (rare), keep new one.
            if self.popup.is_none() {
                self.popup = Some(popup);
            }
        }
    }

    fn entry_dialog_key(&mut self, d: &mut EntryDialog, key: KeyEvent) -> bool {
        // Tags popup nested
        if d.tags_popup.is_some() {
            let mut tp = d.tags_popup.take().unwrap();
            match key.code {
                KeyCode::Esc | KeyCode::Char('q') => {
                    if key.code == KeyCode::Char('q') && key.modifiers.contains(KeyModifiers::CONTROL) {
                        // ctrl-q is not q; fallthrough handled below via modifiers check
                    }
                    // Cancel
                    d.focused = tp.prev_focused;
                    return false;
                }
                KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    d.focused = tp.prev_focused;
                    return false;
                }
                KeyCode::Enter => {
                    // Confirm: set tags input to selected in all_tags order
                    let chosen: Vec<String> = tp.all_tags.iter().filter(|t| tp.selected.contains(*t)).cloned().collect();
                    d.tags.set_text(&chosen.join(", "));
                    d.focused = EntryField::Tags;
                    return false;
                }
                KeyCode::Char('m') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    let chosen: Vec<String> = tp.all_tags.iter().filter(|t| tp.selected.contains(*t)).cloned().collect();
                    d.tags.set_text(&chosen.join(", "));
                    d.focused = EntryField::Tags;
                    return false;
                }
                KeyCode::Down | KeyCode::Char('j') if !key.modifiers.contains(KeyModifiers::CONTROL) && key.code != KeyCode::Char('j') || key.code == KeyCode::Down => {
                    if tp.cursor + 1 < tp.all_tags.len() { tp.cursor += 1; }
                    d.tags_popup = Some(tp);
                    return false;
                }
                KeyCode::Up => {
                    if tp.cursor > 0 { tp.cursor -= 1; }
                    d.tags_popup = Some(tp);
                    return false;
                }
                KeyCode::Char(' ') => {
                    if let Some(tag) = tp.all_tags.get(tp.cursor).cloned() {
                        if tp.selected.contains(&tag) { tp.selected.remove(&tag); } else { tp.selected.insert(tag); }
                    }
                    d.tags_popup = Some(tp);
                    return false;
                }
                KeyCode::Char('j') => {
                    if tp.cursor + 1 < tp.all_tags.len() { tp.cursor += 1; }
                    d.tags_popup = Some(tp);
                    return false;
                }
                KeyCode::Char('k') => {
                    if tp.cursor > 0 { tp.cursor -= 1; }
                    d.tags_popup = Some(tp);
                    return false;
                }
                _ => {
                    d.tags_popup = Some(tp);
                    return false;
                }
            }
        }

        match key.code {
            KeyCode::Esc => return true,
            KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => return true,
            KeyCode::Enter => {
                return self.confirm_entry_dialog(d);
            }
            KeyCode::Char('m') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                return self.confirm_entry_dialog(d);
            }
            KeyCode::Tab => {
                d.focused = match d.focused {
                    EntryField::Title => EntryField::Date,
                    EntryField::Date => EntryField::Priority,
                    EntryField::Priority => EntryField::Tags,
                    EntryField::Tags => EntryField::Title,
                };
                return false;
            }
            KeyCode::BackTab => {
                d.focused = match d.focused {
                    EntryField::Title => EntryField::Tags,
                    EntryField::Date => EntryField::Title,
                    EntryField::Priority => EntryField::Date,
                    EntryField::Tags => EntryField::Priority,
                };
                return false;
            }
            KeyCode::Char('t') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                self.open_tags_popup(d);
                return false;
            }
            KeyCode::Char(' ') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                // Ctrl-Space: crossterm may send Char(' ') with CONTROL or Char('@')
                self.open_tags_popup(d);
                return false;
            }
            KeyCode::Char('@') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                self.open_tags_popup(d);
                return false;
            }
            _ => {}
        }
        // Ctrl-Space in crossterm often is KeyCode::Char(' ')?? also null char
        if key.code == KeyCode::Char('\0') {
            self.open_tags_popup(d);
            return false;
        }
        let input = match d.focused {
            EntryField::Title => &mut d.title,
            EntryField::Date => &mut d.date,
            EntryField::Priority => &mut d.priority,
            EntryField::Tags => &mut d.tags,
        };
        input.handle_key(key.code, key.modifiers);
        false
    }

    fn open_tags_popup(&mut self, d: &mut EntryDialog) {
        let all = self.all_tags_sorted();
        // current parsed tags
        let current: HashSet<String> = parse_tags_input(&d.tags.text).into_iter().collect();
        d.tags_popup = Some(TagsPopup {
            all_tags: all,
            selected: current,
            cursor: 0,
            prev_focused: d.focused,
        });
    }

    fn confirm_entry_dialog(&mut self, d: &mut EntryDialog) -> bool {
        let mut valid = true;
        if d.title.text.is_empty() {
            d.title_error = Some("Title can't be empty".to_string());
            valid = false;
        } else { d.title_error = None; }
        // date parse
        let parsed_date = NaiveDate::parse_from_str(&d.date.text, "%d-%m-%Y")
            .or_else(|_| NaiveDate::parse_from_str(d.date.text.trim(), "%d-%m-%Y"));
        let date_utc: Option<DateTime<Utc>> = match &parsed_date {
            Ok(nd) => {
                d.date_error = None;
                Some(Utc.from_utc_datetime(&nd.and_hms_opt(0, 0, 0).unwrap()))
            }
            Err(e) => {
                d.date_error = Some(e.to_string());
                valid = false;
                None
            }
        };
        // To match original chrono error strings exactly for inputs parsed via NaiveDate,
        // if trimming altered error, recompute: if original parse failed, use its error.
        if let Err(e) = NaiveDate::parse_from_str(&d.date.text, "%d-%m-%Y") {
            // But leading-space input is accepted by chrono %d parsing (it skips space) so this is fine.
            if parsed_date.is_err() {
                d.date_error = Some(e.to_string());
            }
        }
        let priority: Option<u32> = if d.priority.text.is_empty() {
            d.priority_error = None;
            None
        } else {
            match d.priority.text.parse::<u32>() {
                Ok(v) => { d.priority_error = None; Some(v) }
                Err(_) => {
                    d.priority_error = Some("Priority must be a positive number".to_string());
                    valid = false;
                    None
                }
            }
        };
        if !valid { return false; }
        let tags = parse_tags_input(&d.tags.text);
        let title = d.title.text.clone();
        if d.is_create {
            let draft = TransferEntry { date: date_utc.unwrap(), title, content: String::new(), tags, priority };
            self.push_history();
            match self.provider.add_entry(&draft) {
                Ok(entry) => {
                    if let Ok(entries) = self.provider.load_entries() { self.entries = entries; }
                    else { self.entries.push(entry.clone()); }
                    self.refresh_display(true);
                    if let Some(pos) = self.displayed.iter().position(|e| e.id == entry.id) {
                        self.selected_index = Some(pos);
                    }
                    self.editor.modified = false;
                    self.sync_editor_to_selected(false);
                    return true;
                }
                Err(e) => {
                    self.msgbox = Some(MsgBox { kind: MsgKind::Error, text: format!("{}", e), buttons: MsgButtons::Ok, action: MsgAction::None });
                    return true;
                }
            }
        } else {
            let Some(id) = d.entry_id else { return true };
            let Some(mut entry) = self.entries.iter().find(|e| e.id == id).cloned() else { return true };
            self.push_history();
            entry.title = title;
            entry.date = date_utc.unwrap();
            entry.priority = priority;
            entry.tags = tags;
            match self.provider.update_entry(&entry) {
                Ok(()) => {
                    if let Ok(entries) = self.provider.load_entries() { self.entries = entries; }
                    else if let Some(e) = self.entries.iter_mut().find(|e| e.id == id) { *e = entry.clone(); }
                    self.refresh_display(true);
                    // editor content unchanged; keep editor sync if it was this entry
                    if self.editor_entry_id == Some(id) && !self.editor.modified {
                        // content same
                    }
                    return true;
                }
                Err(e) => {
                    self.msgbox = Some(MsgBox { kind: MsgKind::Error, text: format!("{}", e), buttons: MsgButtons::Ok, action: MsgAction::None });
                    return true;
                }
            }
        }
    }

    fn filter_dialog_key(&mut self, d: &mut FilterDialog, key: KeyEvent) -> bool {
        match key.code {
            KeyCode::Esc => return true,
            KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => return true,
            KeyCode::Char('r') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                d.logic = match d.logic { MatchingLogic::All => MatchingLogic::Any, MatchingLogic::Any => MatchingLogic::All };
                return false;
            }
            KeyCode::Enter => {
                // validate priority
                let priority = if d.priority.text.is_empty() { None } else {
                    match d.priority.text.parse::<u32>() {
                        Ok(v) => Some(v),
                        Err(_) => {
                            d.priority_error = Some("Priority must be a positive number".to_string());
                            return false;
                        }
                    }
                };
                d.priority_error = None;
                let f = FilterState {
                    title: d.title.text.clone(),
                    content: d.content.text.clone(),
                    priority,
                    tags: d.all_tags.iter().filter(|t| d.selected.contains(*t)).cloned().collect(),
                    logic: d.logic.clone(),
                };
                if f.has_criteria() {
                    self.filter = Some(f);
                } else {
                    self.filter = None;
                }
                self.tag_cycle = None;
                self.refresh_display(true);
                if !self.editor.modified { self.sync_editor_to_selected(false); }
                return true;
            }
            KeyCode::Char('m') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                // treat like Enter - replicate by re-dispatching as Enter
                let enter = KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE);
                return self.filter_dialog_key(d, enter);
            }
            KeyCode::Tab => {
                d.focused = match d.focused {
                    FilterField::Title => FilterField::Content,
                    FilterField::Content => FilterField::Priority,
                    FilterField::Priority => FilterField::Tags,
                    FilterField::Tags => FilterField::Matching,
                    FilterField::Matching => FilterField::Title,
                };
                return false;
            }
            KeyCode::BackTab => {
                d.focused = match d.focused {
                    FilterField::Title => FilterField::Matching,
                    FilterField::Content => FilterField::Title,
                    FilterField::Priority => FilterField::Content,
                    FilterField::Tags => FilterField::Priority,
                    FilterField::Matching => FilterField::Tags,
                };
                return false;
            }
            KeyCode::Char(' ') if d.focused == FilterField::Tags => {
                if let Some(tag) = d.all_tags.get(d.tag_cursor).cloned() {
                    if d.selected.contains(&tag) { d.selected.remove(&tag); } else { d.selected.insert(tag); }
                }
                return false;
            }
            KeyCode::Down if d.focused == FilterField::Tags => {
                if d.tag_cursor + 1 < d.all_tags.len() { d.tag_cursor += 1; }
                return false;
            }
            KeyCode::Up if d.focused == FilterField::Tags => {
                if d.tag_cursor > 0 { d.tag_cursor -= 1; }
                return false;
            }
            KeyCode::Char('j') if d.focused == FilterField::Tags => {
                if d.tag_cursor + 1 < d.all_tags.len() { d.tag_cursor += 1; }
                return false;
            }
            KeyCode::Char('k') if d.focused == FilterField::Tags => {
                if d.tag_cursor > 0 { d.tag_cursor -= 1; }
                return false;
            }
            _ => {}
        }
        match d.focused {
            FilterField::Title => { d.title.handle_key(key.code, key.modifiers); }
            FilterField::Content => { d.content.handle_key(key.code, key.modifiers); }
            FilterField::Priority => { d.priority.handle_key(key.code, key.modifiers); }
            _ => {}
        }
        false
    }

    fn sort_dialog_key(&mut self, d: &mut SortDialog, key: KeyEvent) -> bool {
        match key.code {
            KeyCode::Esc => return true,
            KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => return true,
            KeyCode::Enter => {
                self.sorter = SorterState { criteria: d.applied.clone(), order: d.order };
                self.refresh_display(true);
                if !self.editor.modified { self.sync_editor_to_selected(false); }
                return true;
            }
            KeyCode::Char('m') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                self.sorter = SorterState { criteria: d.applied.clone(), order: d.order };
                self.refresh_display(true);
                if !self.editor.modified { self.sync_editor_to_selected(false); }
                return true;
            }
            KeyCode::Char('o') => {
                d.order = match d.order { SortOrder::Ascending => SortOrder::Descending, SortOrder::Descending => SortOrder::Ascending };
                return false;
            }
            KeyCode::Char('d') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                d.applied = vec![SortCriteria::Date, SortCriteria::Priority];
                d.available = vec![SortCriteria::Title];
                d.order = SortOrder::Descending;
                d.applied_cursor = 0;
                d.available_cursor = 0;
                return false;
            }
            KeyCode::Tab => {
                d.focused = match d.focused {
                    SortField::Available => SortField::Applied,
                    SortField::Applied => SortField::SortOrder,
                    SortField::SortOrder => SortField::Available,
                };
                return false;
            }
            KeyCode::BackTab => {
                d.focused = match d.focused {
                    SortField::Available => SortField::SortOrder,
                    SortField::Applied => SortField::Available,
                    SortField::SortOrder => SortField::Applied,
                };
                return false;
            }
            KeyCode::Char(' ') => {
                match d.focused {
                    SortField::Available => {
                        if !d.available.is_empty() {
                            let idx = d.available_cursor.min(d.available.len() - 1);
                            let item = d.available.remove(idx);
                            d.applied.push(item);
                            if d.available_cursor >= d.available.len() && d.available_cursor > 0 { d.available_cursor -= 1; }
                        }
                    }
                    SortField::Applied => {
                        if !d.applied.is_empty() {
                            let idx = d.applied_cursor.min(d.applied.len() - 1);
                            let item = d.applied.remove(idx);
                            d.available.push(item);
                            if d.applied_cursor >= d.applied.len() && d.applied_cursor > 0 { d.applied_cursor -= 1; }
                        }
                    }
                    SortField::SortOrder => {
                        d.order = match d.order { SortOrder::Ascending => SortOrder::Descending, SortOrder::Descending => SortOrder::Ascending };
                    }
                }
                return false;
            }
            KeyCode::Char('j') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                if d.focused == SortField::Applied {
                    let i = d.applied_cursor;
                    if i + 1 < d.applied.len() {
                        d.applied.swap(i, i + 1);
                        d.applied_cursor = i + 1;
                    }
                }
                return false;
            }
            KeyCode::Char('k') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                if d.focused == SortField::Applied {
                    let i = d.applied_cursor;
                    if i > 0 {
                        d.applied.swap(i, i - 1);
                        d.applied_cursor = i - 1;
                    }
                }
                return false;
            }
            KeyCode::Down => {
                match d.focused {
                    SortField::Available => { if d.available_cursor + 1 < d.available.len() { d.available_cursor += 1; } }
                    SortField::Applied => {
                        if key.modifiers.contains(KeyModifiers::CONTROL) {
                            let i = d.applied_cursor;
                            if i + 1 < d.applied.len() { d.applied.swap(i, i + 1); d.applied_cursor = i + 1; }
                        } else if d.applied_cursor + 1 < d.applied.len() { d.applied_cursor += 1; }
                    }
                    _ => {}
                }
                return false;
            }
            KeyCode::Up => {
                match d.focused {
                    SortField::Available => { if d.available_cursor > 0 { d.available_cursor -= 1; } }
                    SortField::Applied => {
                        if key.modifiers.contains(KeyModifiers::CONTROL) {
                            let i = d.applied_cursor;
                            if i > 0 { d.applied.swap(i, i - 1); d.applied_cursor = i - 1; }
                        } else if d.applied_cursor > 0 { d.applied_cursor -= 1; }
                    }
                    _ => {}
                }
                return false;
            }
            KeyCode::Char('j') => {
                match d.focused {
                    SortField::Available => { if d.available_cursor + 1 < d.available.len() { d.available_cursor += 1; } }
                    SortField::Applied => { if d.applied_cursor + 1 < d.applied.len() { d.applied_cursor += 1; } }
                    _ => {}
                }
                return false;
            }
            KeyCode::Char('k') => {
                match d.focused {
                    SortField::Available => { if d.available_cursor > 0 { d.available_cursor -= 1; } }
                    SortField::Applied => { if d.applied_cursor > 0 { d.applied_cursor -= 1; } }
                    _ => {}
                }
                return false;
            }
            _ => {}
        }
        false
    }

    fn fuzzy_dialog_key(&mut self, d: &mut FuzzyDialog, key: KeyEvent) -> bool {
        match key.code {
            KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                return true; // cancel without selecting
            }
            KeyCode::Enter | KeyCode::Esc => {
                if let Some(id) = d.results.get(d.cursor).cloned() {
                    if let Some(pos) = self.displayed.iter().position(|e| e.id == id) {
                        self.selected_index = Some(pos);
                        if !self.editor.modified {
                            if let Some(entry) = self.current_entry().cloned() { self.load_editor_for(&entry); }
                        }
                    }
                }
                return true;
            }
            KeyCode::Char('m') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                if let Some(id) = d.results.get(d.cursor).cloned() {
                    if let Some(pos) = self.displayed.iter().position(|e| e.id == id) {
                        self.selected_index = Some(pos);
                        if !self.editor.modified {
                            if let Some(entry) = self.current_entry().cloned() { self.load_editor_for(&entry); }
                        }
                    }
                }
                return true;
            }
            KeyCode::Down => { if d.cursor + 1 < d.results.len() { d.cursor += 1; } return false; }
            KeyCode::Up => { if d.cursor > 0 { d.cursor -= 1; } return false; }
            KeyCode::Char('n') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                if d.cursor + 1 < d.results.len() { d.cursor += 1; }
                return false;
            }
            KeyCode::Char('p') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                if d.cursor > 0 { d.cursor -= 1; }
                return false;
            }
            _ => {}
        }
        if d.query.handle_key(key.code, key.modifiers) {
            self.recompute_fuzzy(d);
        }
        false
    }

    fn recompute_fuzzy(&self, d: &mut FuzzyDialog) {
        d.cursor = 0;
        if d.query.text.is_empty() {
            d.results = Vec::new();
            return;
        }
        let mut scored: Vec<(i64, usize, u32)> = Vec::new();
        for (idx, e) in self.displayed.iter().enumerate() {
            if let Some(score) = fuzzy_score(&e.title, &d.query.text) {
                scored.push((score, idx, e.id));
            }
        }
        scored.sort_by(|a, b| b.0.cmp(&a.0).then(a.1.cmp(&b.1)));
        d.results = scored.into_iter().map(|s| s.2).collect();
    }

    fn help_key(&mut self, d: &mut HelpState, key: KeyEvent) -> bool {
        match key.code {
            KeyCode::Char('q') | KeyCode::Esc => return true,
            KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => return true,
            KeyCode::Tab => { d.tab = (d.tab + 1) % 3; return false; }
            KeyCode::BackTab => { d.tab = (d.tab + 2) % 3; return false; }
            KeyCode::Right | KeyCode::Char('l') => { d.tab = (d.tab + 1) % 3; return false; }
            KeyCode::Left | KeyCode::Char('h') => { d.tab = (d.tab + 2) % 3; return false; }
            KeyCode::Down | KeyCode::Char('j') => {
                if d.tab == 0 { d.global_scroll = d.global_scroll.saturating_add(1); }
                else if d.tab == 2 { d.multi_scroll = d.multi_scroll.saturating_add(1); }
                return false;
            }
            KeyCode::Up | KeyCode::Char('k') => {
                if d.tab == 0 { d.global_scroll = d.global_scroll.saturating_sub(1); }
                else if d.tab == 2 { d.multi_scroll = d.multi_scroll.saturating_sub(1); }
                return false;
            }
            KeyCode::PageDown => {
                if d.tab == 0 { d.global_scroll += 10; } else if d.tab == 2 { d.multi_scroll += 10; }
                return false;
            }
            KeyCode::PageUp => {
                if d.tab == 0 { d.global_scroll = d.global_scroll.saturating_sub(10); }
                else if d.tab == 2 { d.multi_scroll = d.multi_scroll.saturating_sub(10); }
                return false;
            }
            _ => {}
        }
        false
    }

    fn export_dialog_key(&mut self, d: &mut ExportDialog, key: KeyEvent) -> bool {
        match key.code {
            KeyCode::Esc => return true,
            KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => return true,
            KeyCode::Enter => {
                let path_str = d.path.text.clone();
                match d.kind {
                    ExportKind::Single => {
                        let Some(entry) = self.entries.iter().find(|e| e.id == d.ids[0]).cloned() else { return true };
                        match std::fs::write(&path_str, &entry.content) {
                            Ok(()) => {
                                if self.settings.export.show_confirmation {
                                    self.msgbox = Some(MsgBox {
                                        kind: MsgKind::Info,
                                        text: format!("Journal content exported to file {}", path_str),
                                        buttons: MsgButtons::Ok,
                                        action: MsgAction::None,
                                    });
                                }
                                return true;
                            }
                            Err(e) => {
                                self.msgbox = Some(MsgBox { kind: MsgKind::Error, text: e.to_string(), buttons: MsgButtons::Ok, action: MsgAction::None });
                                return true;
                            }
                        }
                    }
                    ExportKind::Multi => {
                        let entries: Vec<Entry> = self.entries.iter().filter(|e| d.ids.contains(&e.id)).cloned().collect();
                        let transfer = EntriesTransfer {
                            version: 100,
                            entries: entries.iter().map(|e| TransferEntry { date: e.date, title: e.title.clone(), content: e.content.clone(), tags: e.tags.clone(), priority: e.priority }).collect(),
                        };
                        match serde_json::to_string_pretty(&transfer) {
                            Ok(text) => match std::fs::write(&path_str, text) {
                                Ok(()) => {
                                    if self.settings.export.show_confirmation {
                                        self.msgbox = Some(MsgBox {
                                            kind: MsgKind::Info,
                                            text: format!("Journal(s)  exported to file {}", path_str),
                                            buttons: MsgButtons::Ok,
                                            action: MsgAction::None,
                                        });
                                    }
                                    return true;
                                }
                                Err(e) => {
                                    self.msgbox = Some(MsgBox { kind: MsgKind::Error, text: e.to_string(), buttons: MsgButtons::Ok, action: MsgAction::None });
                                    return true;
                                }
                            },
                            Err(e) => {
                                self.msgbox = Some(MsgBox { kind: MsgKind::Error, text: e.to_string(), buttons: MsgButtons::Ok, action: MsgAction::None });
                                return true;
                            }
                        }
                    }
                }
            }
            KeyCode::Char('m') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                let enter = KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE);
                return self.export_dialog_key(d, enter);
            }
            _ => {}
        }
        d.path.handle_key(key.code, key.modifiers);
        false
    }

    fn handle_main_key(&mut self, key: KeyEvent) {
        if self.focus == Focus::Editor {
            self.handle_editor_key(key);
        } else if self.multi_select {
            self.handle_multi_key(key);
        } else {
            self.handle_list_key(key);
        }
    }

    fn handle_multi_key(&mut self, key: KeyEvent) {
        match key.code {
            KeyCode::Char('q') | KeyCode::Char('v') | KeyCode::Esc => { self.multi_select = false; return; }
            KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => { self.multi_select = false; return; }
            KeyCode::Char('?') => { self.open_help(); return; }
            KeyCode::Down | KeyCode::Char('j') if matches!(key.code, KeyCode::Down) || !key.modifiers.contains(KeyModifiers::CONTROL) => {
                if key.code == KeyCode::Char('j') && key.modifiers.contains(KeyModifiers::CONTROL) { return; }
                if let Some(idx) = self.selected_index { self.move_selection(idx + 1); }
                return;
            }
            KeyCode::Up | KeyCode::Char('k') => {
                if let Some(idx) = self.selected_index { if idx > 0 { self.move_selection(idx - 1); } }
                return;
            }
            KeyCode::Home => { self.move_selection(0); return; }
            KeyCode::End => { if !self.displayed.is_empty() { self.move_selection(self.displayed.len() - 1); } return; }
            KeyCode::PageDown => {
                if let Some(idx) = self.selected_index { self.move_selection(idx + self.settings.scroll_per_page); }
                return;
            }
            KeyCode::PageUp => {
                if let Some(idx) = self.selected_index { self.move_selection(idx.saturating_sub(self.settings.scroll_per_page)); }
                return;
            }
            KeyCode::Char(' ') | KeyCode::Enter => {
                if let Some(id) = self.current_entry_id() {
                    if self.multi_selected.contains(&id) { self.multi_selected.remove(&id); } else { self.multi_selected.insert(id); }
                }
                return;
            }
            KeyCode::Char('m') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                if let Some(id) = self.current_entry_id() {
                    if self.multi_selected.contains(&id) { self.multi_selected.remove(&id); } else { self.multi_selected.insert(id); }
                }
                return;
            }
            KeyCode::Char('a') => {
                for e in &self.displayed { self.multi_selected.insert(e.id); }
                return;
            }
            KeyCode::Char('x') => { self.multi_selected.clear(); return; }
            KeyCode::Char('i') => {
                for e in &self.displayed {
                    let id = e.id;
                    if self.multi_selected.contains(&id) { self.multi_selected.remove(&id); } else { self.multi_selected.insert(id); }
                }
                return;
            }
            KeyCode::Char('d') | KeyCode::Delete => {
                if !self.multi_selected.is_empty() {
                    let ids: Vec<u32> = self.multi_selected.iter().cloned().collect();
                    let n = ids.len();
                    self.msgbox = Some(MsgBox {
                        kind: MsgKind::Question,
                        text: format!("Do you want to delete the selected {} entries", n),
                        buttons: MsgButtons::YesNo,
                        action: MsgAction::DeleteSelected(ids),
                    });
                }
                return;
            }
            KeyCode::Char('>') => { self.open_export_multi(); return; }
            _ => {}
        }
    }

    fn handle_list_key(&mut self, key: KeyEvent) {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        match key.code {
            KeyCode::Char('q') if !ctrl => {
                if self.check_unsaved(NextAction::Exit) { self.should_quit = true; }
            }
            KeyCode::Char('?') => { self.open_help(); }
            KeyCode::Tab => { self.cycle_focus_forward(); }
            KeyCode::Char('l') if ctrl => { self.cycle_focus_forward(); }
            KeyCode::BackTab => { self.cycle_focus_backward(); }
            KeyCode::Char('h') if ctrl => { self.cycle_focus_backward(); }
            KeyCode::Down => { if let Some(i) = self.selected_index { self.move_selection(i + 1); } }
            KeyCode::Char('j') if !ctrl => { if let Some(i) = self.selected_index { self.move_selection(i + 1); } }
            KeyCode::Up => { if let Some(i) = self.selected_index { self.move_selection(i.saturating_sub(1)); } }
            KeyCode::Char('k') if !ctrl => { if let Some(i) = self.selected_index { self.move_selection(i.saturating_sub(1)); } }
            KeyCode::Home => { self.move_selection(0); }
            KeyCode::End => { if !self.displayed.is_empty() { self.move_selection(self.displayed.len() - 1); } }
            KeyCode::PageDown => { if let Some(i) = self.selected_index { self.move_selection(i + self.settings.scroll_per_page); } }
            KeyCode::PageUp => { if let Some(i) = self.selected_index { self.move_selection(i.saturating_sub(self.settings.scroll_per_page)); } }
            KeyCode::Char('n') if !ctrl => { self.open_create_dialog(); }
            KeyCode::Char('e') if !ctrl => {
                if self.current_entry().is_some() {
                    if self.editor.modified && self.editor_entry_id == self.current_entry_id() {
                        // editing entry title while content modified: proceed to dialog (content preserved)
                        self.open_edit_dialog();
                    } else if self.editor.modified {
                        if self.check_unsaved(NextAction::OpenEditDialog) { self.open_edit_dialog(); }
                    } else {
                        self.open_edit_dialog();
                    }
                }
            }
            KeyCode::Delete => { self.request_delete_current(); }
            KeyCode::Char('d') if !ctrl => { self.request_delete_current(); }
            KeyCode::Char('d') if ctrl => { self.request_delete_current(); }
            KeyCode::Enter => {
                if self.current_entry().is_some() {
                    self.focus = Focus::Editor;
                    self.editor.mode = EditorMode::Edit;
                }
            }
            KeyCode::Char('m') if ctrl => {
                if self.current_entry().is_some() {
                    self.focus = Focus::Editor;
                    self.editor.mode = EditorMode::Edit;
                }
            }
            KeyCode::Esc => { self.editor.mode = EditorMode::Normal; self.editor.visual_anchor = None; }
            KeyCode::Char('c') if ctrl => { self.editor.mode = EditorMode::Normal; self.editor.visual_anchor = None; }
            KeyCode::Char('[') if ctrl => { self.editor.mode = EditorMode::Normal; self.editor.visual_anchor = None; }
            KeyCode::Char('s') if !ctrl => {
                if self.current_entry().is_none() {
                    panic!("Current entry id must have value when updating entry content");
                }
                self.save_editor_content();
            }
            KeyCode::Char('s') if ctrl => {
                if self.current_entry().is_some() { self.save_editor_content(); }
            }
            KeyCode::Char('q') if ctrl => {
                // Ctrl-q discard
                self.request_discard();
            }
            KeyCode::Char('r') if ctrl => {
                if self.check_unsaved(NextAction::Reload) { self.reload_all(); }
            }
            KeyCode::Char('>') => { self.open_export_single(); }
            KeyCode::Char('y') if !ctrl => {
                if self.current_entry().is_some() {
                    if self.check_unsaved(NextAction::ExternalEditor) { self.request_external = true; }
                }
            }
            KeyCode::Char('y') if ctrl => {
                if self.current_entry().is_some() {
                    if self.check_unsaved(NextAction::ExternalEditor) { self.request_external = true; }
                }
            }
            KeyCode::Char('v') if !ctrl => { self.multi_select = true; }
            KeyCode::Char('f') if !ctrl => { self.open_filter_dialog(); }
            KeyCode::Char('x') if !ctrl => {
                if self.is_filtered() {
                    self.filter = None;
                    self.tag_cycle = None;
                    self.refresh_display(true);
                    if !self.editor.modified { self.sync_editor_to_selected(false); }
                }
            }
            KeyCode::Char('t') if ctrl => { self.cycle_tag_filter(); }
            KeyCode::Char('a') if !ctrl => { self.open_fuzzy(); }
            KeyCode::Char('F') => { self.open_fuzzy(); }
            KeyCode::Char('f') if ctrl => { self.fullscreen = !self.fullscreen; }
            KeyCode::Char('o') if !ctrl => { self.open_sort_dialog(); }
            KeyCode::Char('u') if !ctrl => { self.undo(); }
            KeyCode::Char('U') => { self.redo(); }
            _ => {}
        }
    }

    fn request_delete_current(&mut self) {
        if self.current_entry().is_none() { return; }
        if self.editor.modified && self.editor_entry_id == self.current_entry_id() {
            // questionable; proceed with delete confirmation (editor content unsaved will be lost on delete)
            // To be safe, ask save first:
            if !self.check_unsaved(NextAction::OpenDeleteCurrent) { return; }
        }
        if let Some(id) = self.current_entry_id() {
            self.msgbox = Some(MsgBox {
                kind: MsgKind::Question,
                text: "Do you want to remove the current journal?".to_string(),
                buttons: MsgButtons::YesNo,
                action: MsgAction::DeleteCurrent(id),
            });
        }
    }

    fn request_discard(&mut self) {
        if self.editor.modified {
            self.msgbox = Some(MsgBox {
                kind: MsgKind::Question,
                text: "Do you want to discard all unsaved changes?".to_string(),
                buttons: MsgButtons::YesNo,
                action: MsgAction::DiscardEditor,
            });
        }
    }

    fn cycle_focus_forward(&mut self) {
        if self.current_entry().is_none() && self.editor_entry_id.is_none() {
            // Still allow? original seems to keep list focus when no entry; keep as is.
            // To match many cases, do nothing when no entries.
            if self.displayed.is_empty() { return; }
        }
        self.focus = Focus::Editor;
        if self.editor.mode == EditorMode::Edit {
            self.editor.mode = EditorMode::Normal;
        }
    }
    fn cycle_focus_backward(&mut self) {
        // two controls only: backward == forward toggles in 2-pane layout
        if self.displayed.is_empty() { return; }
        self.focus = Focus::Editor;
        if self.editor.mode == EditorMode::Edit { self.editor.mode = EditorMode::Normal; }
    }

    fn cycle_tag_filter(&mut self) {
        let mut tags = self.all_tags_sorted();
        tags.push(NO_TAGS.to_string());
        if tags.is_empty() { return; }
        let next = match &self.tag_cycle {
            Some(cur) => {
                if let Some(pos) = tags.iter().position(|t| t == cur) {
                    tags[(pos + 1) % tags.len()].clone()
                } else { tags[0].clone() }
            }
            None => {
                // derive from current single-tag filter
                if let Some(f) = &self.filter {
                    if f.tags.len() == 1 && f.title.is_empty() && f.content.is_empty() && f.priority.is_none() {
                        if let Some(pos) = tags.iter().position(|t| t == &f.tags[0]) {
                            tags[(pos + 1) % tags.len()].clone()
                        } else { tags[0].clone() }
                    } else { tags[0].clone() }
                } else { tags[0].clone() }
            }
        };
        self.tag_cycle = Some(next.clone());
        self.filter = Some(FilterState {
            title: String::new(),
            content: String::new(),
            priority: None,
            tags: vec![next],
            logic: MatchingLogic::All,
        });
        self.refresh_display(true);
        if !self.editor.modified { self.sync_editor_to_selected(false); }
    }

    fn handle_editor_key(&mut self, key: KeyEvent) {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        // Mode independent app shortcuts
        match self.editor.mode {
            EditorMode::Edit => {
                match key.code {
                    KeyCode::Esc => { self.editor.mode = EditorMode::Normal; self.editor.visual_anchor = None; return; }
                    KeyCode::Char('c') if ctrl => { self.editor.mode = EditorMode::Normal; self.editor.visual_anchor = None; return; }
                    KeyCode::Char('[') if ctrl => { self.editor.mode = EditorMode::Normal; self.editor.visual_anchor = None; return; }
                    KeyCode::Char('s') if ctrl => { self.save_editor_content(); return; }
                    KeyCode::Char('q') if ctrl => { self.request_discard(); return; }
                    KeyCode::Char('p') if ctrl => { self.clipboard_error(); return; }
                    _ => {}
                }
                self.editor_edit_key(key);
            }
            EditorMode::Normal | EditorMode::Visual => {
                // Global-ish keys first
                match key.code {
                    KeyCode::Char('q') if !ctrl => {
                        if self.check_unsaved(NextAction::Exit) { self.should_quit = true; }
                        return;
                    }
                    KeyCode::Char('?') => { self.open_help(); return; }
                    KeyCode::Tab => { self.focus = Focus::Journals; return; }
                    KeyCode::Char('l') if ctrl => { self.focus = Focus::Journals; return; }
                    KeyCode::BackTab => { self.focus = Focus::Journals; return; }
                    KeyCode::Char('h') if ctrl => { self.focus = Focus::Journals; return; }
                    KeyCode::Char('f') if ctrl => { self.fullscreen = !self.fullscreen; return; }
                    KeyCode::Char('s') if ctrl => { self.save_editor_content(); return; }
                    KeyCode::Char('s') if !ctrl && self.editor.mode == EditorMode::Normal => { self.save_editor_content(); return; }
                    KeyCode::Char('q') if ctrl => { self.request_discard(); return; }
                    KeyCode::Char('r') if ctrl => {
                        if self.check_unsaved(NextAction::Reload) { self.reload_all(); }
                        return;
                    }
                    KeyCode::Char('>') => { self.open_export_single(); return; }
                    KeyCode::Char('y') if ctrl => { self.request_external = true; return; }
                    KeyCode::Enter => { self.editor.mode = EditorMode::Edit; return; }
                    KeyCode::Char('m') if ctrl => { self.editor.mode = EditorMode::Edit; return; }
                    KeyCode::Char('v') if ctrl => { self.clipboard_error(); return; }
                    KeyCode::Char('x') if ctrl => { self.clipboard_error(); return; }
                    KeyCode::Char('p') if ctrl => { self.clipboard_error(); return; }
                    KeyCode::Esc => {
                        if self.editor.mode == EditorMode::Visual {
                            self.editor.mode = EditorMode::Normal;
                            self.editor.visual_anchor = None;
                        }
                        return;
                    }
                    KeyCode::Char('c') if ctrl => {
                        if self.editor.mode == EditorMode::Visual {
                            self.editor.mode = EditorMode::Normal;
                            self.editor.visual_anchor = None;
                        }
                        return;
                    }
                    KeyCode::Char('[') if ctrl => {
                        if self.editor.mode == EditorMode::Visual {
                            self.editor.mode = EditorMode::Normal;
                            self.editor.visual_anchor = None;
                        }
                        return;
                    }
                    _ => {}
                }
                if self.editor.mode == EditorMode::Visual {
                    self.editor_visual_key(key);
                } else {
                    self.editor_normal_key(key);
                }
            }
        }
    }

    fn clipboard_error(&mut self) {
        self.msgbox = Some(MsgBox {
            kind: MsgKind::Error,
            text: "Error while communicating with the operation system clipboard. Error Details: Unknown error while interacting with the clipboard: X11 server connection timed out because".to_string(),
            buttons: MsgButtons::Ok,
            action: MsgAction::None,
        });
    }

    fn editor_edit_key(&mut self, key: KeyEvent) {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        let alt = key.modifiers.contains(KeyModifiers::ALT);
        match key.code {
            KeyCode::Char(ch) => {
                if ctrl {
                    match ch {
                        'f' => self.editor.move_right(),
                        'b' => self.editor.move_left(),
                        'n' => self.editor.move_down(),
                        'p' => self.editor.move_up(),
                        'a' => self.editor.line_start(),
                        'e' => self.editor.line_end(),
                        'd' => self.editor.delete_char(),
                        'h' => self.editor.backspace(),
                        'k' => {
                            // delete to end of line
                            let row = self.editor.row;
                            let col = self.editor.col;
                            let len = self.editor.line_len(row);
                            if col < len {
                                let line = self.editor.lines[row].clone();
                                self.editor.lines[row] = line.chars().take(col).collect();
                                self.editor.modified = true;
                            } else {
                                self.editor.delete_char();
                            }
                        }
                        _ => {}
                    }
                } else if alt {
                    match ch {
                        'f' => self.editor.word_forward(),
                        'b' => self.editor.word_back(),
                        'd' => {
                            // delete next word
                            let start = (self.editor.row, self.editor.col);
                            self.editor.word_forward();
                            let end = (self.editor.row, self.editor.col);
                            self.delete_range(start, end);
                        }
                        _ => {}
                    }
                } else {
                    self.editor.insert_char(ch);
                }
            }
            KeyCode::Enter => { self.editor.insert_newline(); }
            KeyCode::Char('m') if ctrl => { self.editor.insert_newline(); }
            KeyCode::Backspace => {
                if alt {
                    // Alt-Backspace delete prev word
                    let end = (self.editor.row, self.editor.col);
                    self.editor.word_back();
                    let start = (self.editor.row, self.editor.col);
                    self.delete_range(start, end);
                } else {
                    self.editor.backspace();
                }
            }
            KeyCode::Delete => { self.editor.delete_char(); }
            KeyCode::Left => { self.editor.move_left(); }
            KeyCode::Right => { self.editor.move_right(); }
            KeyCode::Up => { self.editor.move_down_inv(); }
            KeyCode::Down => { self.editor.move_down(); }
            KeyCode::Home => { self.editor.line_start(); }
            KeyCode::End => { self.editor.line_end(); }
            KeyCode::Tab => { self.editor.insert_char('\t'); }
            _ => {}
        }
    }

    fn delete_range(&mut self, start: (usize, usize), end: (usize, usize)) {
        // delete [start,end) using temporary visual selection machinery
        self.editor.visual_anchor = Some(start);
        self.editor.row = end.0;
        self.editor.col = end.1;
        // manual extract/delete exclusive
        let (sr, sc) = start;
        let (er, ec) = end;
        if sr == er {
            let line = self.editor.lines[sr].clone();
            let chars: Vec<char> = line.chars().collect();
            self.editor.lines[sr] = chars.iter().take(sc).chain(chars.iter().skip(ec)).collect();
        } else {
            let first = self.editor.lines[sr].clone();
            let last = self.editor.lines[er].clone();
            let fc: Vec<char> = first.chars().collect();
            let lc: Vec<char> = last.chars().collect();
            let merged: String = fc.iter().take(sc).chain(lc.iter().skip(ec)).collect();
            self.editor.lines.drain(sr + 1..=er);
            self.editor.lines[sr] = merged;
        }
        self.editor.row = sr;
        self.editor.col = sc;
        self.editor.visual_anchor = None;
        self.editor.modified = true;
    }

    fn editor_normal_key(&mut self, key: KeyEvent) {
        // pending d operator
        if self.editor.pending_d {
            self.editor.pending_d = false;
            match key.code {
                KeyCode::Char('d') => {
                    let line = self.editor.delete_current_line();
                    self.editor.clipboard = line;
                    self.editor.clipboard_linewise = true;
                    return;
                }
                KeyCode::Char('w') => {
                    let start = (self.editor.row, self.editor.col);
                    self.editor.word_forward();
                    let end = (self.editor.row, self.editor.col);
                    self.delete_range(start, end);
                    return;
                }
                _ => {
                    // fall through with current key reprocessed below
                }
            }
        }
        match key.code {
            KeyCode::Char('h') | KeyCode::Left => self.editor.move_left(),
            KeyCode::Char('l') | KeyCode::Right => self.editor.move_right(),
            KeyCode::Char('j') | KeyCode::Down => self.editor.move_down(),
            KeyCode::Char('k') | KeyCode::Up => self.editor.move_up(),
            KeyCode::Char('i') => { self.editor.mode = EditorMode::Edit; }
            KeyCode::Char('a') => {
                self.editor.move_right();
                self.editor.mode = EditorMode::Edit;
            }
            KeyCode::Char('A') => { self.editor.line_end(); self.editor.mode = EditorMode::Edit; }
            KeyCode::Char('I') => { self.editor.first_non_blank(); self.editor.mode = EditorMode::Edit; }
            KeyCode::Char('o') => {
                self.editor.lines.insert(self.editor.row + 1, String::new());
                self.editor.row += 1;
                self.editor.col = 0;
                self.editor.modified = true;
                self.editor.mode = EditorMode::Edit;
            }
            KeyCode::Char('O') => {
                self.editor.lines.insert(self.editor.row, String::new());
                self.editor.col = 0;
                self.editor.modified = true;
                self.editor.mode = EditorMode::Edit;
            }
            KeyCode::Char('x') => {
                let _deleted = self.editor.delete_char_no_modified();
                self.clipboard_error();
            }
            KeyCode::Char('d') => { self.editor.pending_d = true; }
            KeyCode::Char('v') => {
                self.editor.mode = EditorMode::Visual;
                self.editor.visual_anchor = Some((self.editor.row, self.editor.col));
            }
            KeyCode::Char('w') => self.editor.word_forward(),
            KeyCode::Char('b') => self.editor.word_back(),
            KeyCode::Char('e') => self.editor.word_end(),
            KeyCode::Char('u') => { self.undo(); }
            KeyCode::Char('U') => { self.redo(); }
            KeyCode::Char('y') => {
                // yy handled as double: track pending via clipboard_linewise flag? Use pending_d-like: first y sets anchor temporary
                // Simplify: yank current line
                let line = self.editor.lines[self.editor.row].clone();
                self.editor.clipboard = line;
                self.editor.clipboard_linewise = true;
            }
            KeyCode::Char('p') => {
                if self.editor.clipboard_linewise {
                    let line = self.editor.clipboard.clone();
                    self.editor.lines.insert(self.editor.row + 1, line);
                    self.editor.row += 1;
                    self.editor.col = 0;
                    self.editor.modified = true;
                } else if !self.editor.clipboard.is_empty() {
                    let txt = self.editor.clipboard.clone();
                    self.editor.insert_text(&txt);
                }
            }
            KeyCode::Home => self.editor.line_start(),
            KeyCode::End => self.editor.line_end(),
            KeyCode::PageDown => {
                for _ in 0..10 { self.editor.move_down(); }
            }
            KeyCode::PageUp => {
                for _ in 0..10 { self.editor.move_up(); }
            }
            _ => {}
        }
    }

    fn editor_visual_key(&mut self, key: KeyEvent) {
        match key.code {
            KeyCode::Char('h') | KeyCode::Left => self.editor.move_left(),
            KeyCode::Char('l') | KeyCode::Right => self.editor.move_right(),
            KeyCode::Char('j') | KeyCode::Down => self.editor.move_down(),
            KeyCode::Char('k') | KeyCode::Up => self.editor.move_up(),
            KeyCode::Char('w') => self.editor.word_forward(),
            KeyCode::Char('b') => self.editor.word_back(),
            KeyCode::Char('e') => self.editor.word_end(),
            KeyCode::Char('v') => {
                self.editor.mode = EditorMode::Normal;
                self.editor.visual_anchor = None;
            }
            KeyCode::Char('d') => {
                let text = self.editor.delete_selection(true);
                self.editor.clipboard = text;
                self.editor.clipboard_linewise = false;
                self.editor.mode = EditorMode::Normal;
                self.editor.visual_anchor = None;
            }
            KeyCode::Char('y') => {
                let text = self.editor.yank_selection();
                self.editor.clipboard = text;
                self.editor.mode = EditorMode::Normal;
                self.editor.visual_anchor = None;
            }
            KeyCode::Char('c') => {
                let text = self.editor.delete_selection(true);
                self.editor.clipboard = text;
                self.editor.mode = EditorMode::Edit;
                self.editor.visual_anchor = None;
            }
            KeyCode::Char('x') => {
                self.clipboard_error();
            }
            KeyCode::Home => self.editor.line_start(),
            KeyCode::End => self.editor.line_end(),
            _ => {}
        }
    }
}

impl Editor {
    fn move_down_inv(&mut self) {
        // placeholder to keep edit Up handling obvious (move_up)
        self.move_up();
    }
}

pub fn parse_tags_input(text: &str) -> Vec<String> {
    if text.is_empty() {
        Vec::new()
    } else {
        text.split(',').map(|s| s.trim().to_string()).collect()
    }
}

pub fn text_matches(haystack: &str, query: &str) -> bool {
    // Smart-case substring: all-lowercase query is case-insensitive, otherwise case-sensitive.
    if query.chars().all(|c| !c.is_uppercase()) {
        haystack.to_lowercase().contains(&query.to_lowercase())
    } else {
        haystack.contains(query)
    }
}

pub fn fuzzy_score(title: &str, query: &str) -> Option<i64> {
    // DP over chars maximizing a skim-like score.
    let t: Vec<char> = title.chars().collect();
    let q: Vec<char> = query.chars().collect();
    if q.is_empty() { return None; }
    let tl: Vec<char> = title.to_lowercase().chars().collect();
    let ql: Vec<char> = query.to_lowercase().chars().collect();
    // Use DP for optimal alignment (simple)
    let n = t.len();
    let m = q.len();
    if m > n && n > 0 {
        // subsequence still possible if chars are ... m>n cannot be subsequence
        return None;
    }
    const NEG: i64 = -1_000_000;
    // dp[i][j] best score matching q[..j] within t[..i], with t[i-1] matched as j-th if taking
    let mut dp = vec![vec![NEG; m + 1]; n + 1];
    for i in 0..=n { dp[i][0] = 0; }
    for i in 1..=n {
        for j in 1..=m {
            let mut best = dp[i - 1][j]; // skip t[i-1]
            if tl[i - 1] == ql[j - 1] {
                let mut bonus: i64 = 16;
                if i == 1 || !t[i - 2].is_alphanumeric() { bonus += 8; }
                // consecutive bonus if previous also matched in dp path: approximate using dp[i-1][j-1] plus bonus
                let cand = dp[i - 1][j - 1] + bonus;
                if cand > best { best = cand; }
            }
            dp[i][j] = best;
        }
    }
    let score = dp[n][m];
    if score <= NEG / 2 {
        // verify subsequence
        let mut ti = 0;
        for qc in &ql {
            let mut found = false;
            while ti < tl.len() {
                if &tl[ti] == qc { found = true; ti += 1; break; }
                ti += 1;
            }
            if !found { return None; }
        }
        return Some(0);
    }
    // Penalize length slightly and gaps implicitly handled poorly; add preference for early matches:
    // Recompute greedy positions for a positional bonus.
    let mut pos: Vec<usize> = Vec::new();
    let mut ti = 0;
    for qc in &ql {
        while ti < tl.len() && &tl[ti] != qc { ti += 1; }
        if ti >= tl.len() { return None; }
        pos.push(ti);
        ti += 1;
    }
    let mut s = score;
    if let (Some(&first), Some(&last)) = (pos.first(), pos.last()) {
        s -= first as i64;
        s -= (last - first + 1 - m) as i64 * 2;
        // consecutive bonus
        for w in pos.windows(2) { if w[1] == w[0] + 1 { s += 5; } }
    }
    s -= (n - m) as i64;
    Some(s)
}
