pub fn run(
    settings: Settings,
    styles: Styles,
    pre_action: Option<PreAction>,
) -> anyhow::Result<()> {
    // Create provider (sqlite creation/migrations are fatal before terminal init)
    let mut provider: Box<dyn DataProvider> = match settings.backend_type {
        BackendType::Json => Box::new(JsonProvider { path: settings.json_backend.file_path.clone() }),
        BackendType::Sqlite => Box::new(SqliteProvider::new(settings.sqlite_backend.file_path.clone())?),
    };

    // App state
    let state_path = settings.app_state_dir.join("state.json");
    let (sorter, fullscreen, state_can_save) = load_app_state(&state_path);

    let mut app = App {
        settings,
        styles,
        provider,
        entries: Vec::new(),
        displayed: Vec::new(),
        selected_index: None,
        focus: Focus::Journals,
        fullscreen,
        multi_select: false,
        multi_selected: HashSet::new(),
        editor: Editor::default(),
        editor_entry_id: None,
        popup: None,
        msgbox: None,
        should_quit: false,
        sorter,
        filter: None,
        undo_stack: Vec::new(),
        redo_stack: Vec::new(),
        list_scroll: 0,
        state_can_save,
        request_external: false,
        external_failed_msg: None,
        tag_cycle: None,
    };

    crate::logging::log_loading_entries();
    let mut initial_msg: Option<MsgBox> = None;
    match app.provider.load_entries() {
        Ok(entries) => {
            app.entries = entries;
        }
        Err(e) => {
            app.entries = Vec::new();
            initial_msg = Some(MsgBox {
                kind: MsgKind::Error,
                text: e.to_string(),
                buttons: MsgButtons::Ok,
                action: MsgAction::None,
            });
        }
    }
    app.refresh_display(true);
    if app.selected_index.is_none() && !app.displayed.is_empty() {
        app.selected_index = Some(0);
    }
    app.sync_editor_to_selected(false);

    // Terminal init (fails with ENXIO when no tty, before pre-actions take effect)
    let mut terminal = init_terminal()?;
    crate::logging::log_mio();

    if let Some(msg) = initial_msg {
        app.msgbox = Some(msg);
    }

    // Pre-actions processed inside the app after terminal init
    if let Some(action) = pre_action {
        app.handle_pre_action(action);
    }

    let result = run_loop(&mut terminal, &mut app);

    restore_terminal(&mut terminal)?;
    result?;

    // Save app state on normal exit
    if app.state_can_save {
        let state = AppStateFile { sorter: app.sorter.clone(), full_screen: app.fullscreen };
        if let Some(parent) = state_path.parent() {
            let _ = std::fs::create_dir_all(parent);
        }
        if let Ok(text) = serde_json::to_string_pretty(&state) {
            let _ = std::fs::write(&state_path, text);
        }
    }
    Ok(())
}

fn load_app_state(path: &PathBuf) -> (SorterState, bool, bool) {
    if !path.exists() {
        return (SorterState::default(), false, true);
    }
    match std::fs::read_to_string(path) {
        Ok(text) => match serde_json::from_str::<AppStateFile>(&text) {
            Ok(state) => (state.sorter, state.full_screen, true),
            Err(_) => (SorterState::default(), false, false),
        },
        Err(_) => (SorterState::default(), false, false),
    }
}

fn init_terminal() -> anyhow::Result<Terminal<CrosstermBackend<Stdout>>> {
    // panic hook to restore terminal
    let original_hook = std::panic::take_hook();
    std::panic::set_hook(Box::new(move |info| {
        let _ = crossterm::terminal::disable_raw_mode();
        let _ = crossterm::execute!(std::io::stdout(), crossterm::terminal::LeaveAlternateScreen, crossterm::cursor::Show);
        original_hook(info);
    }));
    crossterm::terminal::enable_raw_mode()?;
    let mut stdout = std::io::stdout();
    crossterm::execute!(stdout, crossterm::terminal::EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut term = Terminal::new(backend)?;
    term.clear()?;
    Ok(term)
}
fn restore_terminal(term: &mut Terminal<CrosstermBackend<Stdout>>) -> anyhow::Result<()> {
    let _ = crossterm::terminal::disable_raw_mode();
    let _ = crossterm::execute!(std::io::stdout(), crossterm::terminal::LeaveAlternateScreen, crossterm::cursor::Show);
    term.show_cursor()?;
    Ok(())
}

fn run_loop(term: &mut Terminal<CrosstermBackend<Stdout>>, app: &mut App) -> anyhow::Result<()> {
    loop {
        term.draw(|frame| {
            ui::draw(frame, app);
        })?;
        if app.should_quit {
            break;
        }
        if app.request_external {
            app.request_external = false;
            // restore terminal temporarily
            let _ = crossterm::terminal::disable_raw_mode();
            let _ = crossterm::execute!(std::io::stdout(), crossterm::terminal::LeaveAlternateScreen, crossterm::cursor::Show);
            app.do_external_editor();
            // re-enter
            crossterm::terminal::enable_raw_mode()?;
            let _ = crossterm::execute!(std::io::stdout(), crossterm::terminal::EnterAlternateScreen);
            term.clear()?;
            continue;
        }
        let event = crossterm::event::read()?;
        if let Event::Key(key) = event {
            if key.kind == KeyEventKind::Release {
                continue;
            }
            app.handle_key(key);
        }
    }
    Ok(())
}

impl App {
    pub fn current_entry(&self) -> Option<&Entry> {
        let idx = self.selected_index?;
        self.displayed.get(idx)
    }
    pub fn current_entry_id(&self) -> Option<u32> {
        self.current_entry().map(|e| e.id)
    }

    fn handle_pre_action(&mut self, action: PreAction) {
        match action {
            PreAction::AssignPriority(priority) => {
                if let Ok(()) = self.provider.assign_priority(priority) {
                    if let Ok(entries) = self.provider.load_entries() {
                        self.entries = entries;
                        self.refresh_display(true);
                        self.sync_editor_to_selected(false);
                    }
                }
            }
            PreAction::Import(path) => {
                if !path.exists() {
                    self.msgbox = Some(MsgBox {
                        kind: MsgKind::Error,
                        text: format!("Import file doesn't exist: path {}", path.display()),
                        buttons: MsgButtons::Ok,
                        action: MsgAction::None,
                    });
                    return;
                }
                let parsed: Result<EntriesTransfer, String> = match std::fs::read_to_string(&path) {
                    Ok(content) => serde_json::from_str::<EntriesTransfer>(&content)
                        .map_err(|e| e.to_string()),
                    Err(e) => Err(e.to_string()),
                };
                match parsed {
                    Ok(transfer) => {
                        if let Ok(_added) = self.provider.import_entries(&transfer.entries) {
                            if let Ok(entries) = self.provider.load_entries() {
                                self.entries = entries;
                                self.refresh_display(true);
                                self.sync_editor_to_selected(false);
                            }
                        }
                    }
                    Err(e) => {
                        self.msgbox = Some(MsgBox {
                            kind: MsgKind::Error,
                            text: format!("Error while parsing import file. Error: {}", e),
                            buttons: MsgButtons::Ok,
                            action: MsgAction::None,
                        });
                    }
                }
            }
        }
    }

    pub fn refresh_display(&mut self, keep_id: bool) {
        let prev_id = if keep_id { self.current_entry_id() } else { None };
        let prev_index = self.selected_index;
        let mut items: Vec<Entry> = self
            .entries
            .iter()
            .filter(|e| self.matches_filter(e))
            .cloned()
            .collect();
        let criteria = self.sorter.criteria.clone();
        let order = self.sorter.order;
        items.sort_by(|a, b| {
            let mut cmp = std::cmp::Ordering::Equal;
            for c in &criteria {
                cmp = match c {
                    SortCriteria::Date => a.date.cmp(&b.date),
                    SortCriteria::Priority => a.priority.cmp(&b.priority),
                    SortCriteria::Title => a.title.cmp(&b.title),
                };
                if cmp != std::cmp::Ordering::Equal {
                    break;
                }
            }
            if order == SortOrder::Descending { cmp.reverse() } else { cmp }
        });
        self.displayed = items;
        if self.displayed.is_empty() {
            self.selected_index = None;
        } else if let Some(pid) = prev_id {
            if let Some(pos) = self.displayed.iter().position(|e| e.id == pid) {
                self.selected_index = Some(pos);
            } else if let Some(pi) = prev_index {
                self.selected_index = Some(pi.min(self.displayed.len() - 1));
            } else {
                self.selected_index = Some(0);
            }
        } else if let Some(pi) = prev_index {
            self.selected_index = Some(pi.min(self.displayed.len() - 1));
        } else {
            self.selected_index = Some(0);
        }
    }

    fn matches_filter(&self, entry: &Entry) -> bool {
        let Some(f) = &self.filter else { return true };
        if !f.has_criteria() { return true; }
        let mut checks: Vec<bool> = Vec::new();
        if !f.title.is_empty() {
            checks.push(text_matches(&entry.title, &f.title));
        }
        if !f.content.is_empty() {
            checks.push(text_matches(&entry.content, &f.content));
        }
        if let Some(p) = f.priority {
            checks.push(entry.priority == Some(p));
        }
        if !f.tags.is_empty() {
            for tag in &f.tags {
                if tag == NO_TAGS {
                    checks.push(entry.tags.is_empty());
                } else {
                    checks.push(entry.tags.iter().any(|t| t == tag));
                }
            }
        }
        if checks.is_empty() { return true; }
        match f.logic {
            MatchingLogic::All => checks.iter().all(|b| *b),
            MatchingLogic::Any => checks.iter().any(|b| *b),
        }
    }

    pub fn is_filtered(&self) -> bool {
        self.filter.as_ref().map(|f| f.has_criteria()).unwrap_or(false)
    }

    pub fn sync_editor_to_selected(&mut self, keep_mode: bool) {
        if self.editor.modified {
            return;
        }
        let _ = keep_mode;
        match self.current_entry().cloned() {
            Some(entry) => {
                let mode_before = self.editor.mode;
                self.editor.load(&entry.content);
                self.editor.mode = mode_before;
                // load() sets Normal mode; restore logic: if we were in editor focus the caller manages mode.
                // For initial/list sync we want Normal marker hidden anyway; internal default Normal.
                self.editor_entry_id = Some(entry.id);
            }
            None => {
                self.editor.load("");
                self.editor_entry_id = None;
            }
        }
    }

    // Load editor for entry unconditionally keeping mode
    fn load_editor_for(&mut self, entry: &Entry) {
        let mode = self.editor.mode;
        self.editor.load(&entry.content);
        self.editor.mode = mode;
        self.editor_entry_id = Some(entry.id);
    }

    pub fn push_history(&mut self) {
        if self.settings.history_limit == 0 {
            self.undo_stack.clear();
            return;
        }
        self.undo_stack.push(self.entries.clone());
        while self.undo_stack.len() > self.settings.history_limit {
            self.undo_stack.remove(0);
        }
        self.redo_stack.clear();
    }

    fn apply_entries_to_provider(&mut self, entries: &[Entry]) -> anyhow::Result<()> {
        // Replace all entries in provider with given snapshot
        match self.settings.backend_type {
            BackendType::Json => {
                let text = serde_json::to_string(entries)?;
                std::fs::write(&self.settings.json_backend.file_path, text)?;
            }
            BackendType::Sqlite => {
                // delete all then insert with ids
                if let Ok(current) = self.provider.load_entries() {
                    let ids: Vec<u32> = current.iter().map(|e| e.id).collect();
                    let _ = self.provider.delete_entries(&ids);
                }
                // Insert with fixed ids using raw drafts loses ids for sqlite; need direct method:
                // add then update id is not possible. Instead use provider.add for each then ... 
                // SqliteProvider does not expose insert with id; entries will get new ids close to original if emptied.
                for e in entries {
                    let draft = TransferEntry { date: e.date, title: e.title.clone(), content: e.content.clone(), tags: e.tags.clone(), priority: e.priority };
                    let _ = self.provider.add_entry(&draft);
                }
            }
        }
        Ok(())
    }

    fn undo(&mut self) {
        let Some(snapshot) = self.undo_stack.pop() else { return };
        self.redo_stack.push(self.entries.clone());
        while self.redo_stack.len() > self.settings.history_limit && self.settings.history_limit > 0 {
            self.redo_stack.remove(0);
        }
        let _ = self.apply_entries_to_provider(&snapshot);
        if let Ok(entries) = self.provider.load_entries() {
            self.entries = entries;
        } else {
            self.entries = snapshot;
        }
        self.refresh_display(true);
        if !self.editor.modified { self.sync_editor_to_selected(false); }
    }
    fn redo(&mut self) {
        let Some(snapshot) = self.redo_stack.pop() else { return };
        self.undo_stack.push(self.entries.clone());
        let _ = self.apply_entries_to_provider(&snapshot);
        if let Ok(entries) = self.provider.load_entries() {
            self.entries = entries;
        } else {
            self.entries = snapshot;
        }
        self.refresh_display(true);
        if !self.editor.modified { self.sync_editor_to_selected(false); }
    }

    fn reload_all(&mut self) {
        match self.provider.load_entries() {
            Ok(entries) => {
                self.entries = entries;
                self.refresh_display(true);
                if !self.editor.modified { self.sync_editor_to_selected(false); }
            }
            Err(e) => {
                self.msgbox = Some(MsgBox {
                    kind: MsgKind::Error,
                    text: e.to_string(),
                    buttons: MsgButtons::Ok,
                    action: MsgAction::None,
                });
            }
        }
    }

    fn save_editor_content(&mut self) {
        let Some(entry_id) = self.editor_entry_id else {
            // Mirrors original panic when 's' is pressed with no entry (handled in key code)
            return;
        };
        // Find entry in storage
        let Some(mut entry) = self.entries.iter().find(|e| e.id == entry_id).cloned() else { return };
        if entry.content == self.editor.content() && !self.editor.modified {
            // Still update (original writes file even if unmodified via Ctrl-s in some cases).
            // Keep behaviour simple: proceed to write only if caller forced.
        }
        self.push_history();
        entry.content = self.editor.content();
        if self.provider.update_entry(&entry).is_ok() {
            if let Ok(entries) = self.provider.load_entries() {
                self.entries = entries;
                self.refresh_display(true);
            } else if let Some(e) = self.entries.iter_mut().find(|e| e.id == entry_id) {
                e.content = entry.content.clone();
                self.refresh_display(true);
            }
            self.editor.saved_content = entry.content.clone();
            self.editor.modified = false;
            // reload editor content positions remain
            self.editor_entry_id = Some(entry_id);
        }
    }

    fn discard_editor(&mut self) {
        if let Some(entry) = self.entries.iter().find(|e| Some(e.id) == self.editor_entry_id).cloned() {
            let mode = self.editor.mode;
            self.editor.load(&entry.content);
            self.editor.mode = mode;
        } else {
            self.editor.load(&self.editor.saved_content.clone());
        }
        self.editor.modified = false;
    }

    fn check_unsaved(&mut self, next: NextAction) -> bool {
        // returns true if caller should proceed immediately
        if self.editor.modified {
            self.msgbox = Some(MsgBox {
                kind: MsgKind::Question,
                text: "Do you want to save the changes on the current journal?".to_string(),
                buttons: MsgButtons::YesNoCancel,
                action: MsgAction::Unsaved(next),
            });
            false
        } else {
            true
        }
    }

    fn perform_next(&mut self, next: NextAction) {
        match next {
            NextAction::Exit => { self.should_quit = true; }
            NextAction::SelectIndex(idx) => {
                if !self.displayed.is_empty() {
                    self.selected_index = Some(idx.min(self.displayed.len() - 1));
                    // sync editor to new entry
                    self.editor.modified = false;
                    if let Some(entry) = self.current_entry().cloned() {
                        self.load_editor_for(&entry);
                    }
                }
            }
            NextAction::Reload => { self.reload_all(); }
            NextAction::OpenDeleteCurrent => {
                if let Some(id) = self.current_entry_id() {
                    self.msgbox = Some(MsgBox {
                        kind: MsgKind::Question,
                        text: "Do you want to remove the current journal?".to_string(),
                        buttons: MsgButtons::YesNo,
                        action: MsgAction::DeleteCurrent(id),
                    });
                }
            }
            NextAction::OpenEditDialog => { self.open_edit_dialog(); }
            NextAction::ExternalEditor => { self.request_external = true; }
            NextAction::FocusEditorEdit => {
                self.focus = Focus::Editor;
                self.editor.mode = EditorMode::Edit;
            }
        }
    }

    fn move_selection(&mut self, new_index: usize) {
        if self.displayed.is_empty() { return; }
        let new_index = new_index.min(self.displayed.len() - 1);
        if Some(new_index) == self.selected_index { return; }
        let target_id = self.displayed.get(new_index).map(|e| e.id);
        if self.editor.modified && target_id != self.editor_entry_id {
            if self.check_unsaved(NextAction::SelectIndex(new_index)) {
                self.perform_next(NextAction::SelectIndex(new_index));
            }
        } else {
            self.selected_index = Some(new_index);
            if let Some(entry) = self.current_entry().cloned() {
                self.load_editor_for(&entry);
            }
        }
    }

