pub fn parse_tags_input(text: &str) -> Vec<String> {
    if text.is_empty() {
        Vec::new()
    } else {
        text.split(',').map(|s| s.trim().to_string()).collect()
    }
}

pub fn text_matches(haystack: &str, query: &str) -> bool {
    // Smart-case substring: all-lowercase query is case-insensitive, otherwise case-sensitive.
    if query.chars().all(|c| !c.is_uppercase()) {
        haystack.to_lowercase().contains(&query.to_lowercase())
    } else {
        haystack.contains(query)
    }
}

pub fn fuzzy_score(title: &str, query: &str) -> Option<i64> {
    // DP over chars maximizing a skim-like score.
    let t: Vec<char> = title.chars().collect();
    let q: Vec<char> = query.chars().collect();
    if q.is_empty() { return None; }
    let tl: Vec<char> = title.to_lowercase().chars().collect();
    let ql: Vec<char> = query.to_lowercase().chars().collect();
    // Use DP for optimal alignment (simple)
    let n = t.len();
    let m = q.len();
    if m > n && n > 0 {
        // subsequence still possible if chars are ... m>n cannot be subsequence
        return None;
    }
    const NEG: i64 = -1_000_000;
    // dp[i][j] best score matching q[..j] within t[..i], with t[i-1] matched as j-th if taking
    let mut dp = vec![vec![NEG; m + 1]; n + 1];
    for i in 0..=n { dp[i][0] = 0; }
    for i in 1..=n {
        for j in 1..=m {
            let mut best = dp[i - 1][j]; // skip t[i-1]
            if tl[i - 1] == ql[j - 1] {
                let mut bonus: i64 = 16;
                if i == 1 || !t[i - 2].is_alphanumeric() { bonus += 8; }
                // consecutive bonus if previous also matched in dp path: approximate using dp[i-1][j-1] plus bonus
                let cand = dp[i - 1][j - 1] + bonus;
                if cand > best { best = cand; }
            }
            dp[i][j] = best;
        }
    }
    let score = dp[n][m];
    if score <= NEG / 2 {
        // verify subsequence
        let mut ti = 0;
        for qc in &ql {
            let mut found = false;
            while ti < tl.len() {
                if &tl[ti] == qc { found = true; ti += 1; break; }
                ti += 1;
            }
            if !found { return None; }
        }
        return Some(0);
    }
    // Penalize length slightly and gaps implicitly handled poorly; add preference for early matches:
    // Recompute greedy positions for a positional bonus.
    let mut pos: Vec<usize> = Vec::new();
    let mut ti = 0;
    for qc in &ql {
        while ti < tl.len() && &tl[ti] != qc { ti += 1; }
        if ti >= tl.len() { return None; }
        pos.push(ti);
        ti += 1;
    }
    let mut s = score;
    if let (Some(&first), Some(&last)) = (pos.first(), pos.last()) {
        s -= first as i64;
        s -= (last - first + 1 - m) as i64 * 2;
        // consecutive bonus
        for w in pos.windows(2) { if w[1] == w[0] + 1 { s += 5; } }
    }
    s -= (n - m) as i64;
    Some(s)
}
