fn wrap_count(text: &str, width: usize) -> usize {
    if width == 0 { return 1; }
    let mut lines = 1usize;
    let mut cur = 0usize;
    for word in text.split(' ') {
        let wl = word.chars().count();
        if cur == 0 {
            cur = wl;
        } else if cur + 1 + wl <= width {
            cur += 1 + wl;
        } else {
            lines += 1;
            cur = wl;
        }
        while cur > width {
            lines += 1;
            cur -= width;
        }
    }
    lines
}

