    let chunks = Layout::vertical([Constraint::Min(0), Constraint::Length(fh.min(area.height))]).split(area);
    let main_area = chunks[0];
    let footer_area = chunks[1];

    if app.fullscreen {
        if app.focus == Focus::Journals {
            draw_journals(frame, app, main_area);
