pub fn footer_text(app: &App) -> String {
    if app.focus == Focus::Editor && app.editor.mode == EditorMode::Edit {
        return "Back to Editor Normal Mode: 'Esc','<Ctrl-c>','<Ctrl-[>' |  Edit using Emacs motions".to_string();
    }
