fn draw_msgbox(frame: &mut Frame, app: &App, area: Rect) {
    let Some(msg) = &app.msgbox else { return };
    let rect = area_fixed(area, 55, 8);
    frame.render_widget(Clear, rect);
    let (color, title) = match msg.kind {
        MsgKind::Error => (app.styles.msgbox_error, Some("Error")),
        MsgKind::Info => (app.styles.msgbox_info, Some("Info")),
        MsgKind::Warning => (app.styles.msgbox_warning, Some("Warning")),
        MsgKind::Question => (app.styles.msgbox_question, None),
    };
    let style = Style::default().fg(color);
    let mut block = Block::default().borders(Borders::ALL).border_style(style).title_style(style).style(style);
    if let Some(t) = title { block = block.title(t); }
    let inner = block.inner(rect);
    frame.render_widget(block, rect);
    if inner.height < 4 { return; }
    // Text area: y+1, height 3
    let text_area = Rect { x: inner.x, y: inner.y + 1, width: inner.width, height: 3.min(inner.height) };
    let p = Paragraph::new(msg.text.clone()).alignment(Alignment::Center).wrap(Wrap { trim: true }).style(style);
    frame.render_widget(p, text_area);
    let buttons = match msg.buttons {
        MsgButtons::Ok => "(O)k",
        MsgButtons::YesNo => "(Y)es , (N)o",
        MsgButtons::YesNoCancel => "(Y)es , (N)o , (C)ancel",
    };
    let b_area = Rect { x: inner.x, y: inner.y + 4, width: inner.width, height: 1 };
    let bp = Paragraph::new(buttons).alignment(Alignment::Center).style(style);
    frame.render_widget(bp, b_area);
}
