fn wrap_count(text: &str, width: usize) -> usize {
    if width == 0 { return 1; }
    let mut lines = 1usize;
    let mut cur = 0usize;
    for word in text.split(' ') {
        let wl = word.chars().count();
        if cur == 0 {
            cur = wl;
        } else if cur + 1 + wl <= width {
            cur += 1 + wl;
        } else {
            lines += 1;
            cur = wl;
        }
        while cur > width {
            lines += 1;
            cur -= width;
        }
    }
    lines
}

pub fn draw(frame: &mut Frame, app: &mut App) {
    let area = frame.area();
    let ftext = footer_text(app);
    let fh = wrap_count(&ftext, area.width as usize).max(1) as u16;
    let chunks = Layout::vertical([Constraint::Min(0), Constraint::Length(fh.min(area.height))]).split(area);
    let main_area = chunks[0];
    let footer_area = chunks[1];

    if app.fullscreen {
        if app.focus == Focus::Journals {
            draw_journals(frame, app, main_area);
        } else {
            draw_content(frame, app, main_area);
        }
    } else {
        let cols = Layout::horizontal([Constraint::Percentage(30), Constraint::Percentage(70)]).split(main_area);
        draw_journals(frame, app, cols[0]);
        draw_content(frame, app, cols[1]);
    }

    let footer = Paragraph::new(ftext).wrap(Wrap { trim: true });
    frame.render_widget(footer, footer_area);

    // Popups
    // Need to take popup temporarily? draw takes &Popup via reference using app.popup.as_ref with app also mutable for list scroll in main already done.
    // We'll handle by rendering based on reference and cloning lightweight data where needed inside helpers that take &App.
    draw_popup(frame, app, area);
    draw_msgbox(frame, app, area);
}

fn block_style_for_journals(app: &App) -> Style {
    if app.multi_select {
        s(app.styles.journals_list.block_multi_select)
    } else if app.focus == Focus::Journals {
        s(app.styles.journals_list.block_active)
    } else {
        s(app.styles.journals_list.block_inactive)
    }
}

fn draw_journals(frame: &mut Frame, app: &mut App, area: Rect) {
    let title = if app.multi_select {
        "Journals - Multi-Select"
    } else if app.is_filtered() {
        "Journals - Filtered"
    } else {
        "Journals"
    };
    let bstyle = block_style_for_journals(app);
    let mut block = Block::default()
        .borders(Borders::ALL)
        .border_style(bstyle)
        .title_style(bstyle)
        .title(title);
    if let Some(idx) = app.selected_index {
        if !app.displayed.is_empty() {
            let bottom = format!("{}/{}", idx + 1, app.displayed.len());
            block = block.title_bottom(Line::from(bottom).right_aligned());
        }
    }
    let inner = block.inner(area);
    frame.render_widget(block, area);
    if app.displayed.is_empty() {
        let text = if app.multi_select { "No entries to select" } else { "Use 'n' to create new entry" };
        if inner.height > 1 && inner.width > 0 {
            let a = Rect { x: inner.x, y: inner.y + 1, width: inner.width, height: inner.height - 1 };
            let p = Paragraph::new(text).alignment(Alignment::Center).wrap(Wrap { trim: true });
            frame.render_widget(p, a);
        }
        return;
    }

    // Build visual lines
    #[derive(Clone)]
    struct VLine {
        spans: Vec<(String, Style)>,
        item_pos: usize,
        selected: bool,
    }
    let mut vlines: Vec<VLine> = Vec::new();
    let highlight = if app.focus == Focus::Journals {
        s(app.styles.journals_list.highlight_active)
    } else {
        s(app.styles.journals_list.highlight_inactive)
    };
    for (pos, entry) in app.displayed.iter().enumerate() {
        let is_sel = Some(pos) == app.selected_index;
        let is_multi_sel = app.multi_selected.contains(&entry.id);
        // logical lines: Vec<Vec<(text, style)>>
        let mut logical: Vec<Vec<(String, Style)>> = Vec::new();
        // Title
        let prefix = if app.multi_select {
            match (is_sel, is_multi_sel) {
                (true, true) => "> * ".to_string(),
                (true, false) => "> ".to_string(),
                (false, true) => "  * ".to_string(),
                (false, false) => "  ".to_string(),
            }
        } else if is_sel {
            "> ".to_string()
        } else {
            "  ".to_string()
        };
        let title_style = if app.multi_select && is_multi_sel {
            s(app.styles.journals_list.title_selected)
        } else if app.focus == Focus::Journals {
            s(app.styles.journals_list.title_active)
        } else {
            s(app.styles.journals_list.title_inactive)
        };
        logical.push(vec![(prefix, Style::default()), (entry.title.clone(), title_style)]);
        // Datum
        let datum_text: Option<String> = match app.settings.datum_visibility {
            DatumVisibility::Show => {
                let mut t = format!("{}, {}, {}", entry.date.format("%d"), entry.date.format("%m"), entry.date.format("%Y"));
                // Original format is d,m,Y without separators spaces: e.g. 31,12,2024
                t = format!("{},{},{}", entry.date.format("%d").to_string().trim_start_matches('0').if_empty("0"), entry.date.format("%m").to_string().trim_start_matches('0').if_empty("0"), entry.date.format("%Y"));
                if let Some(p) = entry.priority {
                    t = format!("{} | Priority: {}", t, p);
                }
                Some(t)
            }
            DatumVisibility::Hide => entry.priority.map(|p| format!("Priority: {}", p)),
            DatumVisibility::EmptyLine => {
                if let Some(p) = entry.priority {
                    Some(format!("Priority: {}", p))
                } else {
                    Some(String::new())
                }
            }
        };
        if let Some(dt) = datum_text {
            if dt.is_empty() {
                logical.push(vec![("  ".to_string(), Style::default()), (String::new(), Style::default())]);
            } else {
                logical.push(vec![("  ".to_string(), Style::default()), (dt, s(app.styles.journals_list.date_priority))]);
            }
        }
        // Tags
        if !entry.tags.is_empty() {
            let mut spans: Vec<(String, Style)> = vec![("  ".to_string(), Style::default())];
            if app.settings.colored_tags {
                for (i, tag) in entry.tags.iter().enumerate() {
                    if i > 0 {
                        spans.push((" | ".to_string(), s(app.styles.journals_list.tags_default)));
                    }
                    let bg = tag_color(tag);
                    spans.push((tag.clone(), Style::default().fg(Color::Black).bg(bg)));
                }
            } else {
                spans.push((entry.tags.join(" | "), s(app.styles.journals_list.tags_default)));
            }
            logical.push(spans);
        }
        for line_spans in logical {
            let wrapped = wrap_spans(line_spans, inner.width as usize);
            for w in wrapped {
                vlines.push(VLine { spans: w, item_pos: pos, selected: is_sel });
            }
        }
    }

    // Adjust scroll to keep selected visible
    if let Some(sel) = app.selected_index {
        let starts: Vec<usize> = vlines.iter().enumerate().filter(|(_, v)| v.item_pos == sel).map(|(i, _)| i).collect();
        if let (Some(&first), Some(&last)) = (starts.first(), starts.last()) {
            let h = inner.height as usize;
            if h > 0 {
                if first < app.list_scroll { app.list_scroll = first; }
                if last >= app.list_scroll + h { app.list_scroll = last + 1 - h; }
                let max_scroll = vlines.len().saturating_sub(h);
                if app.list_scroll > max_scroll && vlines.len() > h {
                    // Original List can scroll beyond? Keep max so last page full.
                    app.list_scroll = max_scroll;
                }
            }
        }
    } else {
        app.list_scroll = 0;
    }

    let buf = frame.buffer_mut();
    for row in 0..inner.height {
        let idx = app.list_scroll + row as usize;
        let y = inner.y + row;
        // base
        let (base_style, spans_opt) = if let Some(vl) = vlines.get(idx) {
            (if vl.selected { highlight } else { Style::default() }, Some(vl.clone()))
        } else {
            (Style::default(), None)
        };
        for x in inner.x..inner.right() {
            let cell = &mut buf[(x, y)];
            cell.set_char(' ');
            cell.set_style(base_style);
        }
        if let Some(vl) = spans_opt {
            let mut x = inner.x;
            for (text, st) in &vl.spans {
                for ch in text.chars() {
                    if x >= inner.right() { break; }
                    let cell = &mut buf[(x, y)];
                    cell.set_char(ch);
                    let mut style = *st;
                    if vl.selected { style = style.patch(highlight); }
                    cell.set_style(style);
                    x += 1;
                }
            }
        }
    }
    if vlines.len() > inner.height as usize && inner.width > 0 {
        let scrollbar_area = Rect { x: inner.right() - 1, y: inner.y, width: 1, height: inner.height };
        let mut state = ScrollbarState::new(vlines.len())
            .position(app.list_scroll)
            .viewport_content_length(inner.height as usize);
        let sb = Scrollbar::new(ScrollbarOrientation::VerticalRight)
            .symbols(ratatui_core::symbols::scrollbar::VERTICAL)
            .style(Style::default());
        frame.render_stateful_widget(sb, scrollbar_area, &mut state);
    }
}

trait IfEmpty { fn if_empty(self, v: &str) -> String; }
impl IfEmpty for &str {
    fn if_empty(self, v: &str) -> String { if self.is_empty() { v.to_string() } else { self.to_string() } }
}

pub fn tag_color(tag: &str) -> Color {
    // Deterministic palette based on a simple hash of the tag.
    let colors = [
        Color::LightGreen,
        Color::LightCyan,
        Color::LightRed,
        Color::LightYellow,
        Color::LightBlue,
        Color::LightMagenta,
        Color::Gray,
        Color::DarkGray,
        Color::Green,
        Color::Cyan,
        Color::Red,
        Color::Yellow,
        Color::Blue,
        Color::Magenta,
        Color::White,
    ];
    let mut h: u64 = 0;
    for b in tag.bytes() {
        h = h.wrapping_mul(31).wrapping_add(b as u64);
    }
    colors[(h % colors.len() as u64) as usize]
}

fn wrap_spans(spans: Vec<(String, Style)>, width: usize) -> Vec<Vec<(String, Style)>> {
    if width == 0 { return vec![spans]; }
    // Flatten to chars
    let mut chars: Vec<(char, Style)> = Vec::new();
    for (text, st) in &spans {
        for ch in text.chars() { chars.push((ch, *st)); }
    }
    // Tokenise into words/spaces preserving styles of each char; wrap greedily.
    // Build lines as char vecs.
    let mut lines: Vec<Vec<(char, Style)>> = Vec::new();
    let mut current: Vec<(char, Style)> = Vec::new();
    let mut i = 0usize;
    let default_style = spans.first().map(|s| s.1).unwrap_or_default();
    while i < chars.len() {
        // collect a word (sequence of non-space) plus following spaces? Use word + leading spaces handling.
        // Gather next word
        let mut word: Vec<(char, Style)> = Vec::new();
        // spaces before word are part of separator; if current not empty and next is space, handle in word loop below
        if chars[i].0 == ' ' {
            // collect spaces
            while i < chars.len() && chars[i].0 == ' ' {
                word.push(chars[i]);
                i += 1;
            }
            // if at line start after first line, spaces will be replaced by indent below
            if current.is_empty() {
                // keep original leading spaces for first segment; for continuation wrap we already add indent when starting line
                // If this is a continuation line (lines not empty), skip spaces (we use indent)
                if !lines.is_empty() {
                    continue;
                }
            }
            // if spaces fit
            if current.len() + word.len() <= width {
                current.extend(word);
            } else {
                // break line
                lines.push(current);
                current = vec![(' ', default_style), (' ', default_style)];
            }
            continue;
        } else {
            while i < chars.len() && chars[i].0 != ' ' {
                word.push(chars[i]);
                i += 1;
            }
        }
        if current.len() + word.len() <= width {
            current.extend(word);
        } else if word.len() > width {
            // hard break word
            let mut rest = word;
            while !rest.is_empty() {
                let avail = width.saturating_sub(current.len());
                if avail == 0 {
                    lines.push(current);
                    current = vec![(' ', default_style), (' ', default_style)];
                    continue;
                }
                let take = avail.min(rest.len());
                let tail = rest.split_off(take);
                current.extend(rest);
                rest = tail;
                if !rest.is_empty() {
                    lines.push(current);
                    current = vec![(' ', default_style), (' ', default_style)];
                }
            }
        } else {
            lines.push(current);
            current = vec![(' ', default_style), (' ', default_style)];
            // word may need stripping? keep
            current.extend(word);
        }
    }
    if !current.is_empty() || lines.is_empty() {
        lines.push(current);
    }
    // Convert to spans merging same style
    lines.into_iter().map(|line| {
        let mut out: Vec<(String, Style)> = Vec::new();
        for (ch, st) in line {
            if let Some(last) = out.last_mut() {
                if last.1 == st { last.0.push(ch); continue; }
            }
            out.push((ch.to_string(), st));
        }
        out
    }).collect()
}

fn draw_content(frame: &mut Frame, app: &mut App, area: Rect) {
    let (title, bstyle) = if app.focus == Focus::Editor {
        let mode_str = match app.editor.mode {
            EditorMode::Normal => "Content - NORMAL",
            EditorMode::Edit => "Content - EDIT",
            EditorMode::Visual => "Content - Visual",
        };
        let st = match app.editor.mode {
            EditorMode::Normal => s(app.styles.editor.block_normal_active),
            EditorMode::Edit => s(app.styles.editor.block_insert),
            EditorMode::Visual => s(app.styles.editor.block_visual),
        };
        (if app.editor.modified { format!("{} *", mode_str) } else { mode_str.to_string() }, st)
    } else {
        (if app.editor.modified { "Content *".to_string() } else { "Content".to_string() }, s(app.styles.editor.block_normal_inactive))
    };
    let block = Block::default().borders(Borders::ALL).border_style(bstyle).title_style(bstyle).title(title);
    let inner = block.inner(area);
    frame.render_widget(block, area);
    if inner.width == 0 || inner.height == 0 { return; }
    if app.focus == Focus::Editor {
        app.editor.ensure_cursor_visible(inner.height as usize, inner.width as usize);
    }
    let cursor_style = match app.editor.mode {
        EditorMode::Normal => s(app.styles.editor.cursor_normal),
        EditorMode::Edit => s(app.styles.editor.cursor_insert),
        EditorMode::Visual => s(app.styles.editor.cursor_visual),
    };
    let selection_style = s(app.styles.editor.selection_style);
    let sel_range = if app.editor.mode == EditorMode::Visual { app.editor.selection_range() } else { None };
    let buf = frame.buffer_mut();
    for row_vis in 0..inner.height {
        let row = app.editor.scroll_row + row_vis as usize;
        let y = inner.y + row_vis;
        if row >= app.editor.lines.len() { continue; }
        let line = app.editor.lines[row].clone();
        let chars: Vec<char> = line.chars().collect();
        let mut x = inner.x;
        let mut col = app.editor.scroll_col;
        while col < chars.len() && x < inner.right() {
            let ch = chars[col];
            // check selection
            let mut style = Style::default();
            if let Some((start, end)) = sel_range {
                // inclusive end
                let pos = (row, col);
                if pos >= start && pos <= end { style = selection_style; }
            }
            if app.focus == Focus::Editor && row == app.editor.row && col == app.editor.col {
                style = cursor_style;
            }
            let cell = &mut buf[(x, y)];
            if ch == '\t' {
                cell.set_char(' ');
            } else {
                cell.set_char(ch);
            }
            cell.set_style(style);
            x += 1;
            col += 1;
        }
        // cursor at end of line
        if app.focus == Focus::Editor && row == app.editor.row && app.editor.col == chars.len() {
            let cx = inner.x + (app.editor.col - app.editor.scroll_col) as u16;
            if cx < inner.right() {
                let cell = &mut buf[(cx, y)];
                cell.set_char(' ');
                cell.set_style(cursor_style);
            }
        }
    }
}

// ---------- Popup helpers ----------

fn area_percent(area: Rect, px: u16, py: u16) -> Rect {
    let v = Layout::vertical([
        Constraint::Percentage((100 - py) / 2),
        Constraint::Percentage(py),
        Constraint::Percentage((100 - py) / 2),
    ]).split(area);
    let h = Layout::horizontal([
        Constraint::Percentage((100 - px) / 2),
        Constraint::Percentage(px),
        Constraint::Percentage((100 - px) / 2),
    ]).split(v[1]);
    h[1]
}
fn area_fixed(area: Rect, px: u16, height: u16) -> Rect {
    let h = Layout::horizontal([
        Constraint::Percentage((100 - px) / 2),
        Constraint::Percentage(px),
        Constraint::Percentage((100 - px) / 2),
    ]).split(area);
    let wrect = h[1];
    let y = area.y + (area.height.saturating_sub(height) / 2);
    Rect { x: wrect.x, y, width: wrect.width, height: height.min(area.height) }
}

fn draw_input_block(frame: &mut Frame, area: Rect, title: &str, input: &mut super::input::TextInput, focused: bool, error: bool, app_styles: &crate::styles::Styles) {
    let style = if error {
        s(app_styles.general.input_block_invalid)
    } else if focused {
        s(app_styles.general.input_block_active)
    } else {
        Style::default()
    };
    let block = Block::default().borders(Borders::ALL).border_style(style).title_style(style).title(title.to_string());
    let inner = block.inner(area);
    frame.render_widget(block, area);
    if inner.width == 0 { return; }
    input.ensure_visible(inner.width as usize);
    let cursor_st = if error { s(app_styles.general.input_corsur_invalid) } else { s(app_styles.general.input_corsur_active) };
    let chars: Vec<char> = input.text.chars().collect();
    let buf = frame.buffer_mut();
    let mut x = inner.x;
    let mut idx = input.scroll;
    while idx < chars.len() && x < inner.right() {
        let cell = &mut buf[(x, inner.y)];
        cell.set_char(chars[idx]);
        cell.set_style(if focused && idx == input.cursor { cursor_st } else { Style::default() });
        x += 1;
        idx += 1;
    }
    if focused && input.cursor == chars.len() {
        let cx = inner.x + (input.cursor - input.scroll) as u16;
        if cx < inner.right() {
            let cell = &mut buf[(cx, inner.y)];
            cell.set_char(' ');
            cell.set_style(cursor_st);
        }
    } else if focused && input.cursor < chars.len() {
        // cursor char style already set above if visible; if cursor before scroll (shouldn't), ignore
        let cx = inner.x + input.cursor.saturating_sub(input.scroll) as u16;
        if input.cursor >= input.scroll && cx < inner.right() {
            let cell = &mut buf[(cx, inner.y)];
            cell.set_style(cursor_st);
        }
    }
}

fn input_title(name: &str, error: &Option<String>) -> String {
    if let Some(e) = error { format!("{} : {}", name, e) } else { name.to_string() }
}

fn draw_popup(frame: &mut Frame, app: &mut App, area: Rect) {
    // We need mutable access to inputs for scroll; popup is inside app; use raw split: take popup temporarily.
    // Instead this function receives &mut App and can access popup mutably via as_mut.
    if app.popup.is_none() { return; }
    // To avoid borrow conflicts with styles/settings (immutable refs while popup mut), clone styles (cheap-ish colors)
    // We'll process per popup kind by referencing fields sequentially.
    match app.popup.as_mut().unwrap() {
        Popup::EntryDialog(d) => draw_entry_dialog(frame, app, area, d),
        Popup::Filter(d) => draw_filter_dialog(frame, app, area, d),
        Popup::Sort(d) => draw_sort_dialog(frame, area, d, &app.styles),
        Popup::Fuzzy(d) => draw_fuzzy_dialog(frame, area, d, &app.styles, &app.displayed),
        Popup::Help(d) => draw_help(frame, area, d, &app.styles),
        Popup::Export(d) => draw_export_dialog(frame, area, d, &app.styles),
    }
}

fn draw_entry_dialog(frame: &mut Frame, app: &mut App, area: Rect, d: &mut super::EntryDialog) {
    let help_text = "Enter or <Ctrl-m>: confirm | Esc or <Ctrl-c>: Cancel | Tab: Change focused control | <Ctrl-Space> or <Ctrl-t>: Open tags";
    // width percent 70
    let width_area = area_percent(area, 70, 100);
    let help_w = width_area.width.saturating_sub(8) as usize;
    let help_lines = wrap_count(help_text, help_w.max(1)) as u16;
    let height = 16 + help_lines;
    let rect = area_fixed(area, 70, height);
    frame.render_widget(Clear, rect);
    let title = if d.is_create { "Create journal" } else { "Edit journal" };
    let block = Block::default().borders(Borders::ALL).title(title);
    let inner = block.inner(rect);
    frame.render_widget(block, rect);
    if inner.width < 8 { return; }
    let content = Rect { x: inner.x + 3, y: inner.y, width: inner.width - 6, height: inner.height };
    // Actually fields at dialog x+4: inner.x = rect.x+1, +3 => rect.x+4 correct.
    let chunks = Layout::vertical([
        Constraint::Length(1),
        Constraint::Length(3),
        Constraint::Length(3),
        Constraint::Length(3),
        Constraint::Length(3),
        Constraint::Length(help_lines),
    ]).split(content);
    let styles_clone = app.styles.clone();
    draw_input_block(frame, chunks[1], &input_title("Title", &d.title_error), &mut d.title, d.focused == EntryField::Title, d.title_error.is_some(), &styles_clone);
    draw_input_block(frame, chunks[2], &input_title("Date", &d.date_error), &mut d.date, d.focused == EntryField::Date, d.date_error.is_some(), &styles_clone);
    draw_input_block(frame, chunks[3], &input_title("Priority", &d.priority_error), &mut d.priority, d.focused == EntryField::Priority, d.priority_error.is_some(), &styles_clone);
    let tags_title = if d.focused == EntryField::Tags { "Tags - A comma-separated list".to_string() } else { "Tags".to_string() };
    draw_input_block(frame, chunks[4], &tags_title, &mut d.tags, d.focused == EntryField::Tags, false, &styles_clone);
    let help = Paragraph::new(help_text).alignment(Alignment::Center).wrap(Wrap { trim: true });
    frame.render_widget(help, chunks[5]);

    if let Some(tp) = &d.tags_popup {
        draw_tags_popup(frame, rect, tp, &styles_clone);
    }
}

fn draw_tags_popup(frame: &mut Frame, parent_rect: Rect, tp: &super::TagsPopup, styles: &crate::styles::Styles) {
    // Centered inside parent: 70% width, approx 70% height of parent
    let v = Layout::vertical([Constraint::Percentage(15), Constraint::Percentage(70), Constraint::Percentage(15)]).split(parent_rect);
    let h = Layout::horizontal([Constraint::Percentage(15), Constraint::Percentage(70), Constraint::Percentage(15)]).split(v[1]);
    let rect = h[1];
    frame.render_widget(Clear, rect);
    let block = Block::default().borders(Borders::ALL).border_type(BorderType::Rounded).title("Tags");
    let inner = block.inner(rect);
    frame.render_widget(block, rect);
    // Layout: list area + help (2 lines)
    if inner.height < 3 { return; }
    let help_text = "<Space>: Toggle Selected | Enter or <Ctrl-m>: Confirm | Esc, q or <Ctrl-c>: Cancel";
    let help_lines = wrap_count(help_text, inner.width as usize) as u16;
    let chunks = Layout::vertical([Constraint::Min(0), Constraint::Length(help_lines)]).split(inner);
    let buf = frame.buffer_mut();
    for (i, tag) in tp.all_tags.iter().enumerate() {
        if i >= chunks[0].height as usize { break; }
        let y = chunks[0].y + i as u16;
        let cursor = i == tp.cursor;
        let selected = tp.selected.contains(tag);
        let prefix = if cursor { ">>" } else { "  " };
        let text = if selected { format!("{} * {}", prefix, tag) } else { format!("{}   {}", prefix, tag) };
        // Actually selected non-cursor shows two spaces then *; format above gives "   * tag" for cursor false? prefix "  " + " * " = 5; we mimic observed: cursor ">> * tag", others "   * tag" (3 spaces) or "   tag"
        let text = if selected {
            if cursor { format!(">> * {}", tag) } else { format!("   * {}", tag) }
        } else {
            if cursor { format!(">> {}", tag) } else { format!("   {}", tag) }
        };
        let style = if cursor { s(styles.general.list_item_selected) } else { Style::default() };
        let mut x = chunks[0].x;
