fn help_table_lines(rows: &[(&str, &str, &str)], width: usize) -> Vec<String> {
    let c1 = (width * 20) / 100;
    let c2 = (width * 25) / 100;
    let c3 = width.saturating_sub(c1 + c2);
    let wrap_text = |text: &str, w: usize| -> Vec<String> {
        if w == 0 { return vec![String::new()]; }
        let mut lines = Vec::new();
        let mut cur = String::new();
        for word in text.split(' ') {
            if cur.is_empty() {
                if word.chars().count() > w {
                    // hard wrap
                    let mut rest = word.to_string();
                    while rest.chars().count() > w {
                        let part: String = rest.chars().take(w).collect();
                        lines.push(part);
                        rest = rest.chars().skip(w).collect();
                    }
                    cur = rest;
                } else { cur = word.to_string(); }
            } else if cur.chars().count() + 1 + word.chars().count() <= w {
                cur.push(' ');
                cur.push_str(word);
            } else {
                lines.push(cur);
                cur = word.to_string();
            }
        }
        lines.push(cur);
        lines
    };
    let mut out: Vec<String> = Vec::new();
    out.push(format!("{}{}{}", pad("Key", c1), pad("Command", c2), "Description"));
    out.push(String::new());
    for (k, cmd, desc) in rows {
        let ks = wrap_text(k, c1);
        let cs = wrap_text(cmd, c2);
        let ds = wrap_text(desc, c3);
        let h = ks.len().max(cs.len()).max(ds.len());
        for i in 0..h {
            out.push(format!("{}{}{}",
                pad(ks.get(i).map(|s| s.as_str()).unwrap_or(""), c1),
                pad(cs.get(i).map(|s| s.as_str()).unwrap_or(""), c2),
                ds.get(i).cloned().unwrap_or_default()));
        }
    }
    out
}
fn pad(s: &str, w: usize) -> String {
    let l = s.chars().count();
    if l >= w { s.to_string() } else { format!("{}{}", s, " ".repeat(w - l)) }
}

fn draw_help(frame: &mut Frame, area: Rect, d: &mut HelpState, styles: &crate::styles::Styles) {
    let rect = area_percent(area, 90, 80);
    frame.render_widget(Clear, rect);
    let block = Block::default().borders(Borders::ALL).title("Help");
    let inner = block.inner(rect);
    frame.render_widget(block, rect);
    if inner.width < 4 { return; }
    let content = Rect { x: inner.x + 1, y: inner.y, width: inner.width - 2, height: inner.height };
    let chunks = Layout::vertical([Constraint::Length(3), Constraint::Min(0)]).split(content);
    let tabs_titles = vec!["Global", "Editor", "Multi-Select"];
    let tabs_block = Block::default().borders(Borders::ALL).title("Tabs");
    let tabs = Tabs::new(tabs_titles)
        .block(tabs_block)
        .select(d.tab)
        .highlight_style(s(styles.general.list_item_selected))
        .style(Style::default());
    frame.render_widget(tabs, chunks[0]);
    let (btitle, lines, scroll): (String, Vec<String>, usize) = match d.tab {
        0 => ("Global Keybindings".to_string(), Vec::new(), d.global_scroll),
        1 => ("Editor Keybindings".to_string(), EDITOR_HELP_TEXT.iter().map(|s| s.to_string()).collect(), 0),
        _ => ("Multi-Select Mode Keybindings".to_string(), Vec::new(), d.multi_scroll),
    };
    let kblock = Block::default().borders(Borders::ALL).title(btitle);
    let kinner = kblock.inner(chunks[1]);
    frame.render_widget(kblock, chunks[1]);
    if d.tab == 1 {
        let p = Paragraph::new(lines.join("\n")).wrap(Wrap { trim: false });
        frame.render_widget(p, kinner);
        return;
    }
    let rows = if d.tab == 0 { GLOBAL_HELP } else { MULTI_HELP };
    let mut all_lines = help_table_lines(rows, kinner.width as usize);
    // Apply scroll clamp
    let view = kinner.height as usize;
    let max_scroll = all_lines.len().saturating_sub(view);
    let sc = scroll.min(max_scroll);
    // write back clamped scroll
    if d.tab == 0 { d.global_scroll = sc; } else if d.tab == 2 { d.multi_scroll = sc; }
    let visible: Vec<String> = all_lines.drain(..).skip(sc).take(view).collect();
    let buf = frame.buffer_mut();
    for (i, line) in visible.iter().enumerate() {
        let y = kinner.y + i as u16;
        let mut x = kinner.x;
        for ch in line.chars() {
            if x >= kinner.right() { break; }
            let cell = &mut buf[(x, y)];
            cell.set_char(ch);
            x += 1;
        }
    }
    if view > 0 && (all_lines_len(rows, kinner.width as usize) > view) {
        // scrollbar on right inner edge
        let total = help_table_lines(rows, kinner.width as usize).len();
        let sa = Rect { x: kinner.right() - 1, y: kinner.y, width: 1, height: kinner.height };
        let mut state = ScrollbarState::new(total).position(sc).viewport_content_length(view);
        let sb = Scrollbar::new(ScrollbarOrientation::VerticalRight).symbols(ratatui_core::symbols::scrollbar::VERTICAL);
        frame.render_stateful_widget(sb, sa, &mut state);
    }
}
fn all_lines_len(rows: &[(&str, &str, &str)], width: usize) -> usize { help_table_lines(rows, width).len() }

fn draw_export_dialog(frame: &mut Frame, area: Rect, d: &mut super::ExportDialog, styles: &crate::styles::Styles) {
    let rect = area_fixed(area, 70, 11);
