    let rows: Vec<ratatui_widgets::table::Row> = rows_data.iter().map(|(k, cmd, desc)| {
        let key_text = Text::from(Line::from(Span::styled(*k, Style::default().add_modifier(Modifier::ITALIC))));
        ratatui_widgets::table::Row::new(vec![
            ratatui_widgets::table::Cell::from(key_text),
            ratatui_widgets::table::Cell::from(*cmd),
            ratatui_widgets::table::Cell::from(*desc),
        ])
    }).collect();
    let _ = rows;
    let table = ratatui_widgets::table::Table::new(rows, [
        Constraint::Percentage(20),
        Constraint::Percentage(30),
        Constraint::Percentage(50),
    ])
    .header(header)
    .highlight_style(Style::default().add_modifier(Modifier::REVERSED))
    .highlight_symbol("");
    // Render statefully
    if d.tab == 0 {
        frame.render_stateful_widget(table, kinner, &mut d.global_state);
    } else {
        frame.render_stateful_widget(table, kinner, &mut d.multi_state);
    }
    // Scrollbar based on table state offset
    let (offset, total_rows) = if d.tab == 0 {
        (d.global_state.offset(), GLOBAL_HELP.len())
    } else {
        (d.multi_state.offset(), MULTI_HELP.len())
    };
    // Estimate total physical lines > view?
    let sa = Rect { x: kinner.right() - 1, y: kinner.y, width: 1, height: kinner.height };
    let mut sb_state = ScrollbarState::new(total_rows * 2).position(offset).viewport_content_length(kinner.height as usize);
    let sb = Scrollbar::new(ScrollbarOrientation::VerticalRight).symbols(ratatui_core::symbols::scrollbar::VERTICAL);
    frame.render_stateful_widget(sb, sa, &mut sb_state);
}
