    frame.render_widget(kblock, chunks[1]);
    if d.tab == 1 {
        let lines: Vec<String> = EDITOR_HELP_TEXT.iter().map(|s| s.to_string()).collect();
        let para = Paragraph::new(lines.join("\\n")).wrap(Wrap { trim: false });
        frame.render_widget(para, kinner);
        return;
    }
    let rows_data = if d.tab == 0 { GLOBAL_HELP } else { MULTI_HELP };
    // Column widths: spacing 1 between columns
    let width = kinner.width as usize;
    if width < 4 || kinner.height < 3 { return; }
    let c1 = ((width - 2) * 18) / 100;
    let c2 = ((width - 2) * 28) / 100;
    let c3 = width.saturating_sub(c1 + c2 + 2);
    let wrap_cell = |text: &str, w: usize| -> Vec<String> {
        if w == 0 { return vec![String::new()]; }
        let mut lines: Vec<String> = Vec::new();
        let mut cur = String::new();
        for word in text.split(' ') {
            if cur.is_empty() {
                if word.chars().count() > w {
                    let mut rest = word.to_string();
                    while rest.chars().count() > w {
                        lines.push(rest.chars().take(w).collect());
                        rest = rest.chars().skip(w).collect();
                    }
                    cur = rest;
                } else { cur = word.to_string(); }
            } else if cur.chars().count() + 1 + word.chars().count() <= w {
                cur.push(' '); cur.push_str(word);
            } else {
                lines.push(cur);
                if word.chars().count() > w {
                    let mut rest = word.to_string();
                    while rest.chars().count() > w {
                        lines.push(rest.chars().take(w).collect());
                        rest = rest.chars().skip(w).collect();
                    }
                    cur = rest;
                } else { cur = word.to_string(); }
            }
        }
        lines.push(cur);
        lines
    };
    // Build physical lines per row
    struct RowLine { text_cols: (String, String, String), row: usize }
    let mut row_lines: Vec<RowLine> = Vec::new();
    let mut row_starts: Vec<usize> = Vec::new();
    for (ri, (k, cmd, desc)) in rows_data.iter().enumerate() {
        row_starts.push(row_lines.len());
        let ks = wrap_cell(k, c1);
        let cs = wrap_cell(cmd, c2);
        let ds = wrap_cell(desc, c3);
        let h = ks.len().max(cs.len()).max(ds.len());
        for i in 0..h {
            row_lines.push(RowLine {
                text_cols: (
                    ks.get(i).cloned().unwrap_or_default(),
                    cs.get(i).cloned().unwrap_or_default(),
                    ds.get(i).cloned().unwrap_or_default(),
                ),
                row: ri,
            });
        }
    }
    let total_lines = row_lines.len();
    let view = (kinner.height as usize).saturating_sub(2);
    if view == 0 { return; }
    // clamp selected and update offset (row-based)
    let (selected_opt, offset_ref) = if d.tab == 0 {
        (&mut d.global_selected, &mut d.global_offset)
    } else {
        (&mut d.multi_selected, &mut d.multi_offset)
    };
    if let Some(sel) = selected_opt {
        if *sel >= rows_data.len() { *sel = rows_data.len() - 1; }
    }
    if let Some(sel) = *selected_opt {
        let sel_start = row_starts[sel];
        let sel_end = if sel + 1 < row_starts.len() { row_starts[sel + 1] - 1 } else { total_lines - 1 };
        if sel_start < *offset_ref { *offset_ref = sel_start; }
        if sel_end >= *offset_ref + view { *offset_ref = sel_end + 1 - view; }
    }
    let offset = *offset_ref;
    let selected = *selected_opt;
    // Header
    let buf = frame.buffer_mut();
    let header_style = s(styles.journals_list.date_priority);
    let header_cols = [("Key", c1), ("Command", c2), ("Description", c3)];
    let mut hx = kinner.x;
    for (i, (txt, w)) in header_cols.iter().enumerate() {
        for ch in txt.chars() {
            if hx < kinner.right() { let cell = &mut buf[(hx, kinner.y)]; cell.set_char(ch); cell.set_style(header_style); hx += 1; }
        }
        let used = txt.chars().count();
        for _ in used..*w { if hx < kinner.right() { let cell = &mut buf[(hx, kinner.y)]; cell.set_char(' '); cell.set_style(header_style); hx += 1; } }
        if i < 2 { if hx < kinner.right() { let cell = &mut buf[(hx, kinner.y)]; cell.set_char(' '); hx += 1; } }
    }
    // Rows
    for vi in 0..view {
        let li = offset + vi;
        if li >= total_lines { break; }
        let y = kinner.y + 2 + vi as u16;
        let rl = &row_lines[li];
        let is_sel = selected == Some(rl.row);
        let cols = [(rl.text_cols.0.clone(), true), (rl.text_cols.1.clone(), false), (rl.text_cols.2.clone(), false)];
        let widths = [c1, c2, c3];
        let mut x = kinner.x;
        for (ci, (txt, is_key)) in cols.iter().enumerate() {
            let w = widths[ci];
            // text
            for ch in txt.chars() {
                if x >= kinner.right() { break; }
                let cell = &mut buf[(x, y)];
                cell.set_char(ch);
                let mut st = Style::default();
                if *is_key { st = st.add_modifier(Modifier::ITALIC); }
                if is_sel { st = st.add_modifier(Modifier::REVERSED); }
                cell.set_style(st);
                x += 1;
            }
            // padding
            let used = txt.chars().count();
            for _ in used..w {
                if x >= kinner.right() { break; }
                let cell = &mut buf[(x, y)];
                cell.set_char(' ');
                let mut st = Style::default();
                if is_sel { st = st.add_modifier(Modifier::REVERSED); }
                cell.set_style(st);
                x += 1;
            }
            if ci < 2 {
                if x < kinner.right() {
                    let cell = &mut buf[(x, y)];
                    cell.set_char(' ');
                    if is_sel { cell.set_style(Style::default().add_modifier(Modifier::REVERSED)); }
                    x += 1;
                }
            }
        }
        // Reversed should cover full width (except scrollbar col) if selected
        if is_sel {
            while x < kinner.right().saturating_sub(1) {
                let cell = &mut buf[(x, y)];
                cell.set_char(' ');
                cell.set_style(Style::default().add_modifier(Modifier::REVERSED));
                x += 1;
            }
        }
    }
    if total_lines > view {
        let sa = Rect { x: kinner.right() - 1, y: kinner.y, width: 1, height: kinner.height };
        let mut sb_state = ScrollbarState::new(total_lines).position(offset).viewport_content_length(view);
        let sb = make_scrollbar();
        frame.render_stateful_widget(sb, sa, &mut sb_state);
    }
}
