        if d.query.handle_key(key.code, key.modifiers) {
            self.recompute_fuzzy(d);
        }
        false
    }

    fn recompute_fuzzy(&self, d: &mut FuzzyDialog) {
        d.cursor = 0;
        if d.query.text.is_empty() {
            d.results = Vec::new();
            return;
        }
        let mut scored: Vec<(i64, usize, u32)> = Vec::new();
        for (idx, e) in self.displayed.iter().enumerate() {
            if let Some(score) = fuzzy_score(&e.title, &d.query.text) {
                scored.push((score, idx, e.id));
            }
        }
        scored.sort_by(|a, b| b.0.cmp(&a.0).then(a.1.cmp(&b.1)));
        d.results = scored.into_iter().map(|s| s.2).collect();
    }

    fn help_key(&mut self, d: &mut HelpState, key: KeyEvent) -> bool {
        match key.code {
            KeyCode::Char('q') | KeyCode::Esc => return true,
            KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => return true,
            KeyCode::Tab => { d.tab = (d.tab + 1) % 3; return false; }
            KeyCode::BackTab => { d.tab = (d.tab + 2) % 3; return false; }
            KeyCode::Right | KeyCode::Char('l') => { d.tab = (d.tab + 1) % 3; return false; }
            KeyCode::Left | KeyCode::Char('h') => { d.tab = (d.tab + 2) % 3; return false; }
            KeyCode::Down | KeyCode::Char('j') => {
                if d.tab == 0 {
                    d.global_selected = Some(match d.global_selected { None => 0, Some(i) => i + 1 });
                } else if d.tab == 2 {
                    d.multi_selected = Some(match d.multi_selected { None => 0, Some(i) => i + 1 });
                }
                return false;
            }
            KeyCode::Up | KeyCode::Char('k') => {
                if d.tab == 0 {
                    d.global_selected = Some(match d.global_selected { None => crate::app::ui::GLOBAL_HELP.len() - 1, Some(i) => i.saturating_sub(1) });
                } else if d.tab == 2 {
                    d.multi_selected = Some(match d.multi_selected { None => crate::app::ui::MULTI_HELP.len() - 1, Some(i) => i.saturating_sub(1) });
                }
                return false;
            }
            KeyCode::PageDown => {
                if d.tab == 0 {
                    let cur = d.global_selected.unwrap_or(0);
                    d.global_selected = Some(cur + 10);
                } else if d.tab == 2 {
                    let cur = d.multi_selected.unwrap_or(0);
                    d.multi_selected = Some(cur + 10);
                }
                return false;
            }
            KeyCode::PageUp => {
                if d.tab == 0 {
                    let cur = d.global_selected.unwrap_or(0);
                    d.global_selected = Some(cur.saturating_sub(10));
                } else if d.tab == 2 {
                    let cur = d.multi_selected.unwrap_or(0);
                    d.multi_selected = Some(cur.saturating_sub(10));
                }
                return false;
            }
            _ => {}
        }
        false
    }

