        match key.code {
            KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                return true;
            }
            KeyCode::Enter | KeyCode::Esc => {
                if let Some(id) = d.results.get(d.cursor).cloned() {
                    if let Some(pos) = self.displayed.iter().position(|e| e.id == id) {
                        self.selected_index = Some(pos);
                        if !self.editor.modified {
                            if let Some(entry) = self.current_entry().cloned() { self.load_editor_for(&entry); }
                        }
                    }
                }
                return true;
            }
            KeyCode::Char('m') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                if let Some(id) = d.results.get(d.cursor).cloned() {
                    if let Some(pos) = self.displayed.iter().position(|e| e.id == id) {
                        self.selected_index = Some(pos);
                        if !self.editor.modified {
                            if let Some(entry) = self.current_entry().cloned() { self.load_editor_for(&entry); }
                        }
                    }
                }
                return true;
            }
            KeyCode::Down => { if d.cursor + 1 < d.results.len() { d.cursor += 1; } return false; }
            KeyCode::Up => { if d.cursor > 0 { d.cursor -= 1; } return false; }
            KeyCode::Char('n') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                if d.cursor + 1 < d.results.len() { d.cursor += 1; }
                return false;
            }
            KeyCode::Char('p') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                if d.cursor > 0 { d.cursor -= 1; }
                return false;
            }
            _ => {}
        }
        if d.query.handle_key(key.code, key.modifiers) {
            self.recompute_fuzzy(d);
        }
        false
    }

    fn recompute_fuzzy(&self, d: &mut FuzzyDialog) {
        d.cursor = 0;
        if d.query.text.is_empty() {
            d.results = Vec::new();
            return;
        }
        let mut scored: Vec<(i64, usize, u32)> = Vec::new();
        for (idx, e) in self.displayed.iter().enumerate() {
            if let Some(score) = fuzzy_score(&e.title, &d.query.text) {
                scored.push((score, idx, e.id));
            }
        }
        scored.sort_by(|a, b| b.0.cmp(&a.0).then(a.1.cmp(&b.1)));
        d.results = scored.into_iter().map(|s| s.2).collect();
    }

