        let mut lines: Vec<String> = Vec::new();
        let mut cur = String::new();
        let mut cur_len = 0usize;
        for tok in tokens {
            let tok_trim = tok.trim_end();
            let tok_len = tok.chars().count();
            let effective = if tok.ends_with(' ') { tok_len - 1 } else { tok_len };
            if cur_len == 0 {
                // start of line: skip leading spaces
                let t = tok.trim_start();
                if t.is_empty() { continue; }
                if t.chars().count() > w {
                    // hard break
                    let mut rest = t.to_string();
                    while rest.chars().count() > w {
                        lines.push(rest.chars().take(w).collect());
                        rest = rest.chars().skip(w).collect();
                    }
                    cur = rest;
                    cur_len = cur.chars().count();
                } else {
                    cur = t.to_string();
                    cur_len = cur.chars().count();
                    // preserve internal trailing hyphen etc; spaces are separators added when next token comes
                    if tok.ends_with(' ') { cur.push(' '); cur_len += 1; }
