            let need = if cur.ends_with(' ') { effective } else { effective };
            if cur_len + need <= w {
                cur.push_str(tok_trim);
                cur_len += need;
                if tok.ends_with(' ') && cur_len < w { cur.push(' '); cur_len += 1; }
            } else {
                // If token is long, fill remaining space (ratatui breaks words)
                let avail = w.saturating_sub(cur_len);
                let t = tok_trim;
                if avail > 0 && t.chars().count() > avail && !tok.starts_with(' ') {
                    let part: String = t.chars().take(avail).collect();
                    cur.push_str(&part);
                    lines.push(cur.trim_end().to_string());
                    let rest: String = t.chars().skip(avail).collect();
                    // rest starts new line; may still be > w
                    let mut r = rest;
                    while r.chars().count() > w {
                        lines.push(r.chars().take(w).collect());
                        r = r.chars().skip(w).collect();
                    }
                    cur = r;
                    cur_len = cur.chars().count();
                    if tok.ends_with(' ') && cur_len > 0 && cur_len < w { cur.push(' '); cur_len += 1; }
                } else {
                    lines.push(cur.trim_end().to_string());
                    let t = tok.trim_start();
                    cur = t.to_string();
                    cur_len = cur.chars().count();
                    if tok.ends_with(' ') && cur_len > 0 && cur_len < w { cur.push(' '); cur_len += 1; }
                }
            }
        }
        lines.push(cur.trim_end().to_string());
        if lines.is_empty() { lines.push(String::new()); }
        lines
    }
    struct RowLine { text_cols: (String, String, String), row: usize }
    let mut row_lines: Vec<RowLine> = Vec::new();
    let mut row_starts: Vec<usize> = Vec::new();
    let mut row_heights: Vec<usize> = Vec::new();
    for (ri, (k, cmd, desc)) in rows_data.iter().enumerate() {
