            if used <= view { break; }
            *offset_ref += 1;
            if *offset_ref > sel { break; }
        }
    }
    let offset_row = *offset_ref;
    let offset_lines = row_starts.get(offset_row).cloned().unwrap_or(0);
    let selected = *selected_opt;
    // Header
    let buf = frame.buffer_mut();
    let header_style = s(styles.journals_list.date_priority);
    let header_cols = [("Key", c1), ("Command", c2), ("Description", c3)];
    let mut hx = kinner.x;
    for (i, (txt, w)) in header_cols.iter().enumerate() {
        for ch in txt.chars() {
            if hx < table_right { let cell = &mut buf[(hx, kinner.y)]; cell.set_char(ch); cell.set_style(header_style); hx += 1; }
        }
        let used = txt.chars().count();
        for _ in used..*w { if hx < table_right { let cell = &mut buf[(hx, kinner.y)]; cell.set_char(' '); cell.set_style(header_style); hx += 1; } }
        if i < 2 { if hx < table_right { let cell = &mut buf[(hx, kinner.y)]; cell.set_char(' '); hx += 1; } }
    }
    // Rows: only whole rows that fit
    let mut y_offset = 0usize;
    let mut r = offset_row;
    while r < rows_data.len() {
        let h = row_heights[r];
        if y_offset + h > view { break; }
        for i in 0..h {
            let li = row_starts[r] + i;
            let y = kinner.y + 2 + (y_offset + i) as u16;
            let rl = &row_lines[li];
            let is_sel = selected == Some(rl.row);
            let cols = [(rl.text_cols.0.clone(), true), (rl.text_cols.1.clone(), false), (rl.text_cols.2.clone(), false)];
            let widths = [c1, c2, c3];
            let mut x = kinner.x;
            for (ci, (txt, is_key)) in cols.iter().enumerate() {
                let w = widths[ci];
                for ch in txt.chars() {
                    if x >= table_right { break; }
                    let cell = &mut buf[(x, y)];
                    cell.set_char(ch);
                    let mut st = Style::default();
                    if *is_key { st = st.add_modifier(Modifier::ITALIC); }
                    if is_sel { st = st.add_modifier(Modifier::REVERSED); }
                    cell.set_style(st);
                    x += 1;
                }
                let used = txt.chars().count();
                for _ in used..w {
                    if x >= table_right { break; }
                    let cell = &mut buf[(x, y)];
                    cell.set_char(' ');
                    let mut st = Style::default();
                    if is_sel { st = st.add_modifier(Modifier::REVERSED); }
                    cell.set_style(st);
                    x += 1;
                }
                if ci < 2 {
                    if x < table_right {
                        let cell = &mut buf[(x, y)];
                        cell.set_char(' ');
                        if is_sel { cell.set_style(Style::default().add_modifier(Modifier::REVERSED)); }
                        x += 1;
                    }
                }
            }
            if is_sel {
                while x < table_right {
                    let cell = &mut buf[(x, y)];
                    cell.set_char(' ');
                    cell.set_style(Style::default().add_modifier(Modifier::REVERSED));
                    x += 1;
                }
            }
        }
        y_offset += h;
        r += 1;
    }
    if has_scrollbar {
        let sa = Rect { x: kinner.right() - 1, y: kinner.y, width: 1, height: kinner.height };
        let mut sb_state = ScrollbarState::new(total_lines).position(offset_lines).viewport_content_length(view);
        let sb = make_scrollbar();
        frame.render_stateful_widget(sb, sa, &mut sb_state);
    }
}
