fn draw_help(frame: &mut Frame, area: Rect, d: &mut HelpState, styles: &crate::styles::Styles) {
    let rect = area_percent(area, 90, 80);
    frame.render_widget(Clear, rect);
    let block = Block::default().borders(Borders::ALL).title("Help");
    let inner = block.inner(rect);
    frame.render_widget(block, rect);
    if inner.width < 4 { return; }
    let content = Rect { x: inner.x + 1, y: inner.y, width: inner.width - 2, height: inner.height };
    let chunks = Layout::vertical([Constraint::Length(3), Constraint::Min(0)]).split(content);
    let tabs_titles = vec!["Global", "Editor", "Multi-Select"];
    let tabs_block = Block::default().borders(Borders::ALL).title("Tabs");
    let tabs = Tabs::new(tabs_titles)
        .block(tabs_block)
        .select(d.tab)
        .highlight_style(s(styles.general.list_item_selected))
        .style(Style::default());
    frame.render_widget(tabs, chunks[0]);
    let btitle = match d.tab {
        0 => "Global Keybindings",
        1 => "Editor Keybindings",
        _ => "Multi-Select Mode Keybindings",
    };
    let kblock = Block::default().borders(Borders::ALL).title(btitle);
    let kinner = kblock.inner(chunks[1]);
    frame.render_widget(kblock, chunks[1]);
    if d.tab == 1 {
        let lines: Vec<String> = EDITOR_HELP_TEXT.iter().map(|s| s.to_string()).collect();
        let para = Paragraph::new(lines.join("\n")).wrap(Wrap { trim: false });
        frame.render_widget(para, kinner);
        return;
    }
    let rows_data = if d.tab == 0 { GLOBAL_HELP } else { MULTI_HELP };
    let full_width = kinner.width as usize;
    if full_width < 4 || kinner.height < 3 { return; }
    let c1 = ((full_width * 18) + 50) / 100;
    let c2 = (full_width * 28) / 100;
    let c3 = (full_width * 49) / 100;
    fn wrap_cell2(text: &str, w: usize) -> Vec<String> {
        if w == 0 { return vec![String::new()]; }
        #[derive(Clone)]
        struct Atom { text: String, space_before: bool }
        let mut atoms: Vec<Atom> = Vec::new();
        for (wi, word) in text.split(' ').enumerate() {
            if word.is_empty() { continue; }
            let chars: Vec<char> = word.chars().collect();
            let mut start = 0usize;
            for i in 0..chars.len() {
                if chars[i] == '-' {
                    let part: String = chars[start..=i].iter().collect();
                    atoms.push(Atom { text: part, space_before: wi > 0 && start == 0 });
                    start = i + 1;
                }
            }
            if start < chars.len() {
                let part: String = chars[start..].iter().collect();
                atoms.push(Atom { text: part, space_before: wi > 0 && start == 0 });
            }
        }
        let mut lines: Vec<String> = Vec::new();
        let mut cur = String::new();
        let mut cur_len = 0usize;
        for atom in atoms {
            let alen = atom.text.chars().count();
            let space = if atom.space_before && cur_len > 0 { 1 } else { 0 };
            if cur_len + space + alen <= w {
                if space == 1 { cur.push(' '); cur_len += 1; }
                cur.push_str(&atom.text);
                cur_len += alen;
            } else if alen > w {
                let mut rest = atom.text.clone();
                if cur_len > 0 {
                    let avail = w.saturating_sub(cur_len + space);
                    if avail > 0 {
                        if space == 1 { cur.push(' '); }
                        cur.push_str(&rest.chars().take(avail).collect::<String>());
                        rest = rest.chars().skip(avail).collect();
                    }
                    lines.push(cur);
                    cur = String::new();
                    cur_len = 0;
                }
                while rest.chars().count() > w {
                    lines.push(rest.chars().take(w).collect());
                    rest = rest.chars().skip(w).collect();
                }
                cur = rest;
                cur_len = cur.chars().count();
            } else {
                lines.push(cur);
                cur = atom.text.clone();
                cur_len = alen;
            }
        }
        lines.push(cur);
        if lines.is_empty() { lines.push(String::new()); }
        lines
    }
    struct RowLine { cols: (String, String, String), row: usize }
    let mut row_lines: Vec<RowLine> = Vec::new();
    let mut row_starts: Vec<usize> = Vec::new();
    let mut row_heights: Vec<usize> = Vec::new();
    for (ri, (k, cmd, desc)) in rows_data.iter().enumerate() {
        row_starts.push(row_lines.len());
        let ks = wrap_cell2(k, c1);
        let cs = wrap_cell2(cmd, c2);
        let ds = wrap_cell2(desc, c3);
        let h = ks.len().max(cs.len()).max(ds.len());
        row_heights.push(h);
        for i in 0..h {
            row_lines.push(RowLine { cols: (ks.get(i).cloned().unwrap_or_default(), cs.get(i).cloned().unwrap_or_default(), ds.get(i).cloned().unwrap_or_default()), row: ri });
        }
    }
    let total_lines = row_lines.len();
    let view = (kinner.height as usize).saturating_sub(2);
    if view == 0 { return; }
    let has_scrollbar = total_lines > view;
    let table_right = if has_scrollbar { kinner.right().saturating_sub(1) } else { kinner.right() };
    let (selected_opt, offset_ref) = if d.tab == 0 { (&mut d.global_selected, &mut d.global_offset) } else { (&mut d.multi_selected, &mut d.multi_offset) };
    if let Some(sel) = selected_opt {
        if *sel >= rows_data.len() { *sel = rows_data.len() - 1; }
    }
    if *offset_ref >= rows_data.len() { *offset_ref = rows_data.len().saturating_sub(1); }
    if let Some(sel) = *selected_opt {
        if sel < *offset_ref { *offset_ref = sel; }
        loop {
            let mut used = 0usize;
            for r in *offset_ref..=sel { used += row_heights[r]; }
            if used <= view { break; }
            *offset_ref += 1;
            if *offset_ref > sel { break; }
        }
    }
    let offset_row = *offset_ref;
    let offset_lines = row_starts.get(offset_row).cloned().unwrap_or(0);
    let selected = *selected_opt;
    let buf = frame.buffer_mut();
    let header_style = s(styles.journals_list.date_priority);
    let header_cols = [("Key", c1), ("Command", c2), ("Description", c3)];
    let mut hx = kinner.x;
    for (i, (txt, w)) in header_cols.iter().enumerate() {
        for ch in txt.chars() {
            if hx < table_right { let cell = &mut buf[(hx, kinner.y)]; cell.set_char(ch); cell.set_style(header_style); hx += 1; }
        }
        let used = txt.chars().count();
        for _ in used..*w { if hx < table_right { let cell = &mut buf[(hx, kinner.y)]; cell.set_char(' '); cell.set_style(header_style); hx += 1; } }
        if i < 2 && hx < table_right { let cell = &mut buf[(hx, kinner.y)]; cell.set_char(' '); hx += 1; }
    }
    let mut y_offset = 0usize;
    let mut r = offset_row;
    while r < rows_data.len() {
        let h = row_heights[r];
        if y_offset + h > view { break; }
        for i in 0..h {
            let li = row_starts[r] + i;
            let y = kinner.y + 2 + (y_offset + i) as u16;
            let rl = &row_lines[li];
            let is_sel = selected == Some(rl.row);
            let cols = [(rl.cols.0.clone(), true), (rl.cols.1.clone(), false), (rl.cols.2.clone(), false)];
            let widths = [c1, c2, c3];
            let mut x = kinner.x;
            for (ci, (txt, is_key)) in cols.iter().enumerate() {
                let w = widths[ci];
                for ch in txt.chars() {
                    if x >= table_right { break; }
                    let cell = &mut buf[(x, y)];
                    cell.set_char(ch);
                    let mut st = Style::default();
                    if *is_key { st = st.add_modifier(Modifier::ITALIC); }
                    if is_sel { st = st.add_modifier(Modifier::REVERSED); }
                    cell.set_style(st);
                    x += 1;
                }
                let used = txt.chars().count();
                for _ in used..w {
                    if x >= table_right { break; }
                    let cell = &mut buf[(x, y)];
                    cell.set_char(' ');
                    let mut st = Style::default();
                    if is_sel { st = st.add_modifier(Modifier::REVERSED); }
                    cell.set_style(st);
                    x += 1;
                }
                if ci < 2 && x < table_right {
                    let cell = &mut buf[(x, y)];
                    cell.set_char(' ');
                    if is_sel { cell.set_style(Style::default().add_modifier(Modifier::REVERSED)); }
                    x += 1;
                }
            }
            if is_sel {
                while x < table_right {
                    let cell = &mut buf[(x, y)];
                    cell.set_char(' ');
                    cell.set_style(Style::default().add_modifier(Modifier::REVERSED));
                    x += 1;
                }
            }
        }
        y_offset += h;
        r += 1;
    }
    if has_scrollbar {
        let sa = Rect { x: kinner.right() - 1, y: kinner.y, width: 1, height: kinner.height };
        let mut sb_state = ScrollbarState::new(total_lines).position(offset_lines).viewport_content_length(view);
        let sb = make_scrollbar();
        frame.render_stateful_widget(sb, sa, &mut sb_state);
    }
}
