                current = vec![(' ', default_style), (' ', default_style)];
            }
            continue;
        } else {
            while i < chars.len() && chars[i].0 != ' ' {
                word.push(chars[i]);
                i += 1;
            }
        }
        if current.len() + word.len() <= width {
            current.extend(word);
        } else if word.len() > width {
            let mut rest = word;
            while !rest.is_empty() {
                let avail = width.saturating_sub(current.len());
                if avail == 0 {
                    lines.push(current);
                    current = vec![(' ', default_style), (' ', default_style)];
                    continue;
                }
                let take = avail.min(rest.len());
                let tail = rest.split_off(take);
                current.extend(rest);
