                let mut acc = 0usize;
                for (c, _) in rest.iter() {
                    let w = cw(*c);
                    if acc + w > avail { break; }
                    acc += w;
                    take += 1;
                }
                if take == 0 {
                    if current.is_empty() {
                        take = 1;
                    } else {
                        lines.push(current);
                        current = vec![(' ', default_style), (' ', default_style)];
                        continue;
                    }
                }
                let tail = rest.split_off(take);
                current.extend(rest);
                rest = tail;
                if !rest.is_empty() {
                    lines.push(current);
                    current = vec![(' ', default_style), (' ', default_style)];
                }
            }
        } else {
            lines.push(current);
            current = vec![(' ', default_style), (' ', default_style)];
            current.extend(word);
        }
    }
    if !current.is_empty() || lines.is_empty() {
        lines.push(current);
    }
    lines.into_iter().map(|line| {
        let mut out: Vec<(String, Style)> = Vec::new();
        for (ch, st) in line {
            if let Some(last) = out.last_mut() {
                if last.1 == st { last.0.push(ch); continue; }
            }
            out.push((ch.to_string(), st));
        }
        out
    }).collect()
}

