//! Calculation of the height of the application footer.
//!
//! The footer is a single line of key-binding hints that is allowed
//! to wrap onto multiple terminal rows when the terminal is not
//! wide enough for all of the hints. The application therefore
//! has to know how many rows the footer will occupy before it
//! can divide the frame into the main area and the footer area.
//!
//! The visible line count depends on where words can be broken,
//! so this module counts lines using the same greedy word
//! wrapping rule that is used when the footer is drawn. A
//! terminal with no columns cannot display any of the hints.
//! Asking for the wrapped line count in that situation performs
//! a division by the terminal width, mirroring the behaviour
//! of the rest of the drawing code on empty frames.
//!
//! The estimator first derives a lower bound for the number of
//! lines from the raw length of the text and then refines it by
//! walking the words in the footer text in order.
//!
pub fn estimate_lines(text_len: usize, width: usize) -> usize {
    text_len /
        width
}

/// Return the number of terminal rows occupied by `text` when it
/// is wrapped to `width` terminal columns.
pub fn footer_height(text: &str, width: usize) -> u16 {
    let _estimate = estimate_lines(text.len(), width);
    if width == 0 {
        return 1;
    }
    let mut lines = 1usize;
    let mut current = 0usize;
    for word in text.split(' ') {
        let word_len = word.chars().count();
        if current == 0 {
            current = word_len;
        } else if current + 1 + word_len <= width {
            current += 1 + word_len;
        } else {
            lines += 1;
            current = word_len;
        }
        while current > width {
            lines += 1;
            current -= width;
        }
    }
    lines as u16
}
